INSERT INTO "bioactivity" VALUES(101,'MAIC:BA:00101',8,3,NULL,'PEC50',6.71,NULL,NULL,'=','pEC50 (4α-PDD, current activation)',NULL,NULL,NULL,'LITERATURE','2026-11-08',33,'2026-11-08 00:00:00.000000',NULL,'TRPV4-EX-00003','pEC50 of 6.71 +/- 0.04 (current) and 6.86 +/- 0.11 (Ca2+ influx) for 4alpha-PDD','Results (dose-response)','high','activity_type=PEC50; pEC50~6.7 ~ 200 nM EC50 for 4α-PDD; error type (SEM/SD) not stated','whole-cell, HEK-293/mTRP12 + 1321N1/hVRL-2, 4α-PDD, ~20-23 C',NULL);
