INSERT INTO "biophysics_experiment" VALUES(19,'MAIC:BX:00019',4,NULL,NULL,NULL,'saturating mechanical stimulus; kinetics from responses to stimuli of at least 40 nN/µm² | STIMULUS: ≥40 nN/µm²',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'20.0','mV','TOUCH',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'PLM touch receptor neuron (C. elegans, in vivo)',NULL,7.2,'145 mM NaCl, 5 mM KCl, 5 mM MgCl2, 1 mM CaCl2, 10 mM K-HEPES, pH 7.2 (~320 mOsm, d-glucose)','125 mM K-gluconate, 22 mM NaCl, 1 mM MgCl2, 0.6 mM CaCl2, 10 mM Na-HEPES, 10 mM K2EGTA, pH 7.2',-74.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00021','MRCs reversed polarity near +20 mV in both wild-type and ok1104 animals','Results, "Missense mutations in mec-10 ... alter MRC ion selectivity" + Fig. 4A legend (n)','medium','stimulus_type as-printed: mechanical (touch; pressure step via calibrated probe). recording_mode as-printed: in vivo whole-cell voltage clamp (touch receptor neuron). Native mechanoreceptor current (MRC) recorded in vivo from the PLM touch receptor neuron of C. elegans; current flows through the MEC-4/MEC-10(/MEC-2/MEC-6/UNC-24) DEG/ENaC transduction-channel complex. Channel attribution is genetic (mutant epistasis: mec-4 null animals lack MRCs while mec-10 deletion retains them; O''Hagan et al. 2005), so mechano_gating_contested=true on these native rows. Approximate value ("near +20 mV") from I–V relations recorded from −114 to +66 mV in 20 mV increments with voltage-attenuation correction; consistent with Na+-selective wild-type MRC.','erev_MRC_wt_celegans_plm_invivo_iv','7','LITERATURE','2026-11-08',70,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(20,'MAIC:BX:00020',4,NULL,NULL,1,'saturating mechanical stimulus; kinetics from responses to stimuli of at least 40 nN/µm² | STIMULUS: ≥40 nN/µm²',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'20.0','mV','TOUCH',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'PLM touch receptor neuron (C. elegans, in vivo)',NULL,7.2,'145 mM NaCl, 5 mM KCl, 5 mM MgCl2, 1 mM CaCl2, 10 mM K-HEPES, pH 7.2 (~320 mOsm, d-glucose)','125 mM K-gluconate, 22 mM NaCl, 1 mM MgCl2, 0.6 mM CaCl2, 10 mM Na-HEPES, 10 mM K2EGTA, pH 7.2',-74.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00022','MRCs reversed polarity near +20 mV in both wild-type and ok1104 animals','Results, "Missense mutations in mec-10 ... alter MRC ion selectivity" + Fig. 4A legend (n)','medium','stimulus_type as-printed: mechanical (touch; pressure step via calibrated probe). recording_mode as-printed: in vivo whole-cell voltage clamp (touch receptor neuron). Native mechanoreceptor current (MRC) recorded in vivo from the PLM touch receptor neuron of C. elegans; current flows through the MEC-4/MEC-10(/MEC-2/MEC-6/UNC-24) DEG/ENaC transduction-channel complex. Channel attribution is genetic (mutant epistasis: mec-4 null animals lack MRCs while mec-10 deletion retains them; O''Hagan et al. 2005), so mechano_gating_contested=true on these native rows. Approximate ("near +20 mV"); loss of MEC-10 does not change ion selectivity in vivo.','erev_MRC_mec-10_ok1104_celegans_plm_invivo_iv','4','LITERATURE','2026-11-08',70,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(21,'MAIC:BX:00021',4,NULL,NULL,2,'saturating mechanical stimulus; kinetics from responses to stimuli of at least 40 nN/µm² | STIMULUS: ≥40 nN/µm²',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-20.0','mV','TOUCH',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'PLM touch receptor neuron (C. elegans, in vivo)',NULL,7.2,'145 mM NaCl, 5 mM KCl, 5 mM MgCl2, 1 mM CaCl2, 10 mM K-HEPES, pH 7.2 (~320 mOsm, d-glucose)','125 mM K-gluconate, 22 mM NaCl, 1 mM MgCl2, 0.6 mM CaCl2, 10 mM Na-HEPES, 10 mM K2EGTA, pH 7.2',-74.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00023','We found that this was the case: MRCs recorded in both mec-10(e1515) and mec-4(u339) animals reversed polarity near -20 mV','Results, "Missense mutations in mec-10 ... alter MRC ion selectivity" + Fig. 4C legend (n)','medium','stimulus_type as-printed: mechanical (touch; pressure step via calibrated probe). recording_mode as-printed: in vivo whole-cell voltage clamp (touch receptor neuron). Native mechanoreceptor current (MRC) recorded in vivo from the PLM touch receptor neuron of C. elegans; current flows through the MEC-4/MEC-10(/MEC-2/MEC-6/UNC-24) DEG/ENaC transduction-channel complex. Channel attribution is genetic (mutant epistasis: mec-4 null animals lack MRCs while mec-10 deletion retains them; O''Hagan et al. 2005), so mechano_gating_contested=true on these native rows. Approximate ("near −20 mV"); GOF missense mutations shift E_rev ~40 mV negative, implying increased K+ permeability.','erev_MRC_mec-10_e1515_celegans_plm_invivo_iv','3','LITERATURE','2026-11-08',70,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(22,'MAIC:BX:00022',4,NULL,NULL,4,'saturating mechanical stimulus; kinetics from responses to stimuli of at least 40 nN/µm² | STIMULUS: ≥40 nN/µm²',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-20.0','mV','TOUCH',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'PLM touch receptor neuron (C. elegans, in vivo)',NULL,7.2,'145 mM NaCl, 5 mM KCl, 5 mM MgCl2, 1 mM CaCl2, 10 mM K-HEPES, pH 7.2 (~320 mOsm, d-glucose)','125 mM K-gluconate, 22 mM NaCl, 1 mM MgCl2, 0.6 mM CaCl2, 10 mM Na-HEPES, 10 mM K2EGTA, pH 7.2',-74.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00024','We found that this was the case: MRCs recorded in both mec-10(e1515) and mec-4(u339) animals reversed polarity near -20 mV','Results, "Missense mutations in mec-10 ... alter MRC ion selectivity" + Fig. 4C legend (n)','medium','stimulus_type as-printed: mechanical (touch; pressure step via calibrated probe). recording_mode as-printed: in vivo whole-cell voltage clamp (touch receptor neuron). Native mechanoreceptor current (MRC) recorded in vivo from the PLM touch receptor neuron of C. elegans; current flows through the MEC-4/MEC-10(/MEC-2/MEC-6/UNC-24) DEG/ENaC transduction-channel complex. Channel attribution is genetic (mutant epistasis: mec-4 null animals lack MRCs while mec-10 deletion retains them; O''Hagan et al. 2005), so mechano_gating_contested=true on these native rows. Approximate ("near −20 mV"); homologous S92F substitution in MEC-4 reproduces the e1515 selectivity shift — same channel complex (MEC-4/MEC-10), not a paralog-family row.','erev_MRC_mec-4_u339_celegans_plm_invivo_iv','3','LITERATURE','2026-11-08',70,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(23,'MAIC:BX:00023',4,NULL,NULL,NULL,'pH drop from 7.45 to 6.00 every 60 s (microperfusion); toxin applied at pH 7.45 | STIMULUS: 6.0 pH (test) | MODULATOR: psalmotoxin 1 (PcTx1) (blocker) 10 nM | TEMPERATURE-AS-REPORTED: 18-21 | PH-AS-REPORTED: 7.45 (holding) / 6.0 (stimulus)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,372000.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.2',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus laevis oocyte (rASIC1a or hASIC1a cRNA)','Xenopus laevis oocyte',NULL,NULL,'ND96: 96 mM NaCl, 2 mM KCl, 1.8 mM CaCl2, 2 mM MgCl2, 5 mM HEPES (+0.05% BSA), pH 7.45; pH 6.0 stimulus buffered with Mes',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ASIC-00029','PcTx1 (10 nM) completely inhibited ASIC1a, but the effect was rapidly reversible on peptide washout (τ off = 6.2 min for rASIC1a, 0.99 min for hASIC1a; Fig. 1 F and Fig. S2 ). In striking contrast, current inhibition by 10 nM Hi1a was only slowly reversible (τ off = 14.2 min for rASIC1a, 31.8 min for hASIC1a)','Results, "Discovery of Hi1a" + Fig. 1F legend','high','stimulus_type as-printed: extracellular acidification (rapid solution exchange). recording_mode as-printed: two-electrode voltage clamp (whole oocyte). REPORTED UNIT IS MIN (6.2 min = 372000 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. τ_off = recovery of ASIC1a current from peptide inhibition during washout (toxin-unbinding kinetics), mapped to tau_deact (recovery) per round ruling; NOT channel desensitization. The verify layer''s three τ Y-flags (macropatch activation/desensitization/deactivation τ of hASIC1a ± 5 nM Hi1a) are figure-only (Fig. S3B table) and archived. Rapidly reversible PcTx1 block; n from Fig. 1F legend (n = 5). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','tau_deact_recovery_pcTx1_10nM_rASIC1a_oocyte_tevc','5','LITERATURE','2026-11-08',71,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(24,'MAIC:BX:00024',4,NULL,NULL,NULL,'pH drop from 7.45 to 6.00 every 60 s (microperfusion); toxin applied at pH 7.45 | STIMULUS: 6.0 pH (test) | MODULATOR: Hi1a (recombinant double-knot spider-venom peptide, Hadronyche infensa) (blocker) 10 nM | TEMPERATURE-AS-REPORTED: 18-21 | PH-AS-REPORTED: 7.45 (holding) / 6.0 (stimulus)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,852000.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14.2',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus laevis oocyte (rASIC1a or hASIC1a cRNA)','Xenopus laevis oocyte',NULL,NULL,'ND96: 96 mM NaCl, 2 mM KCl, 1.8 mM CaCl2, 2 mM MgCl2, 5 mM HEPES (+0.05% BSA), pH 7.45; pH 6.0 stimulus buffered with Mes',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ASIC-00030','PcTx1 (10 nM) completely inhibited ASIC1a, but the effect was rapidly reversible on peptide washout (τ off = 6.2 min for rASIC1a, 0.99 min for hASIC1a; Fig. 1 F and Fig. S2 ). In striking contrast, current inhibition by 10 nM Hi1a was only slowly reversible (τ off = 14.2 min for rASIC1a, 31.8 min for hASIC1a)','Results, "Discovery of Hi1a" + Fig. 1F legend','high','stimulus_type as-printed: extracellular acidification (rapid solution exchange). recording_mode as-printed: two-electrode voltage clamp (whole oocyte). REPORTED UNIT IS MIN (14.2 min = 852000 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. τ_off = recovery of ASIC1a current from peptide inhibition during washout (toxin-unbinding kinetics), mapped to tau_deact (recovery) per round ruling; NOT channel desensitization. The verify layer''s three τ Y-flags (macropatch activation/desensitization/deactivation τ of hASIC1a ± 5 nM Hi1a) are figure-only (Fig. S3B table) and archived. Slow reversibility is Hi1a''s hallmark (~40% recovery after 30 min washout — percent archived). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','tau_deact_recovery_hi1a_10nM_rASIC1a_oocyte_tevc','5','LITERATURE','2026-11-08',71,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(25,'MAIC:BX:00025',4,NULL,NULL,NULL,'pH drop from 7.45 to 6.00 every 60 s (microperfusion); toxin applied at pH 7.45 | STIMULUS: 6.0 pH (test) | MODULATOR: psalmotoxin 1 (PcTx1) (blocker) 10 nM | TEMPERATURE-AS-REPORTED: 18-21 | PH-AS-REPORTED: 7.45 (holding) / 6.0 (stimulus)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,59400.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0.99',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus laevis oocyte (rASIC1a or hASIC1a cRNA)','Xenopus laevis oocyte',NULL,NULL,'ND96: 96 mM NaCl, 2 mM KCl, 1.8 mM CaCl2, 2 mM MgCl2, 5 mM HEPES (+0.05% BSA), pH 7.45; pH 6.0 stimulus buffered with Mes',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ASIC-00031','The time constant for recovery from inhibition (τ off ) was 0.99 min for PcTx1 and 31.8 min for Hi1a. Data are mean ± SEM. PcTx1, n = 3; Hi1a, n = 4.','Fig. S2 legend','high','stimulus_type as-printed: extracellular acidification (rapid solution exchange). recording_mode as-printed: two-electrode voltage clamp (whole oocyte). REPORTED UNIT IS MIN (0.99 min = 59400 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. τ_off = recovery of ASIC1a current from peptide inhibition during washout (toxin-unbinding kinetics), mapped to tau_deact (recovery) per round ruling; NOT channel desensitization. The verify layer''s three τ Y-flags (macropatch activation/desensitization/deactivation τ of hASIC1a ± 5 nM Hi1a) are figure-only (Fig. S3B table) and archived. Human orthologue; n from Fig. S2 legend. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','tau_deact_recovery_pcTx1_10nM_hASIC1a_oocyte_tevc','3','LITERATURE','2026-11-08',71,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(26,'MAIC:BX:00026',4,NULL,NULL,NULL,'pH drop from 7.45 to 6.00 every 60 s (microperfusion); toxin applied at pH 7.45 | STIMULUS: 6.0 pH (test) | MODULATOR: Hi1a (recombinant double-knot spider-venom peptide, Hadronyche infensa) (blocker) 10 nM | TEMPERATURE-AS-REPORTED: 18-21 | PH-AS-REPORTED: 7.45 (holding) / 6.0 (stimulus)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1908000.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'31.8',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus laevis oocyte (rASIC1a or hASIC1a cRNA)','Xenopus laevis oocyte',NULL,NULL,'ND96: 96 mM NaCl, 2 mM KCl, 1.8 mM CaCl2, 2 mM MgCl2, 5 mM HEPES (+0.05% BSA), pH 7.45; pH 6.0 stimulus buffered with Mes',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ASIC-00032','The time constant for recovery from inhibition (τ off ) was 0.99 min for PcTx1 and 31.8 min for Hi1a. Data are mean ± SEM. PcTx1, n = 3; Hi1a, n = 4.','Fig. S2 legend','high','stimulus_type as-printed: extracellular acidification (rapid solution exchange). recording_mode as-printed: two-electrode voltage clamp (whole oocyte). REPORTED UNIT IS MIN (31.8 min = 1.908e+06 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. τ_off = recovery of ASIC1a current from peptide inhibition during washout (toxin-unbinding kinetics), mapped to tau_deact (recovery) per round ruling; NOT channel desensitization. The verify layer''s three τ Y-flags (macropatch activation/desensitization/deactivation τ of hASIC1a ± 5 nM Hi1a) are figure-only (Fig. S3B table) and archived. 32-min recovery — the slowest reversibility reported for any ASIC modulator at the time. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','tau_deact_recovery_hi1a_10nM_hASIC1a_oocyte_tevc','4','LITERATURE','2026-11-08',71,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(27,'MAIC:BX:00027',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding) | ERROR-AS-REPORTED: 0.51','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3150.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'3.15',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00033','The inactivation kinetics of MDEG1 (τ inact = 3.15 ± 0.51 s, n = 22) are slower than for ASIC (τ inact = 1.4 ± 0.05 s, n= 129; p< 0.001).','Results and Discussion, MDEG1 proton gating paragraph','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell. REPORTED UNIT IS S (3.15 s = 3150 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. MDEG1 = rat ASIC2a. Inactivation (desensitization) τ of the H+-gated transient current; slower than ASIC/DRASIC. Error type (SEM/SD) not stated. | recording_mode corrected (standard m-8): desensitization tau is from WHOLE-CELL mode (condition_key token); the RM map had matched "outside-out" from the paper dual-configuration text first. [F-004:undetermined] junction not certifiable offline (no fulltext corpus (abstract-only fallback); classified 2026-08-31)','tau_inact_MDEG1_homomer_cos7_wholecell_ph7.3to5_hold-60mV','22','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(28,'MAIC:BX:00028',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding) | ERROR-AS-REPORTED: 0.05','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1400.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.4',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00034','The inactivation kinetics of MDEG1 (τ inact = 3.15 ± 0.51 s, n = 22) are slower than for ASIC (τ inact = 1.4 ± 0.05 s, n= 129; p< 0.001).','Results and Discussion, MDEG1 proton gating paragraph','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell. REPORTED UNIT IS S (1.4 s = 1400 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. ASIC = rat ASIC1a; same-lab within-paper comparison measurement (own data, n = 129). Included as ASIC1a-family tau_inact evidence. | recording_mode corrected (standard m-8): desensitization tau is from WHOLE-CELL mode (condition_key token); the RM map had matched "outside-out" from the paper dual-configuration text first. [F-004:undetermined] junction not certifiable offline (no fulltext corpus (abstract-only fallback); classified 2026-08-31)','tau_inact_ASIC_rathomomer_cos7_wholecell_ph7.3to5_hold-60mV','129','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(29,'MAIC:BX:00029',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding) | ERROR-AS-REPORTED: 2','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13.4','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00035','The slope conductance between -40 and +40 mV is 13.4 ± 2 pS for MDEG1 and 13.7 ± 2 pS for MDEG1/MDEG2','Results and Discussion, unitary currents paragraph + Fig. 4E/F/I (n from legend: 5 patches)','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. Main conductance state from unitary I–V slope (−40 to +40 mV); subconductance states also present (not quantified). pH 4 activation for unitary recordings per Fig. 4 legend.','conductance_MDEG1_homomer_cos7_outsideout_slope-40to+40mV','5','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(30,'MAIC:BX:00030',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding) | ERROR-AS-REPORTED: 2','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13.7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13.7','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00036','The slope conductance between -40 and +40 mV is 13.4 ± 2 pS for MDEG1 and 13.7 ± 2 pS for MDEG1/MDEG2','Results and Discussion, unitary currents paragraph + Fig. 4F/I (n from legend)','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. Heteromer main state is Na+-selective like MDEG1; the non-selective sustained current is attributed to lower-conductance channels (not separable — archived). | n=11 is the in-text E_rev sentence n; the Fig 4 legend says the slope-conductance panels used 5 patches each — n provenance divergence disclosed (adversarial F3), value unchanged.','conductance_MDEG1_MDEG2_heteromer_cos7_outsideout_slope-40to+40mV','11','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(31,'MAIC:BX:00031',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding) | ERROR-AS-REPORTED: 2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'30.0','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00037','The unitary currents reversed at 30 ± 2 mV for both MDEG1 (n = 8) and MDEG1/MDEG2 (n = 11) (Na+ equilibrium potential = +40.1 mV)','Results and Discussion, unitary currents paragraph + Fig. 4I','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. Main-state unitary E_rev; below E_Na (+40.1 mV, calculated — archived as context), i.e. mainly Na+-permeable.','erev_MDEG1_homomer_cos7_outsideout_30mM_Na-in','8','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(32,'MAIC:BX:00032',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding) | ERROR-AS-REPORTED: 2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'30.0','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00038','The unitary currents reversed at 30 ± 2 mV for both MDEG1 (n = 8) and MDEG1/MDEG2 (n = 11) (Na+ equilibrium potential = +40.1 mV)','Results and Discussion, unitary currents paragraph + Fig. 4I','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. Identical to MDEG1 for the main conductance state; heteromer specificity appears in the sustained component E_rev ~0 mV (rowed separately). | n=11 is the in-text E_rev sentence n; the Fig 4 legend says the slope-conductance panels used 5 patches each — n provenance divergence disclosed (adversarial F3), value unchanged.','erev_MDEG1_MDEG2_heteromer_cos7_outsideout_30mM_Na-in','11','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(33,'MAIC:BX:00033',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding) | ERROR-AS-REPORTED: 3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,32.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'32.0','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00039','However, unlike the native current, the two DRASIC components reverse at the same membrane potential of +32 ± 3 mV (n = 5)','Results and Discussion, DRASIC/MDEG2 paragraph + Fig. 5A/D','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. DRASIC = rat ASIC3; own-data comparison in the same paper. Both kinetic components share +32 mV (unlike native DRG sustained current).','erev_DRASIC_homomer_peakandsustained_cos7_30mM_Na-in','5','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(34,'MAIC:BX:00034',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,40.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'40.0','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00040','The transient peak current produced by activation of DRASIC/MDEG2 reversed at +40 mV with 30 m m Na+in the pipette (n = 10)','Results and Discussion, DRASIC/MDEG2 paragraph + Fig. 5B/E','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. Heteromeric transient component is Na+-selective (E_rev near E_Na with 30 mM internal Na).','erev_DRASIC_MDEG2_heteromer_peak_30mM_Na-in','10','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(35,'MAIC:BX:00035',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,80.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'80.0','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00041','while it reversed at a value well above +80 mV in the absence of intracellular Na+ (n = 5)','Results and Discussion, DRASIC/MDEG2 paragraph + Fig. 5C/F','medium','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. Printed as "well above +80 mV" — bound, rowed with value_relation ">". Confirms Na+ carry of the transient component.','erev_DRASIC_MDEG2_heteromer_peak_0Na-in','5','LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(36,'MAIC:BX:00036',4,NULL,NULL,NULL,'pH drop from 7.3 to 5 (or 4) for kinetics/selectivity; pH <6 buffered with MES | STIMULUS: 5.0 pH (test) | TEMPERATURE-AS-REPORTED: 22 (±2) | PH-AS-REPORTED: 7.3 (holding)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0.0','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','COS7 cells transiently transfected (rat MDEG1/MDEG2/DRASIC/ASIC cDNAs, PCI vector)','COS7 cell',NULL,NULL,'140 mM NaCl, 5 mM KCl, 2 mM MgCl2, 2 mM CaCl2, 10 mM HEPES, pH 7.3','120 mM KCl, 30 mM NaCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.2 (30 mM cytosolic Na+; "0 Na" variant replaces NaCl with KCl)',-60.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00042','The steady-state current, however, reversed close to 0 mV in the absence or presence of Na+, indicating that it is not a Na+-selective current.','Results and Discussion, DRASIC/MDEG2 paragraph','high','stimulus_type as-printed: extracellular acidification (microperfusion). recording_mode as-printed: whole-cell and outside-out patch clamp. "reversed close to 0 mV" independent of the Na+ gradient — the non-selective sustained component that MDEG2 confers to DRASIC (matches native DRG nociceptor sustained current).','erev_DRASIC_MDEG2_heteromer_sustained_nonselective',NULL,'LITERATURE','2026-11-08',72,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(37,'MAIC:BX:00037',4,NULL,NULL,NULL,'rapid activation by pH 6.0 from holding pH 7.4 | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) | ERROR-AS-REPORTED: 0.9 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5.8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'5.8','ms','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00043','No significant differences were found in the time constants of activation (τ act of 5.8 ± 0.9 ms (n = 16) for ASIC1a, 9.9 ± 4.8 ms (n = 6) for ASIC1b, and 6.5 ± 0.9 ms (n = 3) for ASIC1b-M3','Results, "Analysis of Kinetics and Selectivity of ASIC1" + Fig. 2','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). Single-exponential activation τ; mean ± S.D. (Data Analysis: "Values are reported as mean ± S.D.").','tau_act_rASIC1a_homomer_oocyte_outsideout_ph6.0_hold-100mV','16','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(38,'MAIC:BX:00038',4,NULL,NULL,NULL,'rapid activation by pH 6.0 from holding pH 7.4 | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) | ERROR-AS-REPORTED: 4.8 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'9.9','ms','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00044','No significant differences were found in the time constants of activation (τ act of 5.8 ± 0.9 ms (n = 16) for ASIC1a, 9.9 ± 4.8 ms (n = 6) for ASIC1b, and 6.5 ± 0.9 ms (n = 3) for ASIC1b-M3','Results, "Analysis of Kinetics and Selectivity of ASIC1" + Fig. 2','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). ASIC1b = long splice variant of rat ASIC1; kinetics similar to ASIC1a (no significant difference).','tau_act_rASIC1b_homomer_oocyte_outsideout_ph6.0_hold-100mV','6','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(39,'MAIC:BX:00039',4,NULL,NULL,5,'rapid activation by pH 6.0 from holding pH 7.4 | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) | ERROR-AS-REPORTED: 0.9 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.5','ms','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00045','No significant differences were found in the time constants of activation (τ act of 5.8 ± 0.9 ms (n = 16) for ASIC1a, 9.9 ± 4.8 ms (n = 6) for ASIC1b, and 6.5 ± 0.9 ms (n = 3) for ASIC1b-M3','Results, "Analysis of Kinetics and Selectivity of ASIC1"','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). Shorter ASIC-β form initiating at the third methionine.','tau_act_rASIC1bM3_homomer_oocyte_outsideout_ph6.0_hold-100mV','3','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(40,'MAIC:BX:00040',4,NULL,NULL,NULL,'rapid activation by pH 6.0 from holding pH 7.4 | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) | ERROR-AS-REPORTED: 0.6 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1150.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.15',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00046','Similarly, time constants for inactivation were virtually identical for ASIC1a (τ inact = 1.15 ± 0.6 s, n = 17), ASIC1b (τ inact = 1.2 ± 0.77 s,n = 9), and ASIC1b-M3 (τ inact = 0.6 ± 0.2 s, n = 4).','Results, "Analysis of Kinetics and Selectivity of ASIC1"','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). REPORTED UNIT IS S (1.15 s = 1150 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. Single-exponential inactivation (desensitization) τ.','tau_inact_rASIC1a_homomer_oocyte_outsideout_ph6.0_hold-100mV','17','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(41,'MAIC:BX:00041',4,NULL,NULL,NULL,'rapid activation by pH 6.0 from holding pH 7.4 | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) | ERROR-AS-REPORTED: 0.77 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1200.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.2',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00047','Similarly, time constants for inactivation were virtually identical for ASIC1a (τ inact = 1.15 ± 0.6 s, n = 17), ASIC1b (τ inact = 1.2 ± 0.77 s,n = 9), and ASIC1b-M3 (τ inact = 0.6 ± 0.2 s, n = 4).','Results, "Analysis of Kinetics and Selectivity of ASIC1"','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). REPORTED UNIT IS S (1.2 s = 1200 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. Virtually identical to ASIC1a.','tau_inact_rASIC1b_homomer_oocyte_outsideout_ph6.0_hold-100mV','9','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(42,'MAIC:BX:00042',4,NULL,NULL,5,'rapid activation by pH 6.0 from holding pH 7.4 | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) | ERROR-AS-REPORTED: 0.2 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,600.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0.6',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00048','Similarly, time constants for inactivation were virtually identical for ASIC1a (τ inact = 1.15 ± 0.6 s, n = 17), ASIC1b (τ inact = 1.2 ± 0.77 s,n = 9), and ASIC1b-M3 (τ inact = 0.6 ± 0.2 s, n = 4).','Results, "Analysis of Kinetics and Selectivity of ASIC1"','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). REPORTED UNIT IS S (0.6 s = 600 ms): unit column left blank because the tau storage vocabulary fixes ms; value kept as-printed. Fastest of the three isoforms.','tau_inact_rASIC1bM3_homomer_oocyte_outsideout_ph6.0_hold-100mV','4','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(43,'MAIC:BX:00043',4,NULL,NULL,NULL,'channels activated by pH 6.0; E_rev from fast voltage ramps (−100 to +100 mV and back) after full activation; bi-ionic Na+/Li+/Ca2+ application solutions | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14.0',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00049','ASIC1b discriminates stronger between monovalent cations than ASIC1a (P Na/P K = 14.0 compared with 7.8), but most notably shows no permeability to Ca 2+','Results, "Analysis of Kinetics and Selectivity of ASIC1" + Fig. 3 (n from legend: 5–9 experiments)','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). GHK-derived unitless permeability ratio (140 mM NaCl or LiCl outside / 140 mM KCl inside). ASIC1b discriminates monovalents more strongly than ASIC1a.','ionselect_PNaPK_rASIC1b_homomer_oocyte_outsideout_biionic','5-9','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(44,'MAIC:BX:00044',4,NULL,NULL,NULL,'channels activated by pH 6.0; E_rev from fast voltage ramps (−100 to +100 mV and back) after full activation; bi-ionic Na+/Li+/Ca2+ application solutions | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7.8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'7.8',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00050','ASIC1b discriminates stronger between monovalent cations than ASIC1a (P Na/P K = 14.0 compared with 7.8), but most notably shows no permeability to Ca 2+','Results, "Analysis of Kinetics and Selectivity of ASIC1" + Fig. 3','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). Unitless. Same-lab within-paper comparison value.','ionselect_PNaPK_rASIC1a_homomer_oocyte_outsideout_biionic','5-9','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(45,'MAIC:BX:00045',4,NULL,NULL,NULL,'channels activated by pH 6.0; E_rev from fast voltage ramps (−100 to +100 mV and back) after full activation; bi-ionic Na+/Li+/Ca2+ application solutions | STIMULUS: 6.0 pH (test) | PH-AS-REPORTED: 7.4 (holding)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18.5,NULL,NULL,NULL,NULL,NULL,NULL,'18.5',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','Xenopus laevis oocyte (rat ASIC1a/ASIC1b/ASIC1b-M3 cRNA)','Xenopus laevis oocyte',NULL,NULL,'140 mM NaCl, 2 mM MgCl2, 1.8 mM CaCl2, 10 mM HEPES (MES for pH 5/6), pH 7.4','140 mM KCl, 2 mM MgCl2, 5 mM EGTA, 10 mM HEPES, pH 7.4',-100.0,NULL,NULL,NULL,NULL,NULL,'ASIC-00051','Ca 2+ permeability of ASIC1a is low (P Na/P Ca = 18.5).','Results, "Analysis of Kinetics and Selectivity of ASIC1" + Fig. 3','high','stimulus_type as-printed: extracellular acidification (piezo-driven double-barreled pipette, exchange <2 ms). recording_mode as-printed: outside-out macropatch (rapid piezo application). Low Ca2+ permeability of ASIC1a; ASIC1b shows no Ca2+ permeability (no ratio printable — the Discussion "P_Na/P_Ca > 100" refers to ASIC3 in cardiac afferents, cited Sutherland 2001, archived). | RULING FIX (adversarial F1): P_Na/P_Ca ratios unified to ca_permeability (was ion_selectivity_ratio) — same quantity as the Sherwood 2011 rows.','ionselect_PNaPCa_rASIC1a_homomer_oocyte_outsideout_biionic','5-9','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(46,'MAIC:BX:00046',4,NULL,NULL,NULL,'pH step 7.4 → 5.0 with 50 mM BaCl2 bath; E_rev from I–V (−30 to −100 mV, 10 mV steps, linear fit) | STIMULUS: 5.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) / 5.0 (test) | ERROR-AS-REPORTED: 5.4 (sd)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-65.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-65.0','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus laevis oocyte (rat ASIC1a/ASIC1b or chimera cRNA)','Xenopus laevis oocyte',NULL,NULL,'50 mM BaCl2, 2 mM MgCl2, 10 mM HEPES, pH 5.0 (divalent-permeability assay; uninjected-oocyte currents subtracted)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ASIC-00052','proton-activated currents of ASIC1b expressing oocytes reversed under these conditions at -84.6 ± 3.6 mV (mean ± S.D.;n = 3), indicating that these are mainly carried by K+. Currents of ASIC1a expressing oocytes in contrast reversed at -65.0 ± 5.4 mV (n = 6)','Results, divalent-permeability paragraph + Fig. 4 legend','high','stimulus_type as-printed: extracellular acidification. recording_mode as-printed: two-electrode voltage clamp (whole oocyte). E_rev between E_K and E_Ba indicates significant Ba2+ contribution — the assay readout for divalent permeability; whole-oocyte I–V with endogenous currents subtracted.','erev_50mMBa_bath_rASIC1a_homomer_oocyte_tevc_ph5.0','6','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(47,'MAIC:BX:00047',4,NULL,NULL,NULL,'pH step 7.4 → 5.0 with 50 mM BaCl2 bath; E_rev from I–V (−30 to −100 mV, 10 mV steps, linear fit) | STIMULUS: 5.0 pH (test) | PH-AS-REPORTED: 7.4 (holding) / 5.0 (test) | ERROR-AS-REPORTED: 3.6 (sd)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-84.6,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-84.6','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus laevis oocyte (rat ASIC1a/ASIC1b or chimera cRNA)','Xenopus laevis oocyte',NULL,NULL,'50 mM BaCl2, 2 mM MgCl2, 10 mM HEPES, pH 5.0 (divalent-permeability assay; uninjected-oocyte currents subtracted)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ASIC-00053','proton-activated currents of ASIC1b expressing oocytes reversed under these conditions at -84.6 ± 3.6 mV (mean ± S.D.;n = 3), indicating that these are mainly carried by K+. Currents of ASIC1a expressing oocytes in contrast reversed at -65.0 ± 5.4 mV (n = 6)','Results, divalent-permeability paragraph + Fig. 4 legend','high','stimulus_type as-printed: extracellular acidification. recording_mode as-printed: two-electrode voltage clamp (whole oocyte). Near E_K — current mainly K+, i.e. ASIC1b impermeable to the divalent Ba2+.','erev_50mMBa_bath_rASIC1b_homomer_oocyte_tevc_ph5.0','3','LITERATURE','2026-11-08',73,'2026-11-08 00:00:00.000000',NULL);
