INSERT INTO "biophysics_experiment" VALUES(173,'MAIC:BX:00173',6,NULL,NULL,NULL,'steps of negative pressure (screw-driven syringe); Po/Pc from integral current, two-state Boltzmann fits; tension calibrated against MscS (gamma1/2 MscS = 5.5 dyne/cm, cited) | ERROR-AS-REPORTED: 0.6','T50',NULL,NULL,10.5,'dyn/cm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'10.5','dyne/cm','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','E. coli giant spheroplasts expressing WT or S3/C-terminal MscL mutants (L121/L122, L128/L129 substitutions, Δ110-136)','E. coli giant spheroplast',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'MSCL-EX-00064','TABLE III Energy, Expansion, and Midpoint Tension for Gating Transitions Extracted from Dose–response Curves for WT MscL and Eight Mutants Mutant ΔE ΔA γ 0.5 kT nm 2 dyne/cm WT 29.8 ± 5.1 ( n = 10) 11.5 ± 2.1 10.5 ± 0.6 WT + DTT 28.3 ± 4.0 ( n = 5) 12.9 ± 0.9 8.9 ± 0.6 a L121C/L122C 26.0 ± 2.3 ( n = 5) 10.1 ± 0.7 10.5 ± 0.5 L121C/L122C + DTT 30.3 ± 1.0 ( n = 3) 13.9 ± 0.1 8.8 ± 0.2 L128C/L129C 26.0 ± 3.4 ( n = 8) 9.9 ± 1.3 10.6 ± 0.2 L128C/L129C + DTT 30.6 ± 5.7 ( n = 4) 14.0 ± 2.8 8.9 ± 0.9 L121A/L122A 36.1 ± 3.9 a ( n = 6) 14.0 ± 1.1 a 10.4 ± 0.5 L128A/L129A 34.6 ± 5.4 ( n = 4) 14.0 ± 2.2 10.1 ± 1.3 L121T/L122T 27.2 ± 4.1 ( n = 7) 10.8 ± 1.7 10.2 ± 0.7 L121A/L122A/L128A/L129A 33.3 ± 2.9 ( n = 7) 14.0 ± 1.3 a 9.7 ± 0.7 a L121T/L122T/L128T/L129T 34.1 ± 3.7 a ( n = 4) 15.0 ± 2.2 a 9.2 ± 0.5 a Δ110-136 36.1 ± 5.9 a ( n = 12) 15.3 ± 2.2 a 9.5 ± 1.0 a','Table III (gamma0.5 column; n per condition in the ΔE column)','high','dyn/cm IS a legal TensionUnit value and numerically equal to mN/m; kept as-reported with unit_db=dyn/cm. Error type not stated in Table III (superscript ''a'' marks t-test significance vs WT, not an error convention). Double/quadruple substitutions recorded as semicolon-joined short protein changes (loader may split into per-variant rows). Crosslinked-vs-ambient comparison: ''the slope of dose–response curves for WT MscL remains the same after DTT addition, but the midpoint (γ 0.5 , tension at which Po/Pc = 1) shifts from 10.5 to 8.9 dyne/cm'' — endpoints rowed as the WT and WT+DTT pair; no single explicit delta value -> no delta_p50 row. DeltaE/DeltaA columns (kT, nm2) have no parameter_kind home -> noted, not rowed.','excised spheroplast patch, E. coli MscL WT, two-state fit of Po/Pc vs tension','10','LITERATURE','2026-11-08',127,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(174,'MAIC:BX:00174',6,NULL,NULL,NULL,'steps of negative pressure (screw-driven syringe); Po/Pc from integral current, two-state Boltzmann fits; tension calibrated against MscS (gamma1/2 MscS = 5.5 dyne/cm, cited) | MODULATOR: DTT (dithiothreitol) (potentiator) 25 mM | ERROR-AS-REPORTED: 0.6','T50',NULL,NULL,8.9,'dyn/cm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'8.9','dyne/cm','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','E. coli giant spheroplasts expressing WT or S3/C-terminal MscL mutants (L121/L122, L128/L129 substitutions, Δ110-136)','E. coli giant spheroplast',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'MSCL-EX-00065','TABLE III Energy, Expansion, and Midpoint Tension for Gating Transitions Extracted from Dose–response Curves for WT MscL and Eight Mutants Mutant ΔE ΔA γ 0.5 kT nm 2 dyne/cm WT 29.8 ± 5.1 ( n = 10) 11.5 ± 2.1 10.5 ± 0.6 WT + DTT 28.3 ± 4.0 ( n = 5) 12.9 ± 0.9 8.9 ± 0.6 a L121C/L122C 26.0 ± 2.3 ( n = 5) 10.1 ± 0.7 10.5 ± 0.5 L121C/L122C + DTT 30.3 ± 1.0 ( n = 3) 13.9 ± 0.1 8.8 ± 0.2 L128C/L129C 26.0 ± 3.4 ( n = 8) 9.9 ± 1.3 10.6 ± 0.2 L128C/L129C + DTT 30.6 ± 5.7 ( n = 4) 14.0 ± 2.8 8.9 ± 0.9 L121A/L122A 36.1 ± 3.9 a ( n = 6) 14.0 ± 1.1 a 10.4 ± 0.5 L128A/L129A 34.6 ± 5.4 ( n = 4) 14.0 ± 2.2 10.1 ± 1.3 L121T/L122T 27.2 ± 4.1 ( n = 7) 10.8 ± 1.7 10.2 ± 0.7 L121A/L122A/L128A/L129A 33.3 ± 2.9 ( n = 7) 14.0 ± 1.3 a 9.7 ± 0.7 a L121T/L122T/L128T/L129T 34.1 ± 3.7 a ( n = 4) 15.0 ± 2.2 a 9.2 ± 0.5 a Δ110-136 36.1 ± 5.9 a ( n = 12) 15.3 ± 2.2 a 9.5 ± 1.0 a','Table III (gamma0.5 column; n per condition in the ΔE column)','high','dyn/cm IS a legal TensionUnit value and numerically equal to mN/m; kept as-reported with unit_db=dyn/cm. Error type not stated in Table III (superscript ''a'' marks t-test significance vs WT, not an error convention). Double/quadruple substitutions recorded as semicolon-joined short protein changes (loader may split into per-variant rows). +DTT rows: 25 mM DTT in the bath (Fig 6 A legend). DTT LOWERS the midpoint (sensitizes) -> modulator_role ''potentiator''; the paper attributes the WT+DTT shift to ''an apparently nonspecific effect of reduction ... due to the cleavage of disulfide bonds in the surrounding proteins''. DeltaE/DeltaA columns (kT, nm2) have no parameter_kind home -> noted, not rowed.','excised spheroplast patch, E. coli MscL WT + DTT, two-state fit of Po/Pc vs tension','5','LITERATURE','2026-11-08',127,'2026-11-08 00:00:00.000000',NULL);
