INSERT INTO "biophysics_experiment" VALUES(402,'MAIC:BX:00402',7,NULL,NULL,NULL,'single-channel activation by constant -40 mmHg suction for 5 s (10-s inter-sweep interval) via high-speed pressure clamp (HSPC-1, ALA Scientific) at holding potentials 0 mV and -40 to -100 mV; unitary I-V across voltages, gamma = slope of linear fit; sampled 50 kHz, filtered 2 kHz (Digidata 1550B, Bessel) | TEMPERATURE-AS-REPORTED: 22-24','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,124.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'124.3','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','PIEZO1-knockout (CRISPR/Cas9) HEK293T cells expressing Arabidopsis OSCA1.2; inside-out patches, intracellular (bath) face perfused to the indicated pH','PIEZO1-KO HEK293T',NULL,7.3,'140 KCl, 10 HEPES, 2 MgCl2, 10 glucose, pH set per condition with KOH/HCl (intracellular face)','130 NaCl, 5 KCl, 10 HEPES, 10 TEA-Cl, 1 CaCl2, 1 MgCl2 (extracellular face)',NULL,NULL,NULL,NULL,NULL,NULL,'OSCA-EX-00095','Single-channel current-voltage relationships ( Fig. 3 I) and quantitative analysis ( Fig. 3 H) confirmed that the unitary conductance remained largely unchanged between pH 7.3 and pH 8.9, with estimated conductance of approximately 124.3 pS and 131.3 pS, respectively.','Results (single-channel pH sensitivity; Fig 3, H and I)','high','[pool-external] 2026-11-07 landscape scan (PR #134) -> pool_external verification (data/osca/literature/raw/pool_external_verified.json). pH-to-value mapping by the sentence''s ''respectively'' (pH 7.3 -> 124.3, pH 8.9 -> 131.3 pS); ''approximately'' -> value_relation ''~''; no error term printed in the text sentence (Fig 3 legend: ''Data are presented as mean ± SD''; paired t-test in panel H) -> error left blank. n = 6 patches from the Fig 3I legend. Heterologous recombinant numerics = confidence high (ruling 9). LAI ARCHIVE (not rowed): threshold/delta_p50 Y-flags — the pH 6.2/8.9-vs-7.3 I-P threshold shifts are quantified only as normalized I-P curves (n=5-6 patches, two-way ANOVA) with absolute mmHg deltas FIGURE-ONLY (Fig 1E/G) — no text-level mmHg delta, arithmetic forbidden (ruling 7); archive spans in extract_quotes_supplemental-v1.json. Panel extension (OSCA1.1 self-subclade, OSCA3.1 paralog subclade, mTMEM63A vertebrate ortholog) describes pH modulation without separate threshold/conductance numerics (I-V current amplitudes only) -> never rowed. Liposome single-channel conductance (Fig 4G) prints no numeric in text (''a modest but statistically significant increase in unitary conductance at pH 8.9 compared to pH 7.3'') -> no row. PIEZO1-KO host line only — no Piezo numerics (no contamination). structure_function N per verify layer (no mutagenesis; pH-sensing residues left to future work).','AtOSCA1.2-WT_PIEZO1-KO-HEK293T_inside-out_-40mmHg-5s-suction_unitary-I-V-slope_pH7.3_Fig3H','6','LITERATURE','2026-11-08',143,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(403,'MAIC:BX:00403',7,NULL,NULL,NULL,'single-channel activation by constant -40 mmHg suction for 5 s (10-s inter-sweep interval) via high-speed pressure clamp (HSPC-1, ALA Scientific) at holding potentials 0 mV and -40 to -100 mV; unitary I-V across voltages, gamma = slope of linear fit; sampled 50 kHz, filtered 2 kHz (Digidata 1550B, Bessel) | TEMPERATURE-AS-REPORTED: 22-24','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,131.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'131.3','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','PIEZO1-knockout (CRISPR/Cas9) HEK293T cells expressing Arabidopsis OSCA1.2; inside-out patches, intracellular (bath) face perfused to the indicated pH','PIEZO1-KO HEK293T',NULL,8.9,'140 KCl, 10 HEPES, 2 MgCl2, 10 glucose, pH set per condition with KOH/HCl (intracellular face)','130 NaCl, 5 KCl, 10 HEPES, 10 TEA-Cl, 1 CaCl2, 1 MgCl2 (extracellular face)',NULL,NULL,NULL,NULL,NULL,NULL,'OSCA-EX-00096','Single-channel current-voltage relationships ( Fig. 3 I) and quantitative analysis ( Fig. 3 H) confirmed that the unitary conductance remained largely unchanged between pH 7.3 and pH 8.9, with estimated conductance of approximately 124.3 pS and 131.3 pS, respectively.','Results (single-channel pH sensitivity; Fig 3, H and I)','high','[pool-external] 2026-11-07 landscape scan (PR #134) -> pool_external verification (data/osca/literature/raw/pool_external_verified.json). pH-to-value mapping by the sentence''s ''respectively'' (pH 7.3 -> 124.3, pH 8.9 -> 131.3 pS); ''approximately'' -> value_relation ''~''; no error term printed in the text sentence (Fig 3 legend: ''Data are presented as mean ± SD''; paired t-test in panel H) -> error left blank. n = 6 patches from the Fig 3I legend. Heterologous recombinant numerics = confidence high (ruling 9). LAI ARCHIVE (not rowed): threshold/delta_p50 Y-flags — the pH 6.2/8.9-vs-7.3 I-P threshold shifts are quantified only as normalized I-P curves (n=5-6 patches, two-way ANOVA) with absolute mmHg deltas FIGURE-ONLY (Fig 1E/G) — no text-level mmHg delta, arithmetic forbidden (ruling 7); archive spans in extract_quotes_supplemental-v1.json. Panel extension (OSCA1.1 self-subclade, OSCA3.1 paralog subclade, mTMEM63A vertebrate ortholog) describes pH modulation without separate threshold/conductance numerics (I-V current amplitudes only) -> never rowed. Liposome single-channel conductance (Fig 4G) prints no numeric in text (''a modest but statistically significant increase in unitary conductance at pH 8.9 compared to pH 7.3'') -> no row. PIEZO1-KO host line only — no Piezo numerics (no contamination). structure_function N per verify layer (no mutagenesis; pH-sensing residues left to future work).','AtOSCA1.2-WT_PIEZO1-KO-HEK293T_inside-out_-40mmHg-5s-suction_unitary-I-V-slope_pH8.9_Fig3H','6','LITERATURE','2026-11-08',143,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(404,'MAIC:BX:00404',7,NULL,NULL,76,'cell-attached pressure pulse sequence via high-speed pressure clamp (HSPC-1, ALA Scientific) at constant -80 mV; normalized I-P relationships, P50 from Boltzmann fit; sampled 10 kHz; room temperature stated without numeric value',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,18.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'18','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','TMEM16F-knockout HEK293T cells expressing eGFP-tagged human TMEM63B (WT or I475del; Lipofectamine 2000), recorded 24-48 h post-transfection','TMEM16F KO HEK293T',NULL,7.3,'140 KCl, 10 HEPES, 2 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEA-Cl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'OSCA-EX-00097','We observed that the I475del variant was modestly sensitized to pressure stimulation relative to WT by shifting the current-pressure relationship ~18 mmHg to the left','Results (I475del exhibits elevated pressure sensitivity; Figure 2)','high','[pool-external class] 2026-11-07 iter-1 re-verification entry (data/osca/literature/raw/iter1_verified.json). Mutation-induced threshold shift quantified in text verbatim (''~18 mmHg to the left'', leftward = sensitization, signed convention: negative-direction shift on the suction axis as-printed unsigned magnitude with direction declared); no error term printed -> error_type none. n = 6 patches per genotype (Fig 2a legend; WT n=6, I475del n=6). P50 by Boltzmann fit of normalized I-P at constant -80 mV. LOWRY ARCHIVE (not rowed): threshold Y-flag — absolute WT/I475del P50 values are FIGURE-ONLY (Fig 2c quantification panel; legend prints conditions and n but no mmHg) -> no p50 rows, only the text-level delta. structure_function Y-flag — P451A and G533A ''completely abolished voltage-dependent currents observed for I475del (as well as WT) under -80 mmHg applied pressure'' = qualitative abolition, no numeric -> no row. TMEM16F = host-line KO only (no TMEM16-family rows). Lipid-scramblase assays (Annexin-V imaging) are not channel parameters.','hTMEM63B-I475del_TMEM16F-KO-HEK293T_cell-attached_-80mV_delta-P50_leftward-vs-WT_Fig2','6','LITERATURE','2026-11-08',144,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(405,'MAIC:BX:00405',1,NULL,NULL,77,'negative pressure (pipette suction) via high-speed pressure clamp HSFC-1; voltage-dependence series -110 to +40 mV; Boltzmann dose-response (current vs pressure) for P1/2','P50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13','mmHg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGENE, 250 ng cDNA, recorded 24-48 h)','HEK293 (hPIEZO1 WT / HX mutants / G2218Stop)',NULL,7.3,'145 NaCl, 5 KCl, 3 MgCl2, 1 CaCl2, 10 HEPES (mM)','150 KCl, 0.5 MgCl2, 0.25 EGTA, 10 HEPES (mM); or 150 CsCl, 1 MgCl2, 1 CaCl2, 5 EGTA, 10 HEPES (mM)',-33.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00001','R2456H and R2456K exhibited a leftward shift of 13 and 8 mmHg, respectively, in the P1/2, but M2225R was similar to the WT channel (Fig. 4A).','Results (Fig. 4A)','high','verify 层 delta_p50=N，但正文印出量化 P1/2 位移（delta 数值直接印刷），按 SPEC delta_p50 裁决（论文印出 delta 数值）入行。leftward = 更低压力激活（gain-of-mechanosensitivity）。Fig. 4 系列 patch 配置论文未逐字标注，按 Methods ''patches...suction applied with a high-speed pressure clamp'' 归 cell-attached suction。绝对 P1/2/α 的 mean±SD 在 Fig. 4 表格（图片），正文无数字。','hPIEZO1_HEK293_cell-attached_suction_Boltzmann-P1/2-shift_R2456H_Fig4A',NULL,'LITERATURE','2026-11-08',1,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(406,'MAIC:BX:00406',1,NULL,NULL,78,'negative pressure (pipette suction) via high-speed pressure clamp HSFC-1; voltage-dependence series -110 to +40 mV; Boltzmann dose-response (current vs pressure) for P1/2','P50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'8','mmHg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGENE, 250 ng cDNA, recorded 24-48 h)','HEK293 (hPIEZO1 WT / HX mutants / G2218Stop)',NULL,7.3,'145 NaCl, 5 KCl, 3 MgCl2, 1 CaCl2, 10 HEPES (mM)','150 KCl, 0.5 MgCl2, 0.25 EGTA, 10 HEPES (mM); or 150 CsCl, 1 MgCl2, 1 CaCl2, 5 EGTA, 10 HEPES (mM)',-33.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00002','R2456H and R2456K exhibited a leftward shift of 13 and 8 mmHg, respectively, in the P1/2, but M2225R was similar to the WT channel (Fig. 4A).','Results (Fig. 4A)','high','同上；R2456K 为保守替换（保持电荷）的 HX 对照突变体，shift 8 mmHg。','hPIEZO1_HEK293_cell-attached_suction_Boltzmann-P1/2-shift_R2456K_Fig4A',NULL,'LITERATURE','2026-11-08',1,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(407,'MAIC:BX:00407',1,NULL,NULL,NULL,'negative pressure (pipette suction) via high-speed pressure clamp HSFC-1; voltage-dependence series -110 to +40 mV; Boltzmann dose-response (current vs pressure) for P1/2','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,40.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'40','ms','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGENE, 250 ng cDNA, recorded 24-48 h)','HEK293 (hPIEZO1 WT / HX mutants / G2218Stop)',NULL,7.3,'145 NaCl, 5 KCl, 3 MgCl2, 1 CaCl2, 10 HEPES (mM)','150 KCl, 0.5 MgCl2, 0.25 EGTA, 10 HEPES (mM); or 150 CsCl, 1 MgCl2, 1 CaCl2, 5 EGTA, 10 HEPES (mM)',-33.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00003','In cell-attached patches, hPIEZO1 had an open time of ∼40 ms when fit to a three-state linear model, shut-open-inactivated, with pressure sensitivity needed only in the shut-to-open rate constant (Fig. 1B).','Results (Fig. 1B)','medium','论文 own-data 的 WT hPIEZO1 唯一量化失活时程：open time ∼40 ms（shut-open-inactivated 三态线性模型拟合）。作为 τ_inact 近似入行（confidence=medium：是模型 open time，非单指数 τinact 拟合）。注意 intro 的 ''inactivates within ∼30 ms (2-4)'' 为引 Coste 文献，不 row（见 archive）。','hPIEZO1-WT_HEK293_cell-attached_suction_3-state-model-open-time_Fig1B',NULL,'LITERATURE','2026-11-08',1,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(408,'MAIC:BX:00408',1,NULL,NULL,79,'negative pressure (pipette suction) via high-speed pressure clamp HSFC-1; voltage-dependence series -110 to +40 mV; Boltzmann dose-response (current vs pressure) for P1/2','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,73.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'73','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGENE, 250 ng cDNA, recorded 24-48 h)','HEK293 (hPIEZO1 WT / HX mutants / G2218Stop)',NULL,7.3,'145 NaCl, 5 KCl, 3 MgCl2, 1 CaCl2, 10 HEPES (mM)','150 KCl, 0.5 MgCl2, 0.25 EGTA, 10 HEPES (mM); or 150 CsCl, 1 MgCl2, 1 CaCl2, 5 EGTA, 10 HEPES (mM)',-33.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00004','The unitary conductance at -33mV was 73 pS (0.5 mM Mg2+ in pipette).','Figure legend (C-terminal truncation figure; cell-attached patches)','medium','own-data 单通道斜率电导：C 端截断体 G2218Stop（非失活型）多通道 cell-attached patch，-33 mV，pipette 0.5 mM Mg2+。confidence=medium：数值在图注印出但 n 与拟合方式未标注。intro 的 ''∼70 pS...reduced to 35 pS by Mg+2 (3,4)'' 为引 Coste 2010/2012，不 row（见 archive）。','hPIEZO1-G2218Stop_HEK293_cell-attached_-33mV_0.5mM-Mg-pipette_Fig8(SI)',NULL,'LITERATURE','2026-11-08',1,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(409,'MAIC:BX:00409',1,NULL,NULL,NULL,'negative pipette pressure pulses 0 to -60 mm Hg (10 mm Hg increments); current-pressure relationship fitted with Boltzmann; channel identity attributed to Piezo1 by siRNA knockdown (Fig. 2) | STIMULUS: -60 mm Hg | ERROR-AS-REPORTED: 1.8','P50',-28.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-28.0','mm Hg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','none (endogenous MA current)','Neuro2A (N2A) mouse neuroblastoma (endogenous)',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00005','The current-pressure relationship is characterized by maximal opening at -60 mm Hg, with a pressure for half-maximal activation (P50) of -28.0 ± 1.8 mm Hg (Fig. 1F).','Results (Fig. 1F)','high','N2A 内源性 stretch-activated 电流的 P50（Piezo1 克隆前）；后续 Fig. 2 siRNA 敲低 Piezo1 将该内源性电流归因 Piezo1，故作为 PIEZO1 相关 own-data 入行。error_type 未在正文/图注声明（Fig. 1 系列图注惯例 mean±SEM），留空。maximal opening at −60 mm Hg 为刺激值记入 ctx。','endogenous-N2A_cell-attached_suction_Boltzmann-P50_-80mV_Fig1F','21','LITERATURE','2026-11-08',2,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(410,'MAIC:BX:00410',1,NULL,NULL,NULL,'negative pipette pressure pulses 0 to -60 mm Hg (10 mm Hg increments); Boltzmann fit of normalized current-pressure relationship | STIMULUS: -60 mm Hg | ERROR-AS-REPORTED: 2.8','P50',-28.1,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-28.1','mm Hg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection pIRES2-EGFP (mouse Piezo1 cloned from N2A; GFP+ cells recorded 12-48 h)','N2A / HEK293T',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00006','The current-pressure relationships in cells overexpressing Piezo1 and in endogenous N2A cells were similar, with P50 of -28.1 ± 2.8 and -31.2 ± 3.5 mm Hg in N2A- and HEK293T-overexpressing cells, respectively (Fig. 4H and K and 1F).','Results (Fig. 4H)','high','mPiezo1 转染 N2A 的 cell-attached 压敏曲线 P50。n=12 取自 Fig. 4 图注（H, n = 12）。error_type 未声明，留空。','mPiezo1-N2A_cell-attached_suction_Boltzmann-P50_-80mV_Fig4H','12','LITERATURE','2026-11-08',2,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(411,'MAIC:BX:00411',1,NULL,NULL,NULL,'negative pipette pressure pulses 0 to -60 mm Hg (10 mm Hg increments); Boltzmann fit of normalized current-pressure relationship | STIMULUS: -60 mm Hg | ERROR-AS-REPORTED: 3.5','P50',-31.2,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-31.2','mm Hg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection pIRES2-EGFP (mouse Piezo1 cloned from N2A; GFP+ cells recorded 12-48 h)','N2A / HEK293T',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00007','The current-pressure relationships in cells overexpressing Piezo1 and in endogenous N2A cells were similar, with P50 of -28.1 ± 2.8 and -31.2 ± 3.5 mm Hg in N2A- and HEK293T-overexpressing cells, respectively (Fig. 4H and K and 1F).','Results (Fig. 4K)','high','n=11 取自 Fig. 4 图注（K, n = 11）。error_type 未声明，留空。','mPiezo1-HEK293T_cell-attached_suction_Boltzmann-P50_-80mV_Fig4K','11','LITERATURE','2026-11-08',2,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(412,'MAIC:BX:00412',1,NULL,NULL,NULL,'negative pipette pressure pulses 0 to -60 mm Hg (10 mm Hg increments); current-pressure relationship fitted with Boltzmann; channel identity attributed to Piezo1 by siRNA knockdown (Fig. 2) | STIMULUS: -60 mm Hg | ERROR-AS-REPORTED: 1.4 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,22.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'22.9','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','none (endogenous MA current)','Neuro2A (N2A) mouse neuroblastoma (endogenous)',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00008','Negative pressure pulses evoked opening of endogenous channels (Fig. 1C), with a single-channel conductance of 22.9 ± 1.4 pS and Erev of +6.2 mV (Fig. 1D).','Results (Fig. 1D)','high','斜率电导（图注：''calculated from the slope of the linear regression line of each cell giving γ = 22.9 ± 1.4pS (mean ± SEM)''，n=4）。内源性 N2A 通道，经 Fig. 2 Piezo1 siRNA 归因。','endogenous-N2A_cell-attached_suction_single-channel_slope-conductance_Fig1D','4','LITERATURE','2026-11-08',2,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(413,'MAIC:BX:00413',1,NULL,NULL,NULL,'piezo-electrically driven glass probe, mechanical steps of 1 μm; I-V from -80 to +40 mV','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.6,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.6','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (N2A)','Neuro2A (N2A) mouse neuroblastoma (endogenous)',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00009','Current-voltage relationships of N2A and C2C12 MA currents were linear between -80 and +80 mV with reversal potentials (Erev) at +6.6 and +6.7 mV, respectively, and inward currents were suppressed with N-methyl-D-glucamine (NMDG)-chloride external solutions, suggesting cationic non-selective permeability (Fig. S1E).','Results (Fig. 1B; Fig. S1E)','high','I-V 线性（-80~+80 mV）且 NMDG 外液消除内向电流 → cation non-selective。+6.6 mV 为 N2A；同句 C2C12 的 +6.7 mV 无 Piezo1 归因（本文未对 C2C12 做 siRNA）→ archive。n=11 取自 Fig. 1B 图注（B, n = 11）。','endogenous-N2A_whole-cell_indentation_IV-Erev_Fig1B-S1E','11','LITERATURE','2026-11-08',2,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(414,'MAIC:BX:00414',1,NULL,NULL,NULL,'negative pipette pressure pulses 0 to -60 mm Hg (10 mm Hg increments); current-pressure relationship fitted with Boltzmann; channel identity attributed to Piezo1 by siRNA knockdown (Fig. 2) | STIMULUS: -60 mm Hg','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.2','mV','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','none (endogenous MA current)','Neuro2A (N2A) mouse neuroblastoma (endogenous)',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00010','Negative pressure pulses evoked opening of endogenous channels (Fig. 1C), with a single-channel conductance of 22.9 ± 1.4 pS and Erev of +6.2 mV (Fig. 1D).','Results (Fig. 1D)','high','单通道 I-V 的 Erev。mPiezo1 过表达细胞 Erev ~+6 mV 为约数（''with Erev ~+6 mV''）记入 note 不单列行。','endogenous-N2A_cell-attached_suction_single-channel_IV-Erev_Fig1D',NULL,'LITERATURE','2026-11-08',2,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(415,'MAIC:BX:00415',1,NULL,NULL,NULL,'negative pressure pulses 150 ms duration, stepwise -10 to -50 mm Hg (HSPC-1 pressure clamp); Boltzmann fit Po/(1-Po)=exp[α(P-P1/2)]; ΔVpatch = -55 mV | STIMULUS: -50 mm Hg | ERROR-AS-REPORTED: 2 (sem)','P50',44.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'44','mm Hg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (PIEZO1-1591-GFP / PIEZO1-1591-mCherry internal-insertion constructs; WT PIEZO1)','HEK293',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)','145 CsCl or 145 NaCl + 10 HEPES (mM), EGTA-buffered free Ca2+',-55.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00011','The pressure sensitivity in cell-attached patches gave a P1/2 of 44±2 mm Hg (n=6), almost identical to the WT PIEZO1 channel P1/2 of 45±3 mm Hg (n=5).','Results (Fig. 7b)','high','P 为 suction（负压）幅值，论文按正数印刷（Boltzmann 定义段：''P is the negative pressure (suction) [mmHg]''）——as-printed 不加符号。error_type=sem 依据系列图注 ''data points throughout represent mean±s.e.m.''。','PIEZO1-1591-GFP_HEK293_cell-attached_suction_Boltzmann-P1/2_Fig7b','6','LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(416,'MAIC:BX:00416',1,NULL,NULL,NULL,'negative pressure pulses 150 ms duration, stepwise -10 to -50 mm Hg (HSPC-1 pressure clamp); Boltzmann fit Po/(1-Po)=exp[α(P-P1/2)]; ΔVpatch = -55 mV | STIMULUS: -50 mm Hg | ERROR-AS-REPORTED: 3 (sem)','P50',45.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'45','mm Hg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (PIEZO1-1591-GFP / PIEZO1-1591-mCherry internal-insertion constructs; WT PIEZO1)','HEK293',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)','145 CsCl or 145 NaCl + 10 HEPES (mM), EGTA-buffered free Ca2+',-55.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00012','The pressure sensitivity in cell-attached patches gave a P1/2 of 44±2 mm Hg (n=6), almost identical to the WT PIEZO1 channel P1/2 of 45±3 mm Hg (n=5).','Results (Fig. 7b)','high','同上（WT PIEZO1，HEK293 瞬转）。','PIEZO1-WT_HEK293_cell-attached_suction_Boltzmann-P1/2_Fig7b','5','LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(417,'MAIC:BX:00417',1,NULL,NULL,NULL,'bleb-attached patch (recording_mode=OTHER: cytoskeleton-free membrane bleb); 150 ms square-wave negative pressure pulse of -55 mm Hg; pipette CsCl | STIMULUS: -55 mm Hg | ERROR-AS-REPORTED: 3 (sem)','P50',33.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'33','mm Hg','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'OTHER','transient transfection (PIEZO1-1591-GFP)','HEK293 membrane blebs (cytoskeleton-free)',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)','145 CsCl + 10 HEPES (mM)',-55.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00013','As seen with MscL, channel activation in blebs showed a leftward shift in the gating curve (P1/2=33±3 mm Hg, n=4) relative to cell-attached patches.','Results (Fig. 8d)','high','bleb-attached（无细胞骨架膜泡）相对 cell-attached 的左移（44→33 mmHg）即去细胞骨架机械保护效应；两 P1/2 均印刷但论文未印 delta 差值，按 SPEC 禁止自造差值，shift 由本行与 p50 44±2 行共同量化（delta_p50 flag=N，无需 resolution）。recording_mode enum 无 BLEB_ATTACHED → OTHER。','PIEZO1-1591-GFP_HEK293_bleb-attached_suction_Boltzmann-P1/2_Fig8d','4','LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(418,'MAIC:BX:00418',1,NULL,NULL,NULL,'negative pressure pulses 150 ms duration, stepwise -10 to -50 mm Hg (HSPC-1 pressure clamp); Boltzmann fit Po/(1-Po)=exp[α(P-P1/2)]; ΔVpatch = -55 mV | STIMULUS: -50 mm Hg','T50',NULL,NULL,4.5,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.5','mN m−1','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (PIEZO1-1591-GFP / PIEZO1-1591-mCherry internal-insertion constructs; WT PIEZO1)','HEK293',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)','145 CsCl or 145 NaCl + 10 HEPES (mM), EGTA-buffered free Ca2+',-55.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00014','From the co-expression data, we estimate that the tension at P1/2 is ∼4.5 mN m-1 for PIEZO1.','Results (Fig. 9; co-expression ratio P1/2(PIEZO1)/P1/2(MscL-G22S) ~0.4)','medium','膜张力半激活（t50）：由 PIEZO1/MscL-G22S 共表达 P1/2 比值 ∼0.4 与 MscL-G22S 张力校准（T1/2=11.3±0.6 mN m−1, inside-out, Laplace 定律）推算的 estimate，非直接 Boltzmann T50 拟合 → confidence=medium。unit as-printed ''mN m−1''；unit_db=''mN/m''。','PIEZO1-WT_HEK293_cell-attached_coexpression-MscL-G22S_tension-at-P1/2_Fig9',NULL,'LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(419,'MAIC:BX:00419',1,NULL,NULL,NULL,'negative pressure pulses 150 ms duration, stepwise -10 to -50 mm Hg (HSPC-1 pressure clamp); Boltzmann fit Po/(1-Po)=exp[α(P-P1/2)]; ΔVpatch = -55 mV | STIMULUS: -50 mm Hg | ERROR-AS-REPORTED: 11 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,55.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'55','ms','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (PIEZO1-1591-GFP / PIEZO1-1591-mCherry internal-insertion constructs; WT PIEZO1)','HEK293',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)','145 CsCl or 145 NaCl + 10 HEPES (mM), EGTA-buffered free Ca2+',-55.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00015','The kinetics of inactivation gave time constants similar to those previously reported for whole-cell mode (ΔVpatch=-55 mV: τ=55±11 ms; n=6).','Results (Fig. 7d)','high','电压依赖性失活（失活随去极化减慢，Fig. 7d）。老 verify 层 evidence ''tau = 55 +/- 11 ms (delta V patch = -55 mV)'' 与原文一致。','PIEZO1-1591-GFP_HEK293_cell-attached_ΔVpatch-55mV_tau-inact_Fig7d','6','LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(420,'MAIC:BX:00420',1,NULL,NULL,NULL,'negative pressure pulses 150 ms duration, stepwise -10 to -50 mm Hg (HSPC-1 pressure clamp); Boltzmann fit Po/(1-Po)=exp[α(P-P1/2)]; ΔVpatch = -55 mV | STIMULUS: -50 mm Hg','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,40.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'40','ms','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (PIEZO1-1591-GFP / PIEZO1-1591-mCherry internal-insertion constructs; WT PIEZO1)','HEK293',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)','145 CsCl or 145 NaCl + 10 HEPES (mM), EGTA-buffered free Ca2+',-55.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00016','Surprisingly when we introduced mCherry to position 1591 (called PIEZO1-1591-mCherry), the kinetics were similar to the WT channel (Fig. 5b) with an inactivation time constant of ∼40 ms in cell-attached mode.','Results (Fig. 5b)','medium','1591 位内插入 mCherry 构建体的 cell-attached 失活时间常数（约数，无 ±、无 n）→ confidence=medium。','PIEZO1-1591-mCherry_HEK293_cell-attached_tau-inact_Fig5b',NULL,'LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(421,'MAIC:BX:00421',1,NULL,NULL,NULL,'negative pressure pulses 150 ms duration, stepwise -10 to -50 mm Hg (HSPC-1 pressure clamp); Boltzmann fit Po/(1-Po)=exp[α(P-P1/2)]; ΔVpatch = -55 mV | STIMULUS: -50 mm Hg','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,62.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'62','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (PIEZO1-1591-GFP / PIEZO1-1591-mCherry internal-insertion constructs; WT PIEZO1)','HEK293',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)','145 CsCl or 145 NaCl + 10 HEPES (mM), EGTA-buffered free Ca2+',-55.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00017','Initial conductance in CsCl with ∼1 μM free Ca2+ is ∼62 pS (buffered using EGTA and calculated using Ca-EGTA Calculator v1.3, an online EGTA Ca2+ chelator calculator), and is reduced by almost half by 1 mM external Ca2+','Figure legend (Fig. 7c)','medium','图注 own-data（n=4 取自图注 ''data points represent mean±s.e.m.; n=4''）。约数 ∼62 pS → relation ''~''。1 mM 外 Ca2+ 使电导几乎减半但无具体数值 → archive。','PIEZO1-1591-GFP_HEK293_cell-attached_CsCl_1μM-free-Ca_conductance_Fig7c','4','LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(422,'MAIC:BX:00422',1,NULL,NULL,NULL,'fire-polished glass probe (2-4 μm, 30° angle), trapezoidal waveform, velocity 0.15 μm/ms, 300 ms hold, 0.5 μm increments; all currents at room temperature','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection (PIEZO1-1591-mCherry)','HEK293',NULL,7.2,'145 NaCl, 3 KCl, 1 MgCl2, 10 HEPES (mM)',NULL,-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00018','showing that the reversal potential is near 0 mV as in the wild-type PIEZO1 channel (data points represent mean±s.e.m.; n=5)','Figure legend (Fig. 6d)','medium','论文仅表述 ''near 0 mV''（无精确 Erev 值）→ value=0、relation=''~''、confidence=medium。','PIEZO1-1591-mCherry_HEK293_whole-cell_indentation_IV-Erev_Fig6d','5','LITERATURE','2026-11-08',3,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(423,'MAIC:BX:00423',1,NULL,NULL,NULL,'negative pressure pulses 500 ms via HSPC-1, 0 to -100 mm Hg (-10 mm Hg increments), 4-11 traces averaged per cell; Boltzmann I(P)=[1+exp(−(P–P50)/s)]−1; external solution zeroes membrane potential; compound (Jedi1/Yoda1/DMSO) in pipette solution | STIMULUS: -100 mm Hg | ERROR-AS-REPORTED: 3.4 (sem)','P50',-27.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-27.0','mm Hg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (mPiezo1)','HEK293T',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM)','130 NaCl, 5 KCl, 10 HEPES, 1 CaCl2, 1 MgCl2, 10 TEA-Cl (mM)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00019','The measured P50 (the pressure required for half maximal activation) is -27.0 ± 3.4, -16.7 ± 2.2, and -15.1 ± 0.9 mm Hg for DMSO, Jedi1, and Yoda1, respectively (Fig. 3i).','Results (Fig. 3i)','high','vehicle 对照行（DMSO 在 pipette 溶液中）。error_type=sem 依据图注 ''Each bar represents mean ± s.e.m.''。n 为散点图（Fig. 3i）未在正文印出。','mPiezo1_HEK293T_cell-attached_HSPC_Boltzmann-P50_-80mV_DMSO_Fig3i',NULL,'LITERATURE','2026-11-08',4,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(424,'MAIC:BX:00424',1,NULL,NULL,NULL,'negative pressure pulses 500 ms via HSPC-1, 0 to -100 mm Hg (-10 mm Hg increments), 4-11 traces averaged per cell; Boltzmann I(P)=[1+exp(−(P–P50)/s)]−1; external solution zeroes membrane potential; compound (Jedi1/Yoda1/DMSO) in pipette solution | STIMULUS: -100 mm Hg | MODULATOR: Jedi1 (agonist) | ERROR-AS-REPORTED: 2.2 (sem)','P50',-16.7,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-16.7','mm Hg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (mPiezo1)','HEK293T',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM)','130 NaCl, 5 KCl, 10 HEPES, 1 CaCl2, 1 MgCl2, 10 TEA-Cl (mM)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00020','The measured P50 (the pressure required for half maximal activation) is -27.0 ± 3.4, -16.7 ± 2.2, and -15.1 ± 0.9 mm Hg for DMSO, Jedi1, and Yoda1, respectively (Fig. 3i).','Results (Fig. 3i)','high','Jedi1 在 pipette 溶液中（''patches with either Jedi1 or Yoda1 present inside the pipette solution''）；浓度正文/方法未印出（Fig. 3g-i 未标注）→ modulator_concentration 留空。Jedi1 为 Piezo1 激动剂，对机械激活呈增敏（P50 左移 -27.0→-16.7）。','mPiezo1_HEK293T_cell-attached_HSPC_Boltzmann-P50_-80mV_Jedi1_Fig3i',NULL,'LITERATURE','2026-11-08',4,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(425,'MAIC:BX:00425',1,NULL,NULL,NULL,'negative pressure pulses 500 ms via HSPC-1, 0 to -100 mm Hg (-10 mm Hg increments), 4-11 traces averaged per cell; Boltzmann I(P)=[1+exp(−(P–P50)/s)]−1; external solution zeroes membrane potential; compound (Jedi1/Yoda1/DMSO) in pipette solution | STIMULUS: -100 mm Hg | MODULATOR: Yoda1 (agonist) | ERROR-AS-REPORTED: 0.9 (sem)','P50',-15.1,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-15.1','mm Hg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (mPiezo1)','HEK293T',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM)','130 NaCl, 5 KCl, 10 HEPES, 1 CaCl2, 1 MgCl2, 10 TEA-Cl (mM)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00021','The measured P50 (the pressure required for half maximal activation) is -27.0 ± 3.4, -16.7 ± 2.2, and -15.1 ± 0.9 mm Hg for DMSO, Jedi1, and Yoda1, respectively (Fig. 3i).','Results (Fig. 3i)','high','同上（Yoda1）。老 verify 层 delta_p50 evidence ''P50 shifted from -27.0 mmHg (DMSO) to -15.1 mmHg (Yoda1)'' 与原文一致。','mPiezo1_HEK293T_cell-attached_HSPC_Boltzmann-P50_-80mV_Yoda1_Fig3i',NULL,'LITERATURE','2026-11-08',4,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(426,'MAIC:BX:00426',1,NULL,NULL,NULL,'FLIPR 96-well GCAMP6s Ca2+ imaging dose-response; curve fitted with Boltzmann equation; vector-transfected signal subtracted; n=4 wells per dose point (recording_mode/stimulus_type = OTHER: non-electrophysiological Ca2+ imaging) | MODULATOR: Jedi1 (agonist)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.5',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OTHER','transient transfection (mPiezo1 + GCAMP6s)','HEK293T',NULL,7.2,'1× HBSS (1.3 mM Ca2+), 10 mM HEPES',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00024','In line with Jedi possessing a common structural motif, Jedi1 and Jedi2 had a comparable EC50 of ~200 and 158 μM, and Hill coefficient of ~1.5 and 1.6 for mPiezo1, respectively (Fig. 2c, d).','Results (Fig. 2c)','medium','论文自称 Hill coefficient 但拟合用 Boltzmann 方程（Fig. 2 图注）；约数无 ± → confidence=medium。unitless。','mPiezo1_HEK293T_FLIPR-GCAMP6s_Jedi1_dose-response-Hill_Fig2c','4','LITERATURE','2026-11-08',4,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(427,'MAIC:BX:00427',1,NULL,NULL,NULL,'FLIPR 96-well GCAMP6s Ca2+ imaging dose-response; curve fitted with Boltzmann equation; vector-transfected signal subtracted; n=4 wells per dose point (recording_mode/stimulus_type = OTHER: non-electrophysiological Ca2+ imaging) | MODULATOR: Jedi2 (agonist)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1.6,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.6',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'OTHER','transient transfection (mPiezo1 + GCAMP6s)','HEK293T',NULL,7.2,'1× HBSS (1.3 mM Ca2+), 10 mM HEPES',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00025','In line with Jedi possessing a common structural motif, Jedi1 and Jedi2 had a comparable EC50 of ~200 and 158 μM, and Hill coefficient of ~1.5 and 1.6 for mPiezo1, respectively (Fig. 2c, d).','Results (Fig. 2d)','medium','同上（Jedi2）。','mPiezo1_HEK293T_FLIPR-GCAMP6s_Jedi2_dose-response-Hill_Fig2d','4','LITERATURE','2026-11-08',4,'2026-11-08 00:00:00.000000',NULL);
