INSERT INTO "biophysics_experiment" VALUES(431,'MAIC:BX:00431',1,NULL,NULL,NULL,'positive pressure steps, 300 ms, HSPC-1 | ERROR-AS-REPORTED: 4.2 (sem)','P50',26.7,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'26.7','mmHg','POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00032','inside-out: P50 = +26.7 ± 4.2 mmHg; N=7','Results (Figure 2D)','high','Paper notes likely underestimate due to premature patch rupture before saturation.','mPiezo1_HEK293t_inside-out_pos-pressure_Boltzmann-P50_-80mV_Fig2D','7','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(432,'MAIC:BX:00432',1,NULL,NULL,NULL,'positive pressure steps, 300 ms, HSPC-1 | ERROR-AS-REPORTED: 9.6 (sem)','P50',70.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'70.0','mmHg','POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00033','For outside-out patches, much larger pressures were required for activation than other configurations (positive pressure: P50 = +70.0 ± 9.6 mmHg; N=11','Results (Figure 2D)','high','Paper notes likely underestimate due to premature patch rupture before saturation.','mPiezo1_HEK293t_outside-out_pos-pressure_Boltzmann-P50_-80mV_Fig2D','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
