INSERT INTO "biophysics_experiment" VALUES(434,'MAIC:BX:00434',1,NULL,NULL,NULL,'negative pressure steps, 300 ms, HSPC-1 high-speed pressure clamp; simultaneous patch imaging, tension via Laplace''s law | ERROR-AS-REPORTED: 0.1 (sem)','T50',NULL,NULL,2.7,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.7','mN/m','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00035','For cell-attached patches, we found that Piezo1 channel activity is well described by a Boltzmann function with a tension of half-maximal activation T50 = 2.7 ± 0.1 mN/m and a slope factor k = 0.8 ± 0.1 (N = 15)','Results (Figure 3B)','high','Tension computed from measured patch curvature via Laplace''s law T=R·Δp/2. N = 15 cells, 218 responses.','mPiezo1_HEK293t_cell-attached_neg-pressure_Boltzmann-T50_Fig3B','15','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(435,'MAIC:BX:00435',1,NULL,NULL,NULL,'negative pressure steps, 300 ms, HSPC-1 | ERROR-AS-REPORTED: 0.3 (sem)','T50',NULL,NULL,4.7,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.7','mN/m','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00036','patches required slightly more tension for activation (T50 = 4.7 ± 0.3 mN/m; N = 10','Results (Figure 3C)','high','N = 10 cells, 123 responses. P<0.001 vs cell-attached.','mPiezo1_HEK293t_inside-out_neg-pressure_Boltzmann-T50_Fig3C','10','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(436,'MAIC:BX:00436',1,NULL,NULL,NULL,'5 s prepulse (0, +5 or +10 mmHg) followed by 300 ms negative test pulse (0 to −50 mmHg, △5 mmHg); HSPC-1; simultaneous patch imaging for tension | ERROR-AS-REPORTED: 0.1 (sem)','T50',NULL,NULL,2.2,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.2','mN/m','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00037','from T50 = 2.2 ± 0.1 mN/m without a prepulse (0 mmHg) to T50 = 1.4 ± 0.1 mN/m with a +5 mmHg prepulse (P<0.001; N=11; Figure 5D,E, and G)','Results (Figure 5D and G)','high','Prepulse protocol: 5 s prepulse then 300 ms negative test pulses. Same quote spans the +5 mmHg prepulse T50 row.','mPiezo1_HEK293t_cell-attached_prepulse-0mmHg_Boltzmann-T50_Fig5D','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(437,'MAIC:BX:00437',1,NULL,NULL,NULL,'5 s prepulse (0, +5 or +10 mmHg) followed by 300 ms negative test pulse (0 to −50 mmHg, △5 mmHg); HSPC-1; simultaneous patch imaging for tension | ERROR-AS-REPORTED: 0.1 (sem)','T50',NULL,NULL,1.4,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.4','mN/m','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00038','from T50 = 2.2 ± 0.1 mN/m without a prepulse (0 mmHg) to T50 = 1.4 ± 0.1 mN/m with a +5 mmHg prepulse (P<0.001; N=11; Figure 5D,E, and G)','Results (Figure 5E and G)','high','The +5 mmHg prepulse approximately flattens the patch dome (zero resting tension), unmasking inherent tension sensitivity.','mPiezo1_HEK293t_cell-attached_prepulse+5mmHg_Boltzmann-T50_Fig5E','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(438,'MAIC:BX:00438',1,NULL,NULL,NULL,'5 s prepulse (0, +5 or +10 mmHg) followed by 300 ms negative test pulse (0 to −50 mmHg, △5 mmHg); HSPC-1; simultaneous patch imaging for tension | ERROR-AS-REPORTED: 0.2 (sem)','T50',NULL,NULL,1.8,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.8','mN/m','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00039','Upon a +10 mmHg prepulse, the T50 was also leftward shifted to that without a prepulse, but to a lesser extent than with a +5 mmHg prepulse (T50 = 1.8 ± 0.2 mN/m; P=0.03; Figure 5F and G)','Results (Figure 5F and G)','high',NULL,'mPiezo1_HEK293t_cell-attached_prepulse+10mmHg_Boltzmann-T50_Fig5F','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(439,'MAIC:BX:00439',1,NULL,NULL,NULL,'5 s prepulse (0, +5 or +10 mmHg) followed by 300 ms negative test pulse (0 to −50 mmHg, △5 mmHg); HSPC-1; simultaneous patch imaging for tension | ERROR-AS-REPORTED: 2.8 (sem)','P50',-16.8,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-16.8','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00040','the pressure of half-maximal activation was shifted by ~9 mmHg towards lower pressures (P50 = -16.8 ± 2.8 mmHg with a 0 mmHg prepulse and P50 = -7.7 ± 1.1 mmHg with a +5 mmHg prepulse; N=11; P<0.05)','Results (Figure 5A and B)','high','Same quote spans the +5 mmHg prepulse P50 and delta rows.','mPiezo1_HEK293t_cell-attached_prepulse-0mmHg_Boltzmann-P50_Fig5B','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(440,'MAIC:BX:00440',1,NULL,NULL,NULL,'5 s prepulse (0, +5 or +10 mmHg) followed by 300 ms negative test pulse (0 to −50 mmHg, △5 mmHg); HSPC-1; simultaneous patch imaging for tension | ERROR-AS-REPORTED: 1.1 (sem)','P50',-7.7,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-7.7','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00041','the pressure of half-maximal activation was shifted by ~9 mmHg towards lower pressures (P50 = -16.8 ± 2.8 mmHg with a 0 mmHg prepulse and P50 = -7.7 ± 1.1 mmHg with a +5 mmHg prepulse; N=11; P<0.05)','Results (Figure 5A and B)','high',NULL,'mPiezo1_HEK293t_cell-attached_prepulse+5mmHg_Boltzmann-P50_Fig5B','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(441,'MAIC:BX:00441',1,NULL,NULL,NULL,'5 s prepulse (0, +5 or +10 mmHg) followed by 300 ms negative test pulse (0 to −50 mmHg, △5 mmHg); HSPC-1; simultaneous patch imaging for tension | ERROR-AS-REPORTED: 2.9 (sem)','P50',-13.5,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-13.5','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00042','P50 = -16.8 ± 2.8 mmHg with a 0 mmHg prepulse and P50 = -13.5 ± 2.9 mmHg with a +10 mmHg prepulse; N=11; P>0.05','Results (Figure 5B)','high',NULL,'mPiezo1_HEK293t_cell-attached_prepulse+10mmHg_Boltzmann-P50_Fig5B','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(442,'MAIC:BX:00442',1,NULL,NULL,NULL,'5 s prepulse (0, +5 or +10 mmHg) followed by 300 ms negative test pulse (0 to −50 mmHg, △5 mmHg); HSPC-1; simultaneous patch imaging for tension','P50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'9','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (Fugene), Mouse Piezo1-IRES-GFP','HEK293t',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose, pH 7.3 (KOH)','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2, pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00043','the pressure of half-maximal activation was shifted by ~9 mmHg towards lower pressures','Results (Figure 5B)','high','Paper-printed shift magnitude (~9 mmHg, leftward towards lower pressures); no arithmetic differencing by extractor. Component P50s are separate p50 rows. Modulator is mechanical (prepulse), not chemical, hence modulator fields blank.','mPiezo1_HEK293t_cell-attached_prepulse+5mmHg_vs_0mmHg_delta-P50_Fig5B','11','LITERATURE','2026-11-08',5,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(443,'MAIC:BX:00443',1,NULL,NULL,NULL,'fluid flow out of a capillary tube (tip diameter 350 μm, flow 20 μL/s) onto excised outside-out patch; unitary currents at −80 mV','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'25','pS','SHEAR_STRESS',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','native (no heterologous expression)','freshly isolated murine mesenteric endothelium (WT mice)',NULL,7.4,'135 NaCl, 4 KCl, 2 CaCl2, 1 MgCl2, 10 glucose, 10 HEPES, pH 7.4 (NaOH)','145 KCl, 1 MgCl2, 0.5 EGTA, 10 HEPES, pH 7.2 (KOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00044','The unitary current size (~1.95 pA at -80 mV) and therefore unitary conductance (~25 pS) were as expected for PIEZO1 channels (Rode et al., 2017).','Results (Figure 3A1/B1 context)','medium','unit_db 留空：pS 为固定单位（schema 约定 conductance 无 enum）。value as-printed ''~25 pS''（近似值，由 unitary current ~1.95 pA at −80 mV 除以 80 mV 得出的斜率电导）；论文未给独立斜率拟合或 error/n，故 confidence=medium。Discussion 重申 ''distinctive unitary conductance of about 25 pS''。~1.95 pA 是电流非电导（SPEC pA/pS 裁决），仅入 archive。','native-PIEZO1_mouse-mesenteric-endothelium_outside-out_fluid-flow_unitary-conductance_Fig3A1',NULL,'LITERATURE','2026-11-08',6,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(444,'MAIC:BX:00444',1,NULL,NULL,NULL,'pressure steps evoking single-channel openings; patch clamped at −80 mV; amplitude histograms at multiple voltages | ERROR-AS-REPORTED: 2.5','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,24.7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'24.7','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','native (endogenous Piezo1; mES cells)','mouse embryonic stem (mES) cells',NULL,7.3,'150 NaCl, 3 KCl, 2 CaCl2, 2 MgCl2, 10 HEPES, 10 glucose, pH 7.3 (NaOH), 310 mOsm/kg','150 KCl, 10 HEPES, 10 EGTA, pH 7.3 (NaOH), 310 mOsm/kg',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00045','Amplitude histograms at multiple voltages revealed a single channel conductance of 24.7 ± 2.5 pS in standard physiological conditions (Figure 2B and C).','Results (Figure 2B and C)','high','unit_db 留空：pS 为固定单位。error_type=none 因论文未声明 SEM/SD（error 值 2.5 as-printed）。own-data（mES 细胞内源性 Piezo1，excised outside-out，pressure clamp 激活）。Fig 2C 图注复述同一数值。','endogenous-Piezo1_mES_outside-out_pressure-clamp_slope-conductance_Fig2C',NULL,'LITERATURE','2026-11-08',7,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(445,'MAIC:BX:00445',1,NULL,NULL,NULL,'poking steps of increasing depth (piezo-actuated round-end probe); I-V relation at multiple voltages under bi-ionic conditions (internal always KCl-based)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native (endogenous Piezo1; mES cells)','mouse embryonic stem (mES) cells',NULL,7.3,'bi-ionic series — NaCl: 150 NaCl, 10 HEPES, 10 glucose, pH 7.3; CaCl2: 90 CaCl2, 7.5 HEPES, 7.5 glucose, pH 7.4; also NaGluconate and NMDG-Cl variants','150 KCl, 10 HEPES, 10 EGTA, pH 7.3 (KOH), 310 mOsm/kg',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00046','The pink curve is done using NaCl in the bath solution. The Erev sits at 4 mV, roughly in between the Erev for potassium and sodium in these conditions, indicating that both ions are equally likely to travel through the pore.','Results (Figure 1B legend)','medium','unit_db 留空：reversal_potential 为固定 mV 单位。representative I-V 读值非群体均值，无 error/n；论文声明未做 liquid junction potential 校正（估计值 4.3 mV for NaCl/KCl）→ confidence=medium。支持 PK = PNa。','endogenous-Piezo1_mES_whole-cell_poking_biionic-NaCl-out_KCl-in_Erev_Fig1B',NULL,'LITERATURE','2026-11-08',7,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(446,'MAIC:BX:00446',1,NULL,NULL,NULL,'poking steps of increasing depth (piezo-actuated round-end probe); I-V relation at multiple voltages under bi-ionic conditions (internal always KCl-based)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'15','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native (endogenous Piezo1; mES cells)','mouse embryonic stem (mES) cells',NULL,7.3,'bi-ionic series — NaCl: 150 NaCl, 10 HEPES, 10 glucose, pH 7.3; CaCl2: 90 CaCl2, 7.5 HEPES, 7.5 glucose, pH 7.4; also NaGluconate and NMDG-Cl variants','150 KCl, 10 HEPES, 10 EGTA, pH 7.3 (KOH), 310 mOsm/kg',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00047','the green curve taken with calcium as the only cation in the bath shifts the Erev to +15 mV, closer to the Erev of calcium than to that of potassium in these conditions, indicating a slightly higher permeability for calcium than for potassium.','Results (Figure 1B legend)','medium','value as-printed ''+15 mV''（存为 15）。representative 读值，无 error/n；未做 LJP 校正（估计 8.2 mV for CaCl2/KCl）→ medium。支持 PCa > PK。','endogenous-Piezo1_mES_whole-cell_poking_biionic-CaCl2-out_KCl-in_Erev_Fig1B',NULL,'LITERATURE','2026-11-08',7,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(447,'MAIC:BX:00447',1,NULL,NULL,NULL,'high-speed pressure clamp (HSPC-1); positive pressure pulses ~500 ms for Boltzmann pressure-gating curve (Fig 2, +50 mV) | ERROR-AS-REPORTED: 2.6 (sd)','P50',48.7,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'48.7','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','HEK293 transient transfection with mPiezo1 plasmid (250 ng, FuGENE)','HEK293',NULL,7.3,'145 NaCl, 5 KCl, 3 MgCl2, 10 HEPES, 0.1 CaCl2 (mM), pH 7.3 (NaOH)','133 CsCl, 10 HEPES, 5 EGTA, 3 MgCl2 (mM), pH 7.3 (CsOH)',50.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00048','A fit of those data to the Boltzmann equation yielded a half activation pressure P 1/2 = 48.7 ± 2.6 mmHg and a slope sensitivity of 6.6 ± 2.2 mmHg/e-fold','Results (Fig 2C)','high','对照组（无 GsMTx4）outside-out 正压 Boltzmann 中点；误差类型 SD（同图 Fig 2 caption 对平行数值标注 (SD)）；Fig 2 caption 印 48.7 ±1.3 mmHg (SD)，以正文 48.7 ± 2.6 为准。room temperature（数值未报告）。','mPIEZO1_HEK293_outside-out_HSPC_Boltzmann-P50_+50mV_control_Fig2C',NULL,'LITERATURE','2026-11-08',8,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(448,'MAIC:BX:00448',1,NULL,NULL,NULL,'high-speed pressure clamp (HSPC-1); positive pressure pulses ~500 ms for Boltzmann pressure-gating curve (Fig 2, +50 mV) | MODULATOR: GsMTx4 (L-enantiomer) (blocker) 3.0 µM | ERROR-AS-REPORTED: 2.2 (sd)','P50',76.9,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'76.9','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','HEK293 transient transfection with mPiezo1 plasmid (250 ng, FuGENE)','HEK293',NULL,7.3,'145 NaCl, 5 KCl, 3 MgCl2, 10 HEPES, 0.1 CaCl2 (mM), pH 7.3 (NaOH)','133 CsCl, 10 HEPES, 5 EGTA, 3 MgCl2 (mM), pH 7.3 (CsOH)',50.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00049','the fit shows P 1/2 shifted to 76.9 ± 2.2 mmHg and the slope sensitivity unchanged at 7.7± 2.5 mmHg/e-fold','Results (Fig 2C)','high','GsMTx4 存在下的 P1/2；饱和电流假设与对照相同（正文说明 patch 在饱和前 lysis，无法直接到达饱和）。TEXT-VS-CAPTION：Fig 2 caption 对同一 Panel B 平行值印 76.8 ± 2.2 mmHg，正文印 76.9 ± 2.2——以正文 76.9 为准（与上一行 48.7 的 caption 分歧处理同规则；标准审 MINOR-2 补声明）。浓度：Fig 2 caption 标 Panel B 为 3.0 µM（正文叙述浓度范围 1-4 µM）。误差 SD（caption 平行标注）。room temperature。','mPIEZO1_HEK293_outside-out_HSPC_Boltzmann-P50_+50mV_GsMTx4-3uM_Fig2C',NULL,'LITERATURE','2026-11-08',8,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(449,'MAIC:BX:00449',1,NULL,NULL,NULL,'high-speed pressure clamp (HSPC-1); positive pressure pulses ~500 ms for Boltzmann pressure-gating curve (Fig 2, +50 mV) | MODULATOR: GsMTx4 (L-enantiomer) (blocker)','P50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'30','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','HEK293 transient transfection with mPiezo1 plasmid (250 ng, FuGENE)','HEK293',NULL,7.3,'145 NaCl, 5 KCl, 3 MgCl2, 10 HEPES, 0.1 CaCl2 (mM), pH 7.3 (NaOH)','133 CsCl, 10 HEPES, 5 EGTA, 3 MgCl2 (mM), pH 7.3 (CsOH)',50.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00050','GsMTx4 produced a ~30mmHg rightward shift in the pressure-gating curve and was active on closed channels','Abstract','medium','论文印出的近似位移（~30 mmHg，向右/高压方向）；误差类型未标。error_low/high 记录论文叙述的量级（约 30）。前两行 P1/2（48.7→76.9）亦可用于交叉核对，但按 as-printed 规则不自算差值。','mPIEZO1_HEK293_outside-out_HSPC_delta-P50_GsMTx4_abstract',NULL,'LITERATURE','2026-11-08',8,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(450,'MAIC:BX:00450',1,NULL,NULL,NULL,'High Speed Pressure Clamp; saturating 70 mmHg pressure pulses; I/V and single-channel protocols at -100 to +100 mV | STIMULUS: 70 mmHg | ERROR-AS-REPORTED: 0.9 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,41.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'41.3','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','N2a cells overexpressing mPIEZO1 (IRES-EGFP)','Neuro2a (N2a)',NULL,7.4,'140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free','140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00052','Inward slope conductance was significantly higher than outward slope conductance (41.3 ± 0.9 pS and 27.1 ± 1.2 pS, respectively, three cells.','Fig 1b (caption)','high','对称 Na+ 无二价阳离子液，70 mmHg 饱和压力下的单通道斜率电导（内向）；SEM。','mPIEZO1_N2a_outside-out_sym-Na-divalent-free_slope-conductance_inward_Fig1b','3','LITERATURE','2026-11-08',9,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(451,'MAIC:BX:00451',1,NULL,NULL,NULL,'High Speed Pressure Clamp; saturating 70 mmHg pressure pulses; I/V and single-channel protocols at -100 to +100 mV | STIMULUS: 70 mmHg | ERROR-AS-REPORTED: 1.2 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,27.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'27.1','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','N2a cells overexpressing mPIEZO1 (IRES-EGFP)','Neuro2a (N2a)',NULL,7.4,'140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free','140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00053','Inward slope conductance was significantly higher than outward slope conductance (41.3 ± 0.9 pS and 27.1 ± 1.2 pS, respectively, three cells.','Fig 1b (caption)','high','同条件下外向斜率电导；与内向 41.3 pS 的差异解释了宏观电流外向整流（Fig 1a）而瞬时电流整流指数 ~1。SEM。','mPIEZO1_N2a_outside-out_sym-Na-divalent-free_slope-conductance_outward_Fig1b','3','LITERATURE','2026-11-08',9,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(452,'MAIC:BX:00452',1,NULL,NULL,NULL,'High Speed Pressure Clamp; saturating 70 mmHg pressure pulses; I/V and single-channel protocols at -100 to +100 mV | STIMULUS: 70 mmHg | ERROR-AS-REPORTED: 3 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,60.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'60.9','ms','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','N2a cells overexpressing mPIEZO1 (IRES-EGFP)','Neuro2a (N2a)',NULL,7.4,'140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free','140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00054','and here we also measured fast inactivation time constants (τinact = 60.9 ± 3 ms, eight cells)','Results (Fig 2)','high','负电位（-60 mV）压力刺激下的快失活时间常数；SEM。注意 Fig 5f caption 平行印 60.9 ± 5.1 ms (9 cells)，正文 60.9 ± 3.0 ms (9 cells, Fig 5 段) —— 以本处主报告 60.9 ± 3 ms (8 cells) 为准，差异记 archive。','mPIEZO1_N2a_outside-out_sym-Na_70mmHg_-60mV_tau-inact_Fig2','8','LITERATURE','2026-11-08',9,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(453,'MAIC:BX:00453',1,NULL,NULL,NULL,'saturating pressure pulses; Erev measured with ramp and voltage-step protocols | STIMULUS: 70 mmHg | ERROR-AS-REPORTED: 1 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'43','mV','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','N2a cells overexpressing mPIEZO1','Neuro2a (N2a)',NULL,7.4,'140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 — extracellular','10 NaCl, 10 HEPES, 5 EGTA, 260 sucrose (mM), pH 7.4 — intracellular (pipette), low Na',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00055','We altered the reversal potential by lowering the intracellular Na+ concentration (NaCl 10 mM inside, NaCl 140 mM outside) and measured the Erev of +43 ± 1 mV (five cells) with a ramp protocol','Results (Supplementary Fig 1a)','high','Na+ 内液 10 mM/外液 140 mM 时的反转电位（ramp 协议）；SEM。用于证明外向渗透（而非电压本身）重置通道失活。','mPIEZO1_N2a_outside-out_low-Na-in_Erev_ramp_SuppFig1a','5','LITERATURE','2026-11-08',9,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(454,'MAIC:BX:00454',1,NULL,NULL,NULL,'saturating pressure pulses; Erev measured with ramp and voltage-step protocols | STIMULUS: 70 mmHg | ERROR-AS-REPORTED: 2 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,45.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'45','mV','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','N2a cells overexpressing mPIEZO1','Neuro2a (N2a)',NULL,7.4,'140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 — extracellular','10 NaCl, 10 HEPES, 5 EGTA, 260 sucrose (mM), pH 7.4 — intracellular (pipette), low Na',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00056','a similar Erev of +45 ± 2 mV, three cells were measured using a voltage step protocol','Results (Supplementary Fig 1a, b)','high','同离子条件、电压阶跃协议测得的 Erev；SEM。','mPIEZO1_N2a_outside-out_low-Na-in_Erev_step_SuppFig1ab','3','LITERATURE','2026-11-08',9,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(455,'MAIC:BX:00455',1,NULL,NULL,NULL,'pressure-response protocol for P50 (Fig 5e) | ERROR-AS-REPORTED: 3.1 (sem)','P50',38.9,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'38.9','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','N2a Piezo1-/- cells (CRISPR KO) overexpressing mPIEZO1','N2a Piezo1-/-',NULL,7.4,'140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free','140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00057','P50 for mPIEZO1, P1/P2 and P2/P1 were 38.9 ± 3.1 mmHg, (21 cells)','Results (Fig 5c, e)','high','老 verify 层 threshold=N，但全文 own-data 含此 mPIEZO1 P50（N2a Piezo1-/- 细胞过表达 mPIEZO1，outside-out，-60 mV）——补充提取。SEM。as-printed 正值（论文未标负号）。','mPIEZO1_N2a-P1KO_outside-out_pressure-response_P50_Fig5e','21','LITERATURE','2026-11-08',9,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(456,'MAIC:BX:00456',1,NULL,NULL,NULL,'pressure-response protocol for P50 (Supplementary Fig 6a) | ERROR-AS-REPORTED: 2.7 (sem)','P50',51.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'51.0','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','N2a Piezo1-/- cells overexpressing zebrafish DrPIEZO1 (IRES-EGFP)','N2a Piezo1-/-',NULL,7.4,'140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free','140 NaCl, 10 HEPES, 5 EGTA (mM), pH 7.4 (NaOH) — symmetrical, divalent-free',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00058','DrPIEZO1 showed mechanosensitivity in outside-out patches with a pressure response behavior of P50 of 51.0 ± 2.7 mmHg (n = 9), which is typical for several PIEZO1 channels','Results (Supplementary Fig 6a)','high','斑马鱼 DrPIEZO1 直系同源（非 mouse/human PIEZO1）；作为 PIEZO1 家族测量 row 并在此声明。SEM。as-printed 正值。','DrPIEZO1_N2a-P1KO_outside-out_pressure-response_P50_SuppFig6a','9','LITERATURE','2026-11-08',9,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(457,'MAIC:BX:00457',1,NULL,NULL,NULL,'HSPC-1; 4 s sinusoidal pressure cycles oscillating between +5 and -50 mmHg, 0.5-50 Hz; single-channel events resolved at 50 Hz | STIMULUS: -50 mmHg | ERROR-AS-REPORTED: 1.7 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,35.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'35.5','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK293t transient transfection with mouse Piezo1-pIRES-EGFP','HEK293t',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00059','single channel amplitudes measured during the last second of a 50 Hz stimulation in patches with few channels were identical (35.5±1.7 pS; N = 3) to previously published values for Piezo1 (29-37 pS)','Results (Figure S3A–B)','high','老 flag conductance=N，但这是本文 own-data 单通道电导（50 Hz 正弦刺激最后 1 s 的单位事件幅度，n=3 patches）——补充提取。SEM（论文统一 mean±s.e.m.）。正文另一处印 35.1±1.7 pS (N=3)（模型论证段），两处印值略异，以先出现的 35.5±1.7 为准。','mPiezo1_HEK293t_cell-attached_HSPC_50Hz-sinusoid_+5to-50mmHg_-80mV_single-channel-conductance_FigS3','3','LITERATURE','2026-11-08',10,'2026-11-08 00:00:00.000000',NULL);
