INSERT INTO "biophysics_experiment" VALUES(465,'MAIC:BX:00465',1,NULL,NULL,80,'fire-polished glass probe (tip 3-5 µm), 0.5 µm/ms, 1 µm increments, 80° angle; mean indentation depth 6.5 µm; voltage steps -150 to +150 mV (Δ30 mV); intersweep interval 10 s | STIMULUS: 6.5 µm | ERROR-AS-REPORTED: 14.3 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,239.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'239.3','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','HEK293t-P1Ko (Piezo1 knockout) transient transfection with wtP1 / E2257K/E2258K/D2264K (± ruthenium red 10 µM during expression)','HEK293t-P1Ko',NULL,7.3,'130 NaCl, 3 KCl, 1 MgCl2, 10 HEPES, 2.5 CaCl2, 10 glucose (mM), pH 7.3 (NaOH)','133 CsCl, 10 HEPES, 5 EGTA, 1 MgCl2, 1 CaCl2, 4 MgATP, 0.4 Na2GTP (mM), pH 7.3 (CsOH)',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00067','at -90 mV: wtP1 τ = 2.5 ± 0.3 ms, n = 10; E2257K/E2258K/D2264K τ = 9.5 ± 1.1 ms, n = 6; p < 5e-7; at +90 mV: wtP1 fast τ = 108.1 ± 7.7 ms; E2257K/E2258K/D2264K fast τ = 239.3 ± 14.3 ms, p < 5e-4','Results (Figures 4E-4H)','high','突变体 +90 mV fast deactivation τ。SEM。','E2257K_E2258K_D2264K_HEK293t-P1ko_whole-cell_indentation_tau-deact-fast_+90mV_Fig4G',NULL,'LITERATURE','2026-11-08',11,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(466,'MAIC:BX:00466',1,NULL,NULL,NULL,'HSPC-1 ramp-like protocol: 0 to -60 mmHg in 1 mmHg steps x 50 ms (~3 s), +5 mmHg prepulse 2 s; +60 mV chosen to minimize inactivation | STIMULUS: -60 mmHg | ERROR-AS-REPORTED: 7.2 (sd)','P50',-33.1,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-33.1','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','endogenous mPiezo1 (no transfection)','Neuro2A (wild-type)',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM), pH 7.3 (KOH) — high K+ to zero membrane potential','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2 (mM), pH 7.3 (NaOH)',60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00068','mean ± SD first=-33.1±7.2 mmHg, second=-31.1±7.7 mmHg; ΔP50=+2.0±8.2 mmHg','Results (Figure 1—figure supplement 2J)','high','内源性 Piezo1（Neuro2A）全体 patch 的群体 P50（第一轮 ramp 协议）；SD（论文 Methods：mean ± SD unless otherwise indicated）。n 留空（对抗审 M3 修正）：该群体的 patch 基数论文记为 281 patches（Fig S2A/D）；261 是 Fig S2I 重复协议配对分析数，不 attach 到 P50——语义错位已纠正。','mPiezo1endogenous_Neuro2A_cell-attached_ramp-0to-60mmHg_+60mV_P50_all-patches_Fig1F-S2J',NULL,'LITERATURE','2026-11-08',12,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(467,'MAIC:BX:00467',1,NULL,NULL,NULL,'HSPC-1 ramp-like protocol: 0 to -60 mmHg in 1 mmHg steps x 50 ms (~3 s), +5 mmHg prepulse 2 s; +60 mV chosen to minimize inactivation | STIMULUS: -60 mmHg','P50',-23.2,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-23.2','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','endogenous mPiezo1 (no transfection)','Neuro2A (wild-type)',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM), pH 7.3 (KOH) — high K+ to zero membrane potential','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2 (mM), pH 7.3 (NaOH)',60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00069','1 channel: P50=-23.2 mmHg, k=-3.3 mmHg; 5 channels: P50=-23.7 mmHg, k=-4.2 mmHg','Results (Figure 2A)','high','理想化 1 通道 patch 的平均开放概率 sigmoid fit；n=35 patches 取自 Fig 2 caption。fit 值未带 ±。与全体 patch 平均（-33.1）差异来自分析方法不同（理想化 Po 曲线 vs 单 patch sigmoid fit），两行并存、condition_key 区分。','mPiezo1endogenous_Neuro2A_cell-attached_ramp_+60mV_P50_1-channel_Fig2A','35','LITERATURE','2026-11-08',12,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(468,'MAIC:BX:00468',1,NULL,NULL,NULL,'HSPC-1 ramp-like protocol: 0 to -60 mmHg in 1 mmHg steps x 50 ms (~3 s), +5 mmHg prepulse 2 s; +60 mV chosen to minimize inactivation | STIMULUS: -60 mmHg','P50',-23.7,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-23.7','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','endogenous mPiezo1 (no transfection)','Neuro2A (wild-type)',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM), pH 7.3 (KOH) — high K+ to zero membrane potential','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2 (mM), pH 7.3 (NaOH)',60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00070','1 channel: P50=-23.2 mmHg, k=-3.3 mmHg; 5 channels: P50=-23.7 mmHg, k=-4.2 mmHg','Results (Figure 2A)','high','5 通道 patch（n=9，Fig 2 caption）；与 1 通道值几乎相同——论文核心结论：低密度下通道互不影响机械敏感性。','mPiezo1endogenous_Neuro2A_cell-attached_ramp_+60mV_P50_5-channel_Fig2A','9','LITERATURE','2026-11-08',12,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(469,'MAIC:BX:00469',1,NULL,NULL,NULL,'pressure steps 0 to -80 mmHg in -5 mmHg increments, 250 ms each, preceded by 5 s +5 mmHg prepulse (4 s at -80 mV + 1 s at +60 mV) | STIMULUS: -80 mmHg','P50',-21.5,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-21.5','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','Neuro2A-p1ko transient transfection with mouse Piezo1-pIRES-EGFP (4 µg, Lipofectamine 2000)','Neuro2A-p1ko',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM), pH 7.3 (KOH) — high K+ to zero membrane potential','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2 (mM), pH 7.3 (NaOH)',60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00071','for 0-20 channels, P50=-21.5 mmHg, k=-8.0 mmHg, n=5; for >200 channels, P50=-21.0 mmHg, k=-6.8 mmHg, n=3','Results (Figure 4G)','high','过表达 mPiezo1（Neuro2A-p1ko），step 协议归一化平均压力-响应曲线分箱；fit 值无 ±。','mPiezo1OE_Neuro2A-p1ko_cell-attached_step-0to-80mmHg_+60mV_P50_0-20ch_Fig4G','5','LITERATURE','2026-11-08',12,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(470,'MAIC:BX:00470',1,NULL,NULL,NULL,'pressure steps 0 to -80 mmHg in -5 mmHg increments, 250 ms each, preceded by 5 s +5 mmHg prepulse (4 s at -80 mV + 1 s at +60 mV) | STIMULUS: -80 mmHg','P50',-21.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-21.0','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','Neuro2A-p1ko transient transfection with mouse Piezo1-pIRES-EGFP (4 µg, Lipofectamine 2000)','Neuro2A-p1ko',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM), pH 7.3 (KOH) — high K+ to zero membrane potential','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2 (mM), pH 7.3 (NaOH)',60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00072','for 0-20 channels, P50=-21.5 mmHg, k=-8.0 mmHg, n=5; for >200 channels, P50=-21.0 mmHg, k=-6.8 mmHg, n=3','Results (Figure 4G)','high','最高密度分箱（~100 channels/µm²）；与低密度 bin 无差异——高密度下亦无正协同。','mPiezo1OE_Neuro2A-p1ko_cell-attached_step-0to-80mmHg_+60mV_P50_>200ch_Fig4G','3','LITERATURE','2026-11-08',12,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(471,'MAIC:BX:00471',1,NULL,NULL,NULL,'pressure steps 0 to -70 mmHg in -5 mmHg increments with patch radius imaging; tension via Laplace''s law T = R*p/2 | STIMULUS: -70 mmHg | ERROR-AS-REPORTED: 0.2 (sd)','T50',NULL,NULL,2.3,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.3','mN/m','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','Neuro2A-p1ko transient transfection with mouse Piezo1-pIRES-EGFP + simultaneous DIC imaging','Neuro2A-p1ko',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM), pH 7.3 (KOH) — high K+ to zero membrane potential','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2 (mM), pH 7.3 (NaOH)',60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00073','0-10 channels: T50=2.3±0.2 mN/m, k=0.8±0.1 mN/m','Figure 5F (caption)','high','DIC 成像逐 patch 半径 + Laplace 定律换算张力的 T50；SD；每 bin n=2-9 patches（D/E 总 n=25）。bin 按 channel density（channels/µm²）划分。','mPiezo1OE_Neuro2A-p1ko_cell-attached_DIC_step-0to-70mmHg_T50_0-10ch-per-um2_Fig5F',NULL,'LITERATURE','2026-11-08',12,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(472,'MAIC:BX:00472',1,NULL,NULL,NULL,'pressure steps 0 to -70 mmHg in -5 mmHg increments with patch radius imaging; tension via Laplace''s law T = R*p/2 | STIMULUS: -70 mmHg | ERROR-AS-REPORTED: 0.4 (sd)','T50',NULL,NULL,2.3,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.3','mN/m','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','Neuro2A-p1ko transient transfection with mouse Piezo1-pIRES-EGFP + simultaneous DIC imaging','Neuro2A-p1ko',NULL,7.3,'140 KCl, 10 HEPES, 1 MgCl2, 10 glucose (mM), pH 7.3 (KOH) — high K+ to zero membrane potential','130 NaCl, 5 KCl, 10 HEPES, 10 TEACl, 1 CaCl2, 1 MgCl2 (mM), pH 7.3 (NaOH)',60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00074','>50 channels: T50=2.3±0.4 mN/m, k=1.1±0.4 mN/m','Figure 5F (caption)','high','最高密度 bin；与最低密度 bin 相同（2.3 mN/m）——密度不影响张力敏感性。SD。','mPiezo1OE_Neuro2A-p1ko_cell-attached_DIC_step-0to-70mmHg_T50_>50ch-per-um2_Fig5F',NULL,'LITERATURE','2026-11-08',12,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(473,'MAIC:BX:00473',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses (2-3 µm tip pipettes); Boltzmann I/Imax vs pressure; τ from -70 mmHg pulses; settings as Syeda et al. 2015; Yoda1 applied via patch pipette | STIMULUS: -70 mmHg | ERROR-AS-REPORTED: 3 (sem)','P50',-51.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-51','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with mPZ1 (WT) plasmid (PEI)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00075','the mean P50 values were -51 ± 3 mmHg for WT in absence of Yoda1 (n = 8) and -25 ± 8 mmHg with 30 µM Yoda1 (n = 6)','Results (Fig 2c, d)','high','WT mPZ1（cell-attached，-80 mV，负压；设置同 Syeda 2015）；个体 I/Imax-P 曲线拟合后取均值；SEM。','mPZ1-WT_HEK293T_cell-attached_HSPC_Boltzmann-P50_-80mV_control_Fig2d','8','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(474,'MAIC:BX:00474',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses (2-3 µm tip pipettes); Boltzmann I/Imax vs pressure; τ from -70 mmHg pulses; settings as Syeda et al. 2015; Yoda1 applied via patch pipette | STIMULUS: -70 mmHg | MODULATOR: Yoda1 (agonist) 30 µM | ERROR-AS-REPORTED: 8 (sem)','P50',-25.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-25','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with mPZ1 (WT) plasmid (PEI)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00076','the mean P50 values were -51 ± 3 mmHg for WT in absence of Yoda1 (n = 8) and -25 ± 8 mmHg with 30 µM Yoda1 (n = 6)','Results (Fig 2c, d)','high','30 µM Yoda1（pipette 内）使 P50 左移（机械阈值降低）；SEM。t-test p=0.003。','mPZ1-WT_HEK293T_cell-attached_HSPC_Boltzmann-P50_-80mV_Yoda1-30uM_Fig2d','6','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(475,'MAIC:BX:00475',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses; Boltzmann P50 and τ at -70 mmHg; ± 30 µM Yoda1 in pipette | STIMULUS: -70 mmHg | ERROR-AS-REPORTED: 1 (sem)','P50',-59.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-59','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with Ch1961-2063 chimera (mPZ1 residues 1961-2063 replaced by mPZ2 homolog)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00077','For Chim, the mean P50 values were -59 ± 1 mmHg without Yoda1 (n = 6) and -63 ± 6 mmHg with 30 µM Yoda1 (n = 7)','Results (Fig 2c, d)','high','Chim = Ch1961-2063（mPZ1 残基 1961-2063 替换为 mPZ2 同源段的 Piezo1 嵌合体，非点突变，variant 列留空）；嵌合本身带来小幅左移（-59 vs -51）。SEM。','mPZ1-Ch1961-2063_HEK293T_cell-attached_HSPC_Boltzmann-P50_-80mV_control_Fig2d','6','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(476,'MAIC:BX:00476',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses; Boltzmann P50 and τ at -70 mmHg; ± 30 µM Yoda1 in pipette | STIMULUS: -70 mmHg | MODULATOR: Yoda1 (agonist) 30 µM | ERROR-AS-REPORTED: 6 (sem)','P50',-63.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-63','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with Ch1961-2063 chimera (mPZ1 residues 1961-2063 replaced by mPZ2 homolog)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00078','For Chim, the mean P50 values were -59 ± 1 mmHg without Yoda1 (n = 6) and -63 ± 6 mmHg with 30 µM Yoda1 (n = 7)','Results (Fig 2c, d)','high','Yoda1 对 Chim 无显著效应（t-test p=0.48）——证实嵌合体 Yoda1 不敏感。SEM。','mPZ1-Ch1961-2063_HEK293T_cell-attached_HSPC_Boltzmann-P50_-80mV_Yoda1-30uM_Fig2d','7','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(477,'MAIC:BX:00477',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses (2-3 µm tip pipettes); Boltzmann I/Imax vs pressure; τ from -70 mmHg pulses; settings as Syeda et al. 2015; Yoda1 applied via patch pipette | STIMULUS: -70 mmHg | ERROR-AS-REPORTED: 11 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,48.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'48','ms','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with mPZ1 (WT) plasmid (PEI)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00079','the rate of inactivation of WT mPZ1 channels in absence of Yoda1 (48 ± 11 ms, n = 4) increases significantly upon Yoda1 exposure (107 ± 20 ms, n = 4)','Results (Fig 2e, f)','high','-70 mmHg 压力脉冲诱发电流的单指数衰减 τ（-80 mV）；SEM。论文叙述 ''rate of inactivation ... increases'' 指时间常数增大（减慢）。','mPZ1-WT_HEK293T_cell-attached_-70mmHg_-80mV_tau-inact_control_Fig2f','4','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(478,'MAIC:BX:00478',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses (2-3 µm tip pipettes); Boltzmann I/Imax vs pressure; τ from -70 mmHg pulses; settings as Syeda et al. 2015; Yoda1 applied via patch pipette | STIMULUS: -70 mmHg | MODULATOR: Yoda1 (agonist) 30 µM | ERROR-AS-REPORTED: 20 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,107.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'107','ms','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with mPZ1 (WT) plasmid (PEI)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00080','the rate of inactivation of WT mPZ1 channels in absence of Yoda1 (48 ± 11 ms, n = 4) increases significantly upon Yoda1 exposure (107 ± 20 ms, n = 4)','Results (Fig 2e, f)','high','Yoda1 显著减慢 WT 失活（48→107 ms）。SEM。','mPZ1-WT_HEK293T_cell-attached_-70mmHg_-80mV_tau-inact_Yoda1_Fig2f','4','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(479,'MAIC:BX:00479',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses; Boltzmann P50 and τ at -70 mmHg; ± 30 µM Yoda1 in pipette | STIMULUS: -70 mmHg | ERROR-AS-REPORTED: 8 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,46.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'46','ms','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with Ch1961-2063 chimera (mPZ1 residues 1961-2063 replaced by mPZ2 homolog)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00081','the inactivation time course for Chim (46 ± 8 ms, n = 4) did not significantly change in the presence of Yoda1 (30 ± 16 ms, n = 4)','Results (Fig 2e, f)','high','Chim 失活 τ 与 WT 相近。SEM。','mPZ1-Ch1961-2063_HEK293T_cell-attached_-70mmHg_-80mV_tau-inact_control_Fig2f','4','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(480,'MAIC:BX:00480',1,NULL,NULL,NULL,'HSPC-1; brief negative pressure pulses; Boltzmann P50 and τ at -70 mmHg; ± 30 µM Yoda1 in pipette | STIMULUS: -70 mmHg | MODULATOR: Yoda1 (agonist) 30 µM | ERROR-AS-REPORTED: 16 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'30','ms','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T transient transfection with Ch1961-2063 chimera (mPZ1 residues 1961-2063 replaced by mPZ2 homolog)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00082','the inactivation time course for Chim (46 ± 8 ms, n = 4) did not significantly change in the presence of Yoda1 (30 ± 16 ms, n = 4)','Results (Fig 2e, f)','high','Yoda1 不显著改变 Chim 失活（46→30 ms, n.s.）——与 WT 的 107 ms 对照。SEM。','mPZ1-Ch1961-2063_HEK293T_cell-attached_-70mmHg_-80mV_tau-inact_Yoda1_Fig2f','4','LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(481,'MAIC:BX:00481',1,NULL,NULL,NULL,'HSPC-1; negative pressure pulses; P50 across Yoda1 concentrations (2-100 µM) for ΔP50 binding fit; single-channel recordings at low pressures | MODULATOR: Yoda1 (agonist) 30 µM','P50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,30.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'30','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HEK 293T co-transfection with equimolar WT and Ch1961-2063 plasmids (predicted 75% hybrid / 12.5% WT / 12.5% Chim trimers)','HEK 293T',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (mM), pH 7.3 (KOH) — depolarizing bath to zero membrane potential','130 NaCl, 5 KCl, 1 CaCl2, 1 MgCl2, 10 TEA-Cl, 10 HEPES (mM), pH 7.3 (NaOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00083','application of 30 µM Yoda1 shifts P50 values by +20 to +30 mmHg in hybrid channels (t-test p-values ranging from 0.002 to 0.007) and WT channels (t-test p-values ranging from 0.0009 to 0.005) but not in Chim channels','Results (Fig 6b)','medium','论文印出的位移范围 +20 至 +30 mmHg（向低压/左移）；value 取上端 30、relation "~"（对抗审 M1/n1 修正：error_low/high 清空——as-printed 区间端点已在 quote 内，"~" + quote 完整承载，避免 range 语义与单端点 value 的退化组合）；Chim 无位移（p 0.3-0.9）。hybrid = WT:Chim=1:1 混合转染（≥1 个 WT 亚基即足够）。','mPZ1-WT-and-hybrid_HEK293T_cell-attached_delta-P50_Yoda1-30uM_Fig6b',NULL,'LITERATURE','2026-11-08',13,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(482,'MAIC:BX:00482',1,NULL,NULL,NULL,'blunt glass probe (3-4 um), 1-um incremental steps, 200-ms pulses, 2-ms ramp, 10-s intervals; threshold = first step evoking current deflection','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,33.8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'33.8','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (mouse Piezo1)','N2A (mouse neuro-2a)',NULL,NULL,'140 mM NaCl, 6 mM KCl, 2 mM CaCl2, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.4)','140 mM CsCl, 5 mM EGTA, 1 mM CaCl2, 1 mM MgCl2, 10 mM HEPES (pH 7.2)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00086','Piezo1 consistently displays robust and fast inactivating currents (τ ≈ 33.8 ms, at -60 mV) under mechanical displacement (Fig. 1a, control, and elsewhere32)','Results (Fig 1a)','high','Single-exponential fit of macroscopic inactivation (Eq. 1). Approximate value as printed (≈). n shown on figure axes only, not stated in text.','N2A endogenous mPiezo1, whole-cell indentation, -60 mV, control (no supplement)',NULL,'LITERATURE','2026-11-08',14,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(483,'MAIC:BX:00483',1,NULL,NULL,NULL,'blunt glass probe (3-4 um), 1-um incremental steps, 200-ms pulses, 2-ms ramp, 10-s intervals | MODULATOR: arachidonic acid (AA, C20:4) 100 µM','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'20','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (mouse Piezo1) + 18-h fatty-acid supplementation of culture medium','N2A (mouse neuro-2a)',NULL,NULL,'140 mM NaCl, 6 mM KCl, 2 mM CaCl2, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.4)','140 mM CsCl, 5 mM EGTA, 1 mM CaCl2, 1 mM MgCl2, 10 mM HEPES (pH 7.2)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00087','We found that C20 PUFAs decreased Piezo1 time constants of inactivation to ≈20 ms (100 µM of AA and EPA, Fig. 2a, b) compared to control cells (≈34 ms).','Results (Fig 2a, b)','high','Membrane-remodelling manipulation via 18-h medium supplementation, not acute perfusion. Value for AA; same sentence reports EPA 100 uM also ≈20 ms (separate row). Control restated as ≈34 ms here vs 33.8 ms in Fig 1a.','N2A endogenous mPiezo1, whole-cell indentation, -60 mV, arachidonic acid 100 uM 18-h supplementation',NULL,'LITERATURE','2026-11-08',14,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(484,'MAIC:BX:00484',1,NULL,NULL,NULL,'blunt glass probe (3-4 um), 1-um incremental steps, 200-ms pulses, 2-ms ramp, 10-s intervals | MODULATOR: eicosapentaenoic acid (EPA, C20:5) 100 µM','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'20','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (mouse Piezo1) + 18-h fatty-acid supplementation of culture medium','N2A (mouse neuro-2a)',NULL,NULL,'140 mM NaCl, 6 mM KCl, 2 mM CaCl2, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.4)','140 mM CsCl, 5 mM EGTA, 1 mM CaCl2, 1 mM MgCl2, 10 mM HEPES (pH 7.2)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00088','We found that C20 PUFAs decreased Piezo1 time constants of inactivation to ≈20 ms (100 µM of AA and EPA, Fig. 2a, b) compared to control cells (≈34 ms).','Results (Fig 2a, b)','high','Same span as AA row; EPA-specific value from the joint statement. Membrane-remodelling via 18-h supplementation.','N2A endogenous mPiezo1, whole-cell indentation, -60 mV, EPA 100 uM 18-h supplementation',NULL,'LITERATURE','2026-11-08',14,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(485,'MAIC:BX:00485',1,NULL,NULL,NULL,'blunt glass probe (3-4 um), 1-um incremental steps, 200-ms pulses, 2-ms ramp, 10-s intervals | MODULATOR: eicosapentaenoic acid (EPA, C20:5)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (mouse Piezo1) + 18-h fatty-acid supplementation of culture medium','N2A (mouse neuro-2a)',NULL,NULL,'140 mM NaCl, 6 mM KCl, 2 mM CaCl2, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.4)','140 mM CsCl, 5 mM EGTA, 1 mM CaCl2, 1 mM MgCl2, 10 mM HEPES (pH 7.2)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00089','we observed a further decrease in the time constants of inactivation (≈13 ms) when supplementing N2A cells with higher EPA concentrations (200 and 300 µM, Supplementary Figure 2a, b)','Results (Supplementary Fig 2a, b)','medium','Concentration given as a 200 and 300 uM pair in one span, so modulator_concentration left blank; note records both.','N2A endogenous mPiezo1, whole-cell indentation, -60 mV, EPA 200-300 uM 18-h supplementation',NULL,'LITERATURE','2026-11-08',14,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(486,'MAIC:BX:00486',1,NULL,NULL,NULL,'blunt glass probe (3-4 um), 1-um incremental steps, 200-ms pulses, 2-ms ramp, 10-s intervals | MODULATOR: eicosapentaenoic acid (EPA, C20:5) 10 µM','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (mouse Piezo1) + 18-h fatty-acid supplementation of culture medium','N2A (mouse neuro-2a)',NULL,NULL,'140 mM NaCl, 6 mM KCl, 2 mM CaCl2, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.4)','140 mM CsCl, 5 mM EGTA, 1 mM CaCl2, 1 mM MgCl2, 10 mM HEPES (pH 7.2)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00090','supplementing N2A cells with low concentrations (10 µM) of EPA, each day for 5 days, increases the EPA content in the plasma membrane and significantly speed up Piezo1 inactivation (≈13 ms; Supplementary Figure 2a-c)','Results (Supplementary Fig 2a-c)','high','Long-term low-dose supplementation protocol.','N2A endogenous mPiezo1, whole-cell indentation, -60 mV, EPA 10 uM daily for 5 days',NULL,'LITERATURE','2026-11-08',14,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(487,'MAIC:BX:00487',1,NULL,NULL,NULL,'blunt glass probe (3-4 um), 1-um incremental steps, 200-ms pulses, 2-ms ramp, 10-s intervals | MODULATOR: docosahexaenoic acid (DHA, C22:6) 100 µM','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,53.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'53','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (mouse Piezo1) + 18-h fatty-acid supplementation of culture medium','N2A (mouse neuro-2a)',NULL,NULL,'140 mM NaCl, 6 mM KCl, 2 mM CaCl2, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.4)','140 mM CsCl, 5 mM EGTA, 1 mM CaCl2, 1 mM MgCl2, 10 mM HEPES (pH 7.2)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00091','On the other hand, C22 DHA elicited a robust increase in the time constants of inactivation up to ≈53 ms (100 µM, Fig. 2a, b).','Results (Fig 2a, b)','high','DHA slows inactivation (opposite direction to C20 PUFAs).','N2A endogenous mPiezo1, whole-cell indentation, -60 mV, DHA 100 uM 18-h supplementation',NULL,'LITERATURE','2026-11-08',14,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(488,'MAIC:BX:00488',1,NULL,NULL,NULL,'1-um-step indentation pulses; I-V from voltage steps 5 s before stimulation (+/-60 mV)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'7.5','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','endogenous (human PIEZO1)','HMVEC (human microvascular endothelial, neonatal dermal)',NULL,NULL,'140 mM NaCl, 6 mM KCl, 2 mM CaCl2, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.4)','140 mM CsCl, 5 mM EGTA, 1 mM CaCl2, 1 mM MgCl2, 10 mM HEPES (pH 7.2)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00092','voltage-dependent inactivation42, non-selective cation currents32 (reversal potential at +7.5 mV, Fig. 4c), complete blockage by GdCl332','Results (Fig 4c)','high','n=5 from Fig 4c legend (Circles are mean ± SD. n = 5). Supports non-selective cation selectivity of HMVEC PIEZO1.','HMVEC endogenous PIEZO1, whole-cell indentation, I-V ramp/steps, Fig 4c','5','LITERATURE','2026-11-08',14,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(489,'MAIC:BX:00489',1,NULL,NULL,NULL,'HSPC-1 computer-controlled high-speed pressure clamp, 350-ms square negative-pressure pulses, -20 to -70 mmHg, 500-ms pulses applied every 15 s (per Fig 2 legend of companion measurements); pipette voltage +65 mV | ERROR-AS-REPORTED: 3 (sem)','P50',36.4,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'36.4','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','stable PIEZO1-1591-GFP (human, hP1-1591-GFP clone)','HEK293T',NULL,7.4,'140 mM NaCl, 3 mM KCl, 1 mM MgCl2, 1 mM CaCl2, 10 mM glucose, 10 mM HEPES, pH 7.4 (identical bath/pipette)','140 mM NaCl, 3 mM KCl, 1 mM MgCl2, 1 mM CaCl2, 10 mM glucose, 10 mM HEPES, pH 7.4',65.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00094','Summary of average P50 values and slopes derived from Boltzmann fits of I/Imax versus pressure plots of all PIEZO1 variants and treatments performed in this study; P50 (-mmHg); hPIEZO1-GFP; 36.4 ± 3; All values are reported as mean ± SEM.','Table 2','high','Table column header is ''P50 (−mmHg)'' i.e. suction magnitude printed unsigned; value stored as printed (36.4 = -36.4 mmHg suction). n per condition in figure legends (Fig 1F n = 7-10), not stated per Table 2 row.','hPIEZO1-GFP stable HEK293T, cell-attached, +65 mV pipette, control (serum-free 30 min)',NULL,'LITERATURE','2026-11-08',15,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(490,'MAIC:BX:00490',1,NULL,NULL,NULL,'HSPC-1 computer-controlled high-speed pressure clamp, 350-ms square negative-pressure pulses, -20 to -70 mmHg, 500-ms pulses applied every 15 s (per Fig 2 legend of companion measurements); pipette voltage +65 mV | MODULATOR: MBCD (methyl-beta-cyclodextrin) (antagonist) 0.1 mM | ERROR-AS-REPORTED: 7 (sem)','P50',30.7,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'30.7','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','stable PIEZO1-1591-GFP (human, hP1-1591-GFP clone)','HEK293T',NULL,7.4,'140 mM NaCl, 3 mM KCl, 1 mM MgCl2, 1 mM CaCl2, 10 mM glucose, 10 mM HEPES, pH 7.4 (identical bath/pipette)','140 mM NaCl, 3 mM KCl, 1 mM MgCl2, 1 mM CaCl2, 10 mM glucose, 10 mM HEPES, pH 7.4',65.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00095','Summary of average P50 values and slopes derived from Boltzmann fits of I/Imax versus pressure plots of all PIEZO1 variants and treatments performed in this study; P50 (-mmHg); + 0.1 mM MBCD; 30.7 ± 7; All values are reported as mean ± SEM.','Table 2','high','Cholesterol depletion lowers membrane cholesterol; direction of P50 effect at this dose is inward (30.7 vs 36.4 control, not significant per Fig S1). Value unsigned as printed under ''P50 (−mmHg)''.','hPIEZO1-GFP stable HEK293T, cell-attached, +65 mV pipette, 0.1 mM MBCD 30 min',NULL,'LITERATURE','2026-11-08',15,'2026-11-08 00:00:00.000000',NULL);
