INSERT INTO "biophysics_experiment" VALUES(503,'MAIC:BX:00503',1,NULL,NULL,NULL,'HSPC-1 computer-controlled high-speed pressure clamp, 350-ms square negative-pressure pulses, -20 to -70 mmHg, 500-ms pulses applied every 15 s (per Fig 2 legend of companion measurements); pipette voltage +65 mV | MODULATOR: MBCD (methyl-beta-cyclodextrin) (antagonist) 5 mM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,40.0,'%',NULL,NULL,NULL,NULL,'40','%','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','stable PIEZO1-1591-GFP (human, hP1-1591-GFP clone)','HEK293T',NULL,7.4,'140 mM NaCl, 3 mM KCl, 1 mM MgCl2, 1 mM CaCl2, 10 mM glucose, 10 mM HEPES, pH 7.4 (identical bath/pipette)','140 mM NaCl, 3 mM KCl, 1 mM MgCl2, 1 mM CaCl2, 10 mM glucose, 10 mM HEPES, pH 7.4',65.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00108','only MBCD caused a rightward shift in the midpoint activation pressure of the channel by ∼40%','Results (Fig 1, E and F)','medium','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). Printed as a percent shift (~40% = 1.4-fold), not a mmHg delta — schema_gap via threshold_fold_shift. mmHg delta not computed from Table 2 rows per no-self-arithmetic rule.','hPIEZO1-GFP stable HEK293T, cell-attached, 5 mM MBCD vs control',NULL,'LITERATURE','2026-11-08',15,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(504,'MAIC:BX:00504',1,NULL,NULL,NULL,'steady-state negative pipette pressure 0 to -90 mmHg, 60-s continuous gap-free single-channel traces; high-resistance pipettes 5-6 MOhm (~0.8 um tip) | ERROR-AS-REPORTED: 3.9 (sem)','P50',-51.6,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-51.6','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient mPIEZO1 (pCDNA3.1-mPIEZO1-IRES-mCherry)','HEK293T-delta-PZ1 (PIEZO1 knockout)',NULL,7.4,'HBSS with calcium, magnesium and sodium bicarbonate (Gibco #14025)','140 mM KCl, 10 mM HEPES, 10 mM TEA, 2 mM EGTA (pH 7.4 with NaOH)',-90.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00109','Scatter plots of Npo values against pressures were well fitted by a two-state Boltzmann function, with half-maximal pressure values (P50) ranging from -51.6 ± 3.9 to -54.4 ± 5.7 mmHg, giving an error-propagated average of -52.9 ± 2.8 mmHg (Fig. 1, B-D)','Results (Fig 1, B-D)','high','Range endpoints come from three independent NPo estimation methods (Fig 1B-D); error bars = SEM per Fig 1 legend. Sign as printed (suction).','mPIEZO1 HEK293T-deltaPZ1, cell-attached, -90 mV, steady-state 0 to -90 mmHg, Boltzmann fit of NPo (all-point histogram / durations / mean durations)',NULL,'LITERATURE','2026-11-08',16,'2026-11-08 00:00:00.000000',NULL);
