INSERT INTO "biophysics_experiment" VALUES(507,'MAIC:BX:00507',1,NULL,NULL,NULL,'steady-state negative pipette pressure 0 to -90 mmHg, 60-s continuous gap-free single-channel traces; high-resistance pipettes 5-6 MOhm (~0.8 um tip) | ERROR-AS-REPORTED: 6.1 (sem)','P50',-62.6,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-62.6','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient mPIEZO1 (pCDNA3.1-mPIEZO1-IRES-mCherry)','HEK293T-delta-PZ1 (PIEZO1 knockout)',NULL,7.4,'HBSS with calcium, magnesium and sodium bicarbonate (Gibco #14025)','140 mM KCl, 10 mM HEPES, 10 mM TEA, 2 mM EGTA (pH 7.4 with NaOH)',-90.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00112','the pressure-dependent open probability plot derived from the amplitude-weighted time constants of exponential components yields a P50 value of -62.6 ± 6.1 mmHg (Fig. 3 G), slightly more negative than the P50 calculated using fit-independent methods (Fig. 1, B-D)','Results (Fig 3G)','medium','Model-dependent (dwell-time exponential components) but from measured data; slightly more negative than fit-independent P50. Sign as printed.','mPIEZO1 HEK293T-deltaPZ1, cell-attached, -90 mV, open probability from amplitude-weighted OC1/OC2/SC1-SC3 time constants, Boltzmann fit',NULL,'LITERATURE','2026-11-08',16,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(508,'MAIC:BX:00508',1,NULL,NULL,NULL,'steady-state negative pipette pressure 0 to -90 mmHg, 60-s continuous gap-free single-channel traces; high-resistance pipettes 5-6 MOhm (~0.8 um tip) | ERROR-AS-REPORTED: 4.09 (sd)','P50',-62.98,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-62.98','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient mPIEZO1 (pCDNA3.1-mPIEZO1-IRES-mCherry)','HEK293T-delta-PZ1 (PIEZO1 knockout)',NULL,7.4,'HBSS with calcium, magnesium and sodium bicarbonate (Gibco #14025)','140 mM KCl, 10 mM HEPES, 10 mM TEA, 2 mM EGTA (pH 7.4 with NaOH)',-90.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00113','yielding a P50 nearly identical to the P50 calculated from the amplitude-weighted time constants of exponential components of dwell time distributions (-62.98 ± 4.09 vs. -62.6 ± 6.1 mmHg; Fig. 3 G and Fig. 7 H)','Results (Fig 7H)','low','Simulated (model-derived) value; Fig 7 legend states rates shown as mean ± SD. Kept with confidence=low per model-inference rule. Sign as printed.','mPIEZO1 HEK293T-deltaPZ1, cell-attached, -90 mV, M21 Markov model simulated data, Po from O1+O2 occupancy',NULL,'LITERATURE','2026-11-08',16,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(509,'MAIC:BX:00509',1,NULL,NULL,NULL,'steady-state negative pipette pressure 0 to -90 mmHg, 60-s continuous gap-free single-channel traces; high-resistance pipettes 5-6 MOhm (~0.8 um tip) | ERROR-AS-REPORTED: 0.3','T50',NULL,NULL,3.4,'mN/m',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'3.4','mN m−1','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient mPIEZO1 (pCDNA3.1-mPIEZO1-IRES-mCherry)','HEK293T-delta-PZ1 (PIEZO1 knockout)',NULL,7.4,'HBSS with calcium, magnesium and sodium bicarbonate (Gibco #14025)','140 mM KCl, 10 mM HEPES, 10 mM TEA, 2 mM EGTA (pH 7.4 with NaOH)',-90.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00114','Assuming tension linearly scales with pressure for identical cells and pipette geometry (Sukharev et al., 1999), the average PIEZO1 single channel P50 value would yield a T50 value of 3.4 ± 0.3 mN m-1','Results (Fig 2, A and B)','low','Indirect estimate: assumes linear tension-pressure scaling calibrated with MscL (own P50 −172 ± 6 mmHg with the same pipettes; literature MscL T50 ~10.4-11.8 mN m−1). Error type not stated (treated as propagated). unit as printed ''mN m−1'', unit_db normalized to ''mN/m''.','mPIEZO1 HEK293T-deltaPZ1, cell-attached, -90 mV, T50 inferred from average single-channel P50 via MscL tension calibration',NULL,'LITERATURE','2026-11-08',16,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(510,'MAIC:BX:00510',1,NULL,NULL,NULL,'HSPC-1 500-ms negative pressure pulses, 0 to -80 mmHg in -10 mmHg steps, every 15 s; 30 uM Yoda1 in pipette where indicated | MODULATOR: Yoda1 (potentiator) 30 μM','P50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'15','mm Hg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient mPiezo1-IRES-GFP','HEK293T',NULL,7.3,'140 mM KCl, 1 mM MgCl2, 10 mM glucose, 10 mM HEPES (pH 7.3, zeroes membrane potential)','130 mM NaCl, 5 mM KCl, 1 mM CaCl2, 1 mM MgCl2, 10 mM TEA-Cl, 10 mM HEPES (pH 7.3); + 30 uM Yoda1 where specified',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00117','Yoda1 sensitized mPiezo1 to activation by pressure as indicated by a leftward shift in the current-pressure relationship, reducing the half maximal activation pressure (P50) by about 15 mm Hg (Figure 2B,C)','Results and discussion (Fig 2, B and C)','high','Direction: reduction (leftward). Value printed as magnitude ''about 15 mm Hg''; unit as printed ''mm Hg'', unit_db ''mmHg''. Absolute pre/post P50 values are in Fig 2C only. Yoda1-exposed n = 8, control n = 12 per Fig 2 legend.','mPiezo1 HEK293T, cell-attached, -80 mV, 30 uM Yoda1 in pipette vs control (n = 8 and 12)',NULL,'LITERATURE','2026-11-08',17,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(511,'MAIC:BX:00511',1,NULL,NULL,NULL,'piezoelectric-driven blunt glass probe, 0.5-um displacement increments every 10 s; Yoda1 10 uM bath/puffer application 1-2 min before test | ERROR-AS-REPORTED: 1.5','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,16.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'16.5','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient mPiezo1-IRES-GFP','HEK293T',NULL,NULL,'not stated for whole-cellpoke experiments','not stated',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00118','The fold change in the inactivation time constant indicates a significant slowing of inactivation during Yoda1 exposure. The effect was completely reversible (not shown). The baseline tau prior to Yoda1 exposure was 16.5 ± 1.5 ms (n = 5) (H).','Fig 2G legend','medium','Error type (SEM vs SD) not stated for this value. Yoda1 slows inactivation but the post-Yoda1 value is reported only as fold change (no absolute ms printed).','mPiezo1 HEK293T, whole-cell indentation, -80 mV, baseline (vehicle) before 10 uM Yoda1','5','LITERATURE','2026-11-08',17,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(512,'MAIC:BX:00512',1,NULL,NULL,NULL,'no externally applied pressure (Yoda1-mediated activation); 0.5 M KCl to boost signal-to-noise; Yoda1 1-30 uM in liposomes | MODULATOR: Yoda1 (agonist) 1 μM | ERROR-AS-REPORTED: 9 (sd)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,98.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'98','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'RECONSTITUTED_PROTEOLIPOSOME','purified mPiezo1 reconstituted in symmetric DPhPC droplet interface bilayers','cell-free droplet interface bilayer (DIB)',NULL,7.4,'0.5 M KCl, 20 mM HEPES, pH 7.4','0.5 M KCl, 20 mM HEPES, pH 7.4',100.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00119','Single-channel electrical recordings of reconstituted mPiezo1 in the symmetric DPhPC bilayers in the presence of 1 μM Yoda1. The calculated single-channel conductance of outward currents from the corresponding all point current histograms is 98 ± 9 pS in 0.5 M KCl, 20 mM HEPES, pH 7.4 at V = 100 mV.','Fig 3B legend','high','Unitary conductance from Gaussian fits of all-point histograms — qualifies under the conductance=unitary-pS-only rule (reconstituted bilayer). Mean ± SD per Methods (''The calculated values are reported as mean ± standard deviation'') and Fig 3D legend. conductance flag was N at triage but this is an own-data unitary value, so it is rowed.','purified mPiezo1 in symmetric DPhPC droplet interface bilayers, 1 uM Yoda1, 0.5 M KCl, V = +100 mV, outward currents',NULL,'LITERATURE','2026-11-08',17,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(513,'MAIC:BX:00513',1,NULL,NULL,NULL,'High Speed Pressure Clamp (HSPC): positive pressure steps 10-150 mmHg, 20 mmHg increments, 600-ms pulses at 0.1 Hz; Boltzmann fit of pressure-response | ERROR-AS-REPORTED: 6.0 (sem)','P50',87.1,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'87.1','mmHg','POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','endogenous (mouse Piezo1; stretch-activated current shown PIEZO1-dependent, TRPV4-independent)','primary murine chondrocytes (C57Bl/6 or Trpv4-/- pups, 4-5 days)',NULL,NULL,'150 mM NaCl, 5 mM KCl, 10 mM HEPES, 10 mM glucose, 1 mM MgCl2, 2 mM CaCl2','140 mM KCl, 10 mM HEPES, 1 mM EGTA, 1 mM MgCl2',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00120','We found that patches pulled from WT chondrocytes exhibited robust currents to applied pressure, with a P50 of 87.1 ± 6.0 mmHg (mean ± s.e.m., n = 12)','Results (Fig 6A; Fig 6—figure supplement 1)','high','Positive pressure (outside-out stretch); value as printed (unsigned). Stretch-activated current attributed to PIEZO1: Trpv4-/- P50 indistinguishable and Piezo1-miRNA abolishes the current.','primary murine chondrocyte WT, outside-out, HSPC positive pressure 10-150 mmHg, -60 mV, Boltzmann fit','12','LITERATURE','2026-11-08',18,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(514,'MAIC:BX:00514',1,NULL,NULL,NULL,'High Speed Pressure Clamp (HSPC): positive pressure steps 10-150 mmHg, 20 mmHg increments, 600-ms pulses at 0.1 Hz; Boltzmann fit of pressure-response | ERROR-AS-REPORTED: 9.3 (sem)','P50',88.2,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'88.2','mmHg','POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','endogenous (mouse Piezo1; stretch-activated current shown PIEZO1-dependent, TRPV4-independent)','primary murine chondrocytes (C57Bl/6 or Trpv4-/- pups, 4-5 days)',NULL,NULL,'150 mM NaCl, 5 mM KCl, 10 mM HEPES, 10 mM glucose, 1 mM MgCl2, 2 mM CaCl2','140 mM KCl, 10 mM HEPES, 1 mM EGTA, 1 mM MgCl2',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00121','However, we observed comparable stretch-activated currents in patches isolated from Trpv4-/- cells with a mean P50 for activation (88.2 ± 9.3 mmHg (mean ± s.e.m., n = 7)) (Figure 6—figure supplement 1)','Results (Fig 6—figure supplement 1)','high','TRPV4 absence does not change the stretch P50 — direct evidence the stretch-activated current is PIEZO1-mediated (core claim of the paper).','primary murine chondrocyte Trpv4-/-, outside-out, HSPC positive pressure 10-150 mmHg, -60 mV, Boltzmann fit','7','LITERATURE','2026-11-08',18,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(515,'MAIC:BX:00515',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,47.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'47','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00122','The current-voltage relationship for K+ in cell-attached patches was fairly linear and reversed near 0 mV as expected. The slope conductance was 47 pS (Fig 1A).','Results (Fig 1A)','high','n = 6 from Fig 1A legend. Unitary slope conductance (cell-attached). SAME-SOURCE DISCLOSURE (对抗审 M5): the paper also reports the chord conductance at -80 mV as "~47 pS" (Fig 1B, same n=6 patches) — for the near-linear I/V (reversal near 0 mV) slope and chord are mathematically the same quantity, so that value is NOT rowed separately (double-count guard); the chord value at -100 mV (~53 pS, different voltage point) IS rowed independently below.','hPIEZO1 HEK293, cell-attached, pipette 150 mM KCl, suction steps, I/V linear fit','6','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(516,'MAIC:BX:00516',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,53.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'53','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00123','Fitting the peaks with Gaussians, the chord conductance of K+ at -80 mV and -100 mV were ~47 pS and ~53 pS, respectively.','Results (Fig 1B)','high','n = 6 (Fig 1 legend); matches abstract range 35-55 pS.','hPIEZO1 HEK293, cell-attached, pipette 150 mM KCl, chord conductance at -100 mV','6','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(517,'MAIC:BX:00517',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,39.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'39','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00124','The other alkali ions Na+, Cs+ and Li+, had I/V data similar to that of K+ with slope conductances of 39 pS for Cs+, 36 pS for Na+ and 23 pS for Li+ (Fig 1C).','Results (Fig 1C)','high','n = 3 for Cs+ (Fig 1 legend).','hPIEZO1 HEK293, cell-attached, pipette 150 mM CsCl, I/V linear fit','3','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(518,'MAIC:BX:00518',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,36.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'36','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00125','The other alkali ions Na+, Cs+ and Li+, had I/V data similar to that of K+ with slope conductances of 39 pS for Cs+, 36 pS for Na+ and 23 pS for Li+ (Fig 1C).','Results (Fig 1C)','high','n = 6 for Na+ (Fig 1 legend).','hPIEZO1 HEK293, cell-attached, pipette 150 mM NaCl, I/V linear fit','6','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(519,'MAIC:BX:00519',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'23','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00126','The other alkali ions Na+, Cs+ and Li+, had I/V data similar to that of K+ with slope conductances of 39 pS for Cs+, 36 pS for Na+ and 23 pS for Li+ (Fig 1C).','Results (Fig 1C)','high','n = 5 for Li+ (Fig 1 legend); abstract calls it ''significantly lower conductance of ~ 23 pS''.','hPIEZO1 HEK293, cell-attached, pipette 150 mM LiCl, I/V linear fit','5','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(520,'MAIC:BX:00520',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,25.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'25','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00127','In cell-attached patches, the chord conductance of the unitary currents with extracellular Ba2+ at -80 mV was ~25 pS (Fig 3A).','Results (Fig 3A)','high','n = 10 (Fig 3A legend); cytochalasin D pre-exposure used to facilitate activation. Junction potential -7.8 mV not corrected (authors note correction would cause a minor increase).','hPIEZO1 HEK293, cell-attached, pipette 90 mM BaCl2, chord conductance at -80 mV','10','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(521,'MAIC:BX:00521',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'15','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00128','The chord conductances of Ca2+ and Mg2+ were ~15 pS at -80mV and ~10 pS at -50mV, respectively.','Results (Cytochalasin D section; Fig 3B)','high','n = 10 (Fig 3B legend); cytochalasin D 2 uM pre-exposure. Junction potential -8.3 mV uncorrected.','hPIEZO1 HEK293, cell-attached, pipette 90 mM CaCl2, chord conductance at -80 mV','10','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(522,'MAIC:BX:00522',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'10','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00129','The chord conductances of Ca2+ and Mg2+ were ~15 pS at -80mV and ~10 pS at -50mV, respectively.','Results (Fig 3B legend)','high','n = 4 (Fig 3B legend); different voltage (-50 mV) because of lower signal. Junction potential -9.1 mV uncorrected.','hPIEZO1 HEK293, cell-attached, pipette 90 mM MgCl2, chord conductance at -50 mV','4','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(523,'MAIC:BX:00523',1,NULL,NULL,NULL,'high-speed pressure clamp suction steps applied to the pipette; cytochalasin D 2 uM 15 min where noted; bath clamps resting potential to 0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,51.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'51','pS','SUCTION',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient hPIEZO1 cDNA (200 ng)','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM KCl / NaCl / CsCl / LiCl (monovalent series) or 90 mM MgCl2/CaCl2/BaCl2 or K+ + divalent/organic mixtures, 10 mM HEPES, pH 7.4',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00130','The relationship between [K+] and single-channel conductance was fit to the Michaelis-Menten equation yielding a maximal conductance of 51 pS and the KD of K+ for the channel of ~32 mM (Fig 2B).','Results (Fig 2B)','medium','Saturating maximal conductance from fit; KD of K+ (~32 mM) archived — it is a permeation (conductance saturation) parameter, not a pharmacological modulator affinity, so it is not routed to bioactivity kd.','hPIEZO1 HEK293, cell-attached, [K+] 10-300 mM series, 40 mV driving force, Michaelis-Menten fit (n = 3 patches per concentration)',NULL,'LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(524,'MAIC:BX:00524',1,NULL,NULL,NULL,'positive pressure via high-speed pressure clamp, 500-ms pulses',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.88,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0.88',NULL,'POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','transient hPIEZO1 cDNA','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM CsCl / NaCl / LiCl / TMA / TEA, 10 mM HEPES, pH 7.4',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00131','The resulting permeability ratios were 1:0.88:0.82:0.71 (PK:PCs:PNa:PLi).','Results (Fig 2A)','high','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). schema_gap (no ratio column; partial reversal-potential proxy only). Sequence PK > PCs = PNa > PLi.','hPIEZO1 HEK293, outside-out, Cs+ cytoplasmic vs K+ extracellular, GHK equation, junction-potential corrected',NULL,'LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(525,'MAIC:BX:00525',1,NULL,NULL,NULL,'positive pressure via high-speed pressure clamp, 500-ms pulses',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.82,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0.82',NULL,'POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','transient hPIEZO1 cDNA','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM CsCl / NaCl / LiCl / TMA / TEA, 10 mM HEPES, pH 7.4',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00132','The resulting permeability ratios were 1:0.88:0.82:0.71 (PK:PCs:PNa:PLi).','Results (Fig 2A)','high','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). schema_gap; see PCs/PK row.','hPIEZO1 HEK293, outside-out, Na+ cytoplasmic vs K+ extracellular, GHK equation',NULL,'LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(526,'MAIC:BX:00526',1,NULL,NULL,NULL,'positive pressure via high-speed pressure clamp, 500-ms pulses',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.71,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0.71',NULL,'POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','transient hPIEZO1 cDNA','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM CsCl / NaCl / LiCl / TMA / TEA, 10 mM HEPES, pH 7.4',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00133','The resulting permeability ratios were 1:0.88:0.82:0.71 (PK:PCs:PNa:PLi).','Results (Fig 2A)','high','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). schema_gap; Li+ discrimination implies pore lower limit near Li+ hydrated diameter (~6 A).','hPIEZO1 HEK293, outside-out, Li+ cytoplasmic vs K+ extracellular, GHK equation',NULL,'LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(527,'MAIC:BX:00527',1,NULL,NULL,NULL,'positive pressure via high-speed pressure clamp, 500-ms pulses','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,45.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'45','mV','POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','transient hPIEZO1 cDNA','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM CsCl / NaCl / LiCl / TMA / TEA, 10 mM HEPES, pH 7.4',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00134','For 150 mM TMA, the current would reverse near +45 mV, whereas with 150 mM TEA, the reversal potential would be near +8 mV (n = 3 patches) after compensating for the junction potential.','Fig 6 legend','medium','Text elsewhere says ''around +40 mV'' uncorrected; the legend value (+45 mV) is the junction-compensated one and is used. Organic-cation permeability marker, not a normal ionic Erev.','hPIEZO1 HEK293, outside-out, pipette 150 mM TMA vs K+ bath, junction-potential compensated (-5.0 mV)','3','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(528,'MAIC:BX:00528',1,NULL,NULL,NULL,'positive pressure via high-speed pressure clamp, 500-ms pulses','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'8','mV','POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,'OUTSIDE_OUT','transient hPIEZO1 cDNA','HEK293',NULL,7.4,'150 mM KCl, 10 mM HEPES, 1 mM MgCl2, 1 mM CaCl2, pH 7.4','150 mM CsCl / NaCl / LiCl / TMA / TEA, 10 mM HEPES, pH 7.4',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00135','For 150 mM TMA, the current would reverse near +45 mV, whereas with 150 mM TEA, the reversal potential would be near +8 mV (n = 3 patches) after compensating for the junction potential.','Fig 6 legend','medium','Text says ''near ~ 0 mV'' uncorrected; legend value (+8 mV) is junction-compensated and used.','hPIEZO1 HEK293, outside-out, pipette 150 mM TEA vs K+ bath, junction-potential compensated (-7.7 mV)','3','LITERATURE','2026-11-08',19,'2026-11-08 00:00:00.000000',NULL);
