INSERT INTO "biophysics_experiment" VALUES(547,'MAIC:BX:00547',1,NULL,NULL,85,'500 ms negative pressure pulses (HSPC-1); divalent-free Na+-based pipette (removes Ca2+ block, doubles conductance vs standard); single-channel amplitudes from 5-20 repeated traces, slope conductance from I-V linear regression | ERROR-AS-REPORTED: 1.2 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,64.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'64.2','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT or mutants',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (pH 7.3 with KOH) — zeroing membrane potential','150 mM NaCl, 10 HEPES (pH 7.3 with NaOH), divalent-free',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00154','In addition, we observed that in the absence of divalent ions, D2139A and D2144A mutations, which are downstream of E2133, result in slightly increased single-channel conductance compared with WT (64.2±1.2 and 69.6±1.8 pS, respectively; mean±s.e.m.).','Results (Supplementary Table 3)','high','Downstream acidic residue; slight conductance increase vs WT.','mPiezo1-D2139A_HEK293T_cell-attached_-80mV_NaDVF-pipette_slope-conductance_SuppTable3',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(548,'MAIC:BX:00548',1,NULL,NULL,86,'500 ms negative pressure pulses (HSPC-1); divalent-free Na+-based pipette (removes Ca2+ block, doubles conductance vs standard); single-channel amplitudes from 5-20 repeated traces, slope conductance from I-V linear regression | ERROR-AS-REPORTED: 1.8 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,69.6,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'69.6','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT or mutants',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (pH 7.3 with KOH) — zeroing membrane potential','150 mM NaCl, 10 HEPES (pH 7.3 with NaOH), divalent-free',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00155','In addition, we observed that in the absence of divalent ions, D2139A and D2144A mutations, which are downstream of E2133, result in slightly increased single-channel conductance compared with WT (64.2±1.2 and 69.6±1.8 pS, respectively; mean±s.e.m.).','Results (Supplementary Table 3)','high','Downstream acidic residue; slight conductance increase vs WT.','mPiezo1-D2144A_HEK293T_cell-attached_-80mV_NaDVF-pipette_slope-conductance_SuppTable3',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(549,'MAIC:BX:00549',1,NULL,NULL,87,'500 ms negative pressure pulses (HSPC-1); divalent-free Na+-based pipette (removes Ca2+ block, doubles conductance vs standard); single-channel amplitudes from 5-20 repeated traces, slope conductance from I-V linear regression | ERROR-AS-REPORTED: 3.0 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,77.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'77.5','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT or mutants',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (pH 7.3 with KOH) — zeroing membrane potential','150 mM NaCl, 10 HEPES (pH 7.3 with NaOH), divalent-free',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00156','Unitary conductance of E2133Q was similar to E2133A mutants, whereas unitary conductance of E2133D and E2133K increased or drastically decreased compared with WT (77.5±3.0 and 20.0±1.3 pS, respectively; mean±s.e.m.; Fig. 4b-d and Supplementary Table 3).','Results (Fig. 4b–d; Supplementary Table 3)','high','Charge-conserving but shorter side chain increases conductance above WT.','mPiezo1-E2133D_HEK293T_cell-attached_-80mV_NaDVF-pipette_slope-conductance_Fig4b-d',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(550,'MAIC:BX:00550',1,NULL,NULL,88,'500 ms negative pressure pulses (HSPC-1); divalent-free Na+-based pipette (removes Ca2+ block, doubles conductance vs standard); single-channel amplitudes from 5-20 repeated traces, slope conductance from I-V linear regression | ERROR-AS-REPORTED: 1.3 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'20.0','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT or mutants',NULL,7.3,'140 KCl, 1 MgCl2, 10 glucose, 10 HEPES (pH 7.3 with KOH) — zeroing membrane potential','150 mM NaCl, 10 HEPES (pH 7.3 with NaOH), divalent-free',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00157','Unitary conductance of E2133Q was similar to E2133A mutants, whereas unitary conductance of E2133D and E2133K increased or drastically decreased compared with WT (77.5±3.0 and 20.0±1.3 pS, respectively; mean±s.e.m.; Fig. 4b-d and Supplementary Table 3).','Results (Fig. 4b–d; Supplementary Table 3)','high','Charge-reversal mutation drastically decreases conductance; E2133K pressure sensitivity unchanged (Supplementary Fig. 7, no fitted P50 printed).','mPiezo1-E2133K_HEK293T_cell-attached_-80mV_NaDVF-pipette_slope-conductance_Fig4b-d',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(551,'MAIC:BX:00551',1,NULL,NULL,NULL,'asymmetric 150 mM CsCl / 100 mM CaCl2 for current-voltage and reversal potential (liquid junction potential corrected) | ERROR-AS-REPORTED: 0.6 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'10.3','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT or mutants',NULL,7.3,'100 CaCl2, 10 HEPES (pH 7.3 with CsOH)','150 CsCl, 10 HEPES (pH 7.3 with CsOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00158','Under these conditions, E2133Q and E2133K mutations significantly shift the channel''s reversal potential to the left (5.0±0.5 and 2.6±0.4 mV, respectively, versus 10.3±0.6 mV for WT; mean±s.e.m.; Fig. 4e,f).','Results (Fig. 4e, f)','high','Liquid junction potential corrected for ion-selectivity experiments. Positive Erev in asymmetric CsCl/CaCl2 indicates Ca2+ permeability.','mPiezo1-WT_HEK293T_whole-cell_150CsCl-100CaCl2_Erev_Fig4e-f',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(552,'MAIC:BX:00552',1,NULL,NULL,89,'asymmetric 150 mM CsCl / 100 mM CaCl2 for current-voltage and reversal potential (liquid junction potential corrected) | ERROR-AS-REPORTED: 0.5 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'5.0','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT or mutants',NULL,7.3,'100 CaCl2, 10 HEPES (pH 7.3 with CsOH)','150 CsCl, 10 HEPES (pH 7.3 with CsOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00159','Under these conditions, E2133Q and E2133K mutations significantly shift the channel''s reversal potential to the left (5.0±0.5 and 2.6±0.4 mV, respectively, versus 10.3±0.6 mV for WT; mean±s.e.m.; Fig. 4e,f).','Results (Fig. 4e, f)','high','Shift attributed to decreased Ca2+ permeability (PCa/PCs decreased 1.3-fold; chloride unchanged).','mPiezo1-E2133Q_HEK293T_whole-cell_150CsCl-100CaCl2_Erev_Fig4e-f',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(553,'MAIC:BX:00553',1,NULL,NULL,88,'asymmetric 150 mM CsCl / 100 mM CaCl2 for current-voltage and reversal potential (liquid junction potential corrected) | ERROR-AS-REPORTED: 0.4 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.6,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.6','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT or mutants',NULL,7.3,'100 CaCl2, 10 HEPES (pH 7.3 with CsOH)','150 CsCl, 10 HEPES (pH 7.3 with CsOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00160','Under these conditions, E2133Q and E2133K mutations significantly shift the channel''s reversal potential to the left (5.0±0.5 and 2.6±0.4 mV, respectively, versus 10.3±0.6 mV for WT; mean±s.e.m.; Fig. 4e,f).','Results (Fig. 4e, f)','high','Charge-reversal mutation; also increases PCl/PNa 1.5-fold (fold only, archived).','mPiezo1-E2133K_HEK293T_whole-cell_150CsCl-100CaCl2_Erev_Fig4e-f',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(554,'MAIC:BX:00554',1,NULL,NULL,NULL,'bi-ionic PCl/PNa measurement, GHK equation',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.14,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0.14',NULL,'INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT',NULL,7.3,'30 NaCl, 10 HEPES, 225 sucrose (pH 7.3 with NaOH)','150 NaCl, 10 HEPES (pH 7.3 with NaOH)',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00161','We found that mPiezo1 permeates chloride with PCl/PNa of 0.14, and that E2133K mutation significantly increases this ratio by 1.5-fold compared with WT (Supplementary Fig. 6a,b).','Results (Supplementary Fig. 6a, b)','medium','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). Dimensionless ratio, no error/n printed. E2133K 1.5-fold increase given as fold only (archived, no arithmetic). Schema-gap: no ratio column in DB.','mPiezo1-WT_HEK293T_whole-cell_biionic-PCl-PNa_GHK_SuppFig6a-b',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(555,'MAIC:BX:00555',1,NULL,NULL,NULL,'bi-ionic PCa/PCs measurement, GHK equation',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1.21,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1.21',NULL,'INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection (FuGene HD, 2 µg cDNA)','HEK293T expressing mPiezo1 WT',NULL,7.3,'50 Ca-gluconate, 0.5 CaCl2, 10 HEPES, 170 sucrose (pH 7.3 with CsOH)','149 Cs-methanesulfonate, 1 CsCl, 10 HEPES (pH 7.3 with CsOH)',NULL,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00162','Indeed, we found a PCa/PCs ratio of 1.21 for mPiezo1 which is decreased by 1.3-fold in E2133Q mutant (Supplementary Fig. 6c,d).','Results (Supplementary Fig. 6c, d)','medium','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). Dimensionless ratio, no error/n printed. E2133Q 1.3-fold decrease given as fold only (archived). Schema-gap: no ratio column in DB.','mPiezo1-WT_HEK293T_whole-cell_biionic-PCa-PCs_GHK_SuppFig6c-d',NULL,'LITERATURE','2026-11-08',22,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(556,'MAIC:BX:00556',1,NULL,NULL,NULL,'glass probe on piezoelectric actuator, 150-ms mechanical steps in 1-µm increments; MA inward currents, monoexponential fit of inactivating component for time constant of inactivation | ERROR-AS-REPORTED: 0.2 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.1','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','Flp-In T-Rex doxycycline-inducible stable lines (24-48 h induction), human PIEZO1 WT or mutant','HEK293',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00166','The K1877del mutant exhibited both faster channel-inactivation kinetics compared with wild type (control, τ = 6.1 ± 0.2 milliseconds vs K1877del, τ = 5.3 ± 0.2 milliseconds; mean ± standard error of the mean, P < .009, Student t test)','Results (Table 3; Figure 3B; Figure 4A paragraph)','high','n = 41 = N (tested cells) from Table 3 (''N, number of tested cells''); Table 3 also lists n (number of experiments) = 8 for WT. Monoexponential fit of inactivating component.','hPIEZO1-WT_HEK293_FlpInTrex_whole-cell_-80mV_poke_tau-inact_Table3','41','LITERATURE','2026-11-08',23,'2026-11-08 00:00:00.000000',NULL);
