INSERT INTO "biophysics_experiment" VALUES(561,'MAIC:BX:00561',1,NULL,NULL,93,'glass probe on piezoelectric actuator, 150-ms mechanical steps in 1-µm increments; MA inward currents, monoexponential fit of inactivating component for time constant of inactivation | ERROR-AS-REPORTED: 0.5 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.9','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','Flp-In T-Rex doxycycline-inducible stable lines (24-48 h induction), human PIEZO1 WT or mutant','HEK293',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00171','R2488Q; 23; 3.9 ± 0.2***; 6.9 ± 0.5; 8; 4.2 ± 0.1*; Blunted response; Colocalization with ER and Golgi','Results (Table 3)','high','Inactivation not different from WT; trafficking defect + blunted osmotic response. n = N (tested cells) = 23.','hPIEZO1-R2488Q_HEK293_FlpInTrex_whole-cell_-80mV_poke_tau-inact_Table3','23','LITERATURE','2026-11-08',23,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(562,'MAIC:BX:00562',1,NULL,NULL,94,'glass probe on piezoelectric actuator, 150-ms mechanical steps in 1-µm increments; MA inward currents, monoexponential fit of inactivating component for time constant of inactivation | ERROR-AS-REPORTED: 0.2 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5.8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'5.8','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','Flp-In T-Rex doxycycline-inducible stable lines (24-48 h induction), human PIEZO1 WT or mutant','HEK293',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00172','R2302H; 27; 4.1 ± 0.2***; 5.8 ± 0.2; 6; 0.3 ± 0.1; No response; Colocalization with ER and Golgi','Results (Table 3)','high','Inactivation not different from WT; trafficking defect variant. n = N (tested cells) = 27.','hPIEZO1-R2302H_HEK293_FlpInTrex_whole-cell_-80mV_poke_tau-inact_Table3','27','LITERATURE','2026-11-08',23,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(563,'MAIC:BX:00563',1,NULL,NULL,95,'glass probe on piezoelectric actuator, 150-ms mechanical steps in 1-µm increments; MA inward currents, monoexponential fit of inactivating component for time constant of inactivation | ERROR-AS-REPORTED: 0.2 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'5.3','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','Flp-In T-Rex doxycycline-inducible stable lines (24-48 h induction), human PIEZO1 WT or mutant','HEK293',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00173','The K1877del mutant exhibited both faster channel-inactivation kinetics compared with wild type (control, τ = 6.1 ± 0.2 milliseconds vs K1877del, τ = 5.3 ± 0.2 milliseconds; mean ± standard error of the mean, P < .009, Student t test)','Results (Table 3; Figure 4A paragraph)','high','Loss-of-function variant (faster inactivation, P < .009 vs WT). n = N (tested cells) = 20 from Table 3.','hPIEZO1-K1877del_HEK293_FlpInTrex_whole-cell_-80mV_poke_tau-inact_Table3','20','LITERATURE','2026-11-08',23,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(564,'MAIC:BX:00564',1,NULL,NULL,96,'glass probe on piezoelectric actuator, 150-ms mechanical steps in 1-µm increments; MA inward currents, monoexponential fit of inactivating component for time constant of inactivation | ERROR-AS-REPORTED: 0.5 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'9.9','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','Flp-In T-Rex doxycycline-inducible stable lines (24-48 h induction), human PIEZO1 WT or mutant','HEK293',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO1-EX-00174','E2496ELE; 30; 4.7 ± 0.2; 9.9 ± 0.5***; 4; 0.9 ± 0.1; No response; None','Results (Table 3)','high','p.Leu2495_Glu2496dup; text quotes ''9.9 ± 0.05'' once (''displayed increased inactivation rate compared with wild-type (9.9 ± 0.05, P < .001'') but Table 3 prints 9.9 ± 0.5 — table value used; discrepancy noted. n = N (tested cells) = 30.','hPIEZO1-E2496ELE_HEK293_FlpInTrex_whole-cell_-80mV_poke_tau-inact_Table3','30','LITERATURE','2026-11-08',23,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(565,'MAIC:BX:00565',2,NULL,NULL,NULL,'HSPC (ALA Scientific); stepwise negative pressure, 3-s steps, up to −60 mmHg; single-channel I-V at −120 to −40 mV in 20-mV steps at low pressures adjusted per cell | STIMULUS: -60 mmHg | ERROR-AS-REPORTED: 1.14 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'23.4','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection, same constructs','N2A-P1KO (Neuro2A PIEZO1-knockout)',NULL,NULL,NULL,NULL,-100.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00001','The analysis of single-channel openings at low pressures and varying holding potentials, showed that IDR3del has a significantly larger single-channel conductance than full-length PIEZO2 (IDR3del, 34.07 ± 1.26 pS vs. PIEZO2, 23.4 ± 1.14 pS, mean ± SEM)','Results (Fig 2d–f)','high','Mouse PIEZO2 (piezo2-pSPORT6 backbone) full-length WT. Slope conductance from linear regression of single-channel I-V in cell-attached patches; single-channel openings evoked by low pressures. SEM per text. n per group only shown in figure brackets, not printed in text. Gene subject verified: PIEZO2 (not PIEZO1). Sub/superscript rendering in quote un-flattened from XML (IDR3<sup>del</sup> → IDR3del).','mPIEZO2_N2A-P1KO_cell-attached_stretch_low-pressure-IV_slope-conductance_Fig2f',NULL,'LITERATURE','2026-11-08',24,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(566,'MAIC:BX:00566',2,NULL,NULL,97,'HSPC (ALA Scientific); stepwise negative pressure, 3-s steps, up to −60 mmHg; single-channel I-V at −120 to −40 mV in 20-mV steps at low pressures adjusted per cell | STIMULUS: -60 mmHg | ERROR-AS-REPORTED: 1.26 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34.07,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'34.07','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection, same constructs','N2A-P1KO (Neuro2A PIEZO1-knockout)',NULL,NULL,NULL,NULL,-100.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00002','The analysis of single-channel openings at low pressures and varying holding potentials, showed that IDR3del has a significantly larger single-channel conductance than full-length PIEZO2 (IDR3del, 34.07 ± 1.26 pS vs. PIEZO2, 23.4 ± 1.14 pS, mean ± SEM)','Results (Fig 2d–f)','high','Experimental deletion mutant of intracellular IDR3 (not a disease variant); variant token as printed. Same recording configuration as the WT row (cell-attached stretch, single-channel I-V slope). Statistics per figure legend: Kruskal-Wallis overall p=0.0069; Dunn''s post-test pairwise PIEZO2 vs IDR3del *p=0.0096.','mPIEZO2-IDR3del_N2A-P1KO_cell-attached_stretch_low-pressure-IV_slope-conductance_Fig2f',NULL,'LITERATURE','2026-11-08',24,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(567,'MAIC:BX:00567',2,NULL,NULL,97,'HSPC (ALA Scientific); stepwise negative pressure, 3-s steps, up to −60 mmHg; single-channel I-V at −120 to −40 mV in 20-mV steps at low pressures adjusted per cell | STIMULUS: -60 mmHg | ERROR-AS-REPORTED: 0.45 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,35.7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'35.7','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection, same constructs','N2A-P1KO (Neuro2A PIEZO1-knockout)',NULL,NULL,NULL,NULL,-100.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00003','Single-channel recordings showed that the unitary conductance of IDR3del and P2-(IDR3 + lateral plug)del did not significantly differ (IDR3del: 35.7 ± 0.45 pS vs. P2-(IDR3 + lateral plug)del: 34.83 ± 2.90 pS','Results (Fig 3d)','high','Second independent experiment (lateral-plug hypothesis), separate from the Fig 2 comparison — hence a separate row from the 34.07 pS value despite identical construct. Error type not explicitly restated here; treated as SEM per the paper''s standing mean ± SEM convention (Fig 2 legend / statistics section).','mPIEZO2-IDR3del_N2A-P1KO_cell-attached_stretch_slope-conductance_Fig3d',NULL,'LITERATURE','2026-11-08',24,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(568,'MAIC:BX:00568',2,NULL,NULL,98,'HSPC (ALA Scientific); stepwise negative pressure, 3-s steps, up to −60 mmHg; single-channel I-V at −120 to −40 mV in 20-mV steps at low pressures adjusted per cell | STIMULUS: -60 mmHg | ERROR-AS-REPORTED: 2.9 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34.83,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'34.83','pS','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','transient transfection, same constructs','N2A-P1KO (Neuro2A PIEZO1-knockout)',NULL,NULL,NULL,NULL,-100.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00004','Single-channel recordings showed that the unitary conductance of IDR3del and P2-(IDR3 + lateral plug)del did not significantly differ (IDR3del: 35.7 ± 0.45 pS vs. P2-(IDR3 + lateral plug)del: 34.83 ± 2.90 pS','Results (Fig 3d)','high','Double deletion (IDR3 + lateral plug) on PIEZO2 backbone — gene subject is PIEZO2 (''P2-'' prefix), not a PIEZO1 chimera; the PIEZO1-IDR2P2 chimera values elsewhere in the paper are NOT rowed (paralog). Error type SEM per paper convention.','mPIEZO2-(IDR3+lateral-plug)del_N2A-P1KO_cell-attached_stretch_slope-conductance_Fig3d',NULL,'LITERATURE','2026-11-08',24,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(569,'MAIC:BX:00569',2,NULL,NULL,NULL,'refined mechano-clamp: fire-polished glass probe (tip 2-3 µm) at 45°, 0.42-µm increments, 1 µm/ms ramp; threshold = latency x probe speed (current-onset criterion I<mean_baseline-6SD); 3 stimulus locations/cell, most sensitive used | ERROR-AS-REPORTED: 0.19 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.86,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.86','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection, Piezo2-IRES-GFP (mouse piezo2-pSPORT6 backbone) WT and point mutants','N2a-PIEZO1-KO',22.0,7.3,'extracellular (pH 7.3 NaOH); detailed composition in SI Appendix','125 K-gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA, 2 GTP, 2 ATP (pH 7.3 KOH)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00005','The mean inactivation time constant of PIEZO2-B2Ldel currents (3.5 ± 0.26 ms) was slightly but not significantly bigger than that of PIEZO2-WT currents (2.86 ± 0.19 ms','Results (Fig 3F; text before Fig 3 legend)','high','Mouse PIEZO2-WT (Piezo2-IRES-GFP). Whole-cell poke, −60 mV, 1 µm/ms ramp; single-exponential fit of MA current decay (Methods). SEM per figure-legend convention (''Comparison of the mean ± SEM inactivation time constants (τinact)''). n not printed in text (in-graph). Gene subject verified: PIEZO2-WT.','mPIEZO2_N2a-P1KO_whole-cell_poke_1um-per-ms_-60mV_single-exp-tau-inact_Fig3F',NULL,'LITERATURE','2026-11-08',25,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(570,'MAIC:BX:00570',2,NULL,NULL,99,'refined mechano-clamp: fire-polished glass probe (tip 2-3 µm) at 45°, 0.42-µm increments, 1 µm/ms ramp; threshold = latency x probe speed (current-onset criterion I<mean_baseline-6SD); 3 stimulus locations/cell, most sensitive used | ERROR-AS-REPORTED: 0.26 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'3.5','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection, Piezo2-IRES-GFP (mouse piezo2-pSPORT6 backbone) WT and point mutants','N2a-PIEZO1-KO',22.0,7.3,'extracellular (pH 7.3 NaOH); detailed composition in SI Appendix','125 K-gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA, 2 GTP, 2 ATP (pH 7.3 KOH)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00006','The mean inactivation time constant of PIEZO2-B2Ldel currents (3.5 ± 0.26 ms) was slightly but not significantly bigger than that of PIEZO2-WT currents (2.86 ± 0.19 ms','Results (Fig 3F; text before Fig 3 legend)','high','B2Ldel = deletion of beam-to-latch linker + latch on PIEZO2 (experimental deletion mutant, not a disease variant). Not significantly different from WT (text). Superscript del un-flattened from XML in quote.','mPIEZO2-B2Ldel_N2a-P1KO_whole-cell_poke_1um-per-ms_-60mV_single-exp-tau-inact_Fig3F',NULL,'LITERATURE','2026-11-08',25,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(571,'MAIC:BX:00571',2,NULL,NULL,NULL,'refined mechano-clamp: fire-polished glass probe (tip 2-3 µm) at 45°, 0.42-µm increments, 1 µm/ms ramp; threshold = latency x probe speed (current-onset criterion I<mean_baseline-6SD); 3 stimulus locations/cell, most sensitive used | ERROR-AS-REPORTED: 1.2 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'11.9','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection, Piezo2-IRES-GFP (mouse piezo2-pSPORT6 backbone) WT and point mutants','N2a-PIEZO1-KO',22.0,7.3,'extracellular (pH 7.3 NaOH); detailed composition in SI Appendix','125 K-gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA, 2 GTP, 2 ATP (pH 7.3 KOH)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00007','the reversal potentials of the two channels did not significantly differ from one another (PIEZO2-WT, 11.9 ± 1.2 mV, n = 7 vs. PIEZO2-B2Ldel, 15.4 ± 3.2 mV, n = 5, Student’s t test, P = 0.268)','Results (Fig 3 paragraph; τinact/E_rev sentence)','high','MA-current I-V under poking, K-gluconate-based pipette / NaCl-based bath. Error type not restated at this sentence; SEM per paper-wide mean ± SEM convention. Student''s t test P=0.268 (not significant).','mPIEZO2_N2a-P1KO_whole-cell_poke_I-V_Erev_Fig3','7','LITERATURE','2026-11-08',25,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(572,'MAIC:BX:00572',2,NULL,NULL,99,'refined mechano-clamp: fire-polished glass probe (tip 2-3 µm) at 45°, 0.42-µm increments, 1 µm/ms ramp; threshold = latency x probe speed (current-onset criterion I<mean_baseline-6SD); 3 stimulus locations/cell, most sensitive used | ERROR-AS-REPORTED: 3.2 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,15.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'15.4','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection, Piezo2-IRES-GFP (mouse piezo2-pSPORT6 backbone) WT and point mutants','N2a-PIEZO1-KO',22.0,7.3,'extracellular (pH 7.3 NaOH); detailed composition in SI Appendix','125 K-gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA, 2 GTP, 2 ATP (pH 7.3 KOH)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00008','the reversal potentials of the two channels did not significantly differ from one another (PIEZO2-WT, 11.9 ± 1.2 mV, n = 7 vs. PIEZO2-B2Ldel, 15.4 ± 3.2 mV, n = 5, Student’s t test, P = 0.268)','Results (Fig 3 paragraph; τinact/E_rev sentence)','high','Same deletion mutant as tau_inact row; E_rev not significantly different from WT. n=5 cells.','mPIEZO2-B2Ldel_N2a-P1KO_whole-cell_poke_I-V_Erev_Fig3','5','LITERATURE','2026-11-08',25,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(573,'MAIC:BX:00573',2,NULL,NULL,NULL,'fire-polished glass pipette (tip 3–4 µm) at 80°, piezo-electric microstage, 1-µm increments every 10 s, ramp velocity 1 µm/ms, 150-ms stimulus; I-V: voltage steps from −60 mV holding applied 0.7 s before stimulation | ERROR-AS-REPORTED: 0.6 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.2','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection of human PIEZO2 cDNA (WT, I802F, E2727del) + GFP','HEK293T',NULL,7.3,'130 NaCl, 3 KCl, 1 MgCl2, 10 HEPES, 2.5 CaCl2, 10 glucose (pH 7.3 NaOH)','133 CsCl, 10 HEPES, 5 EGTA, 1 CaCl2, 1 MgCl2, 4 MgATP, 0.4 Na2GTP (pH 7.3 CsOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00009','Human PIEZO2 MA currents have a time constant of inactivation τ of 6.2 ± 0.6 ms (n = 12 cells) at -80 mV when fitted with a monoexponential equation','Results (Fig 2 D and E)','high','Human PIEZO2 WT (disease-paper WT baseline). Whole-cell poke at −80 mV, monoexponential fit. SEM per Fig 2/3 legend ''mean ± SEM''. The trailing clause ''which is comparable to mouse Piezo2 (∼7 ms)'' is a literature comparison (Coste 2010) and is NOT extracted (intro-cited value). En-dash ''–80 mV'' as printed.','hPIEZO2_HEK293T_whole-cell_poke_-80mV_monoexp-tau-inact_Fig2D-E','12','LITERATURE','2026-11-08',26,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(574,'MAIC:BX:00574',2,NULL,NULL,100,'fire-polished glass pipette (tip 3–4 µm) at 80°, piezo-electric microstage, 1-µm increments every 10 s, ramp velocity 1 µm/ms, 150-ms stimulus; I-V: voltage steps from −60 mV holding applied 0.7 s before stimulation','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection of human PIEZO2 cDNA (WT, I802F, E2727del) + GFP','HEK293T',NULL,7.3,'130 NaCl, 3 KCl, 1 MgCl2, 10 HEPES, 2.5 CaCl2, 10 glucose (pH 7.3 NaOH)','133 CsCl, 10 HEPES, 5 EGTA, 1 CaCl2, 1 MgCl2, 4 MgATP, 0.4 Na2GTP (pH 7.3 CsOH)',-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00010','I802F and E2727del MA currents have similar amplitudes compared with wild-type PIEZO2 currents, as well as a linear current voltage relationship with a reversal potential close to 0 mV under the recording conditions','Results (Fig 2 B and C)','medium','Value printed as ''close to 0 mV'' — approximate, no error, single span covering both DA5 mutants (I802F, E2727del) hence variant field carries both tokens and one row (value not resolved per mutant). relation ''~''. Linear I-V noted (CsCl pipette / NaCl bath). WT E_rev not separately printed.','hPIEZO2-I802F+E2727del_HEK293T_whole-cell_poke_I-V_Erev_Fig2B-C',NULL,'LITERATURE','2026-11-08',26,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(575,'MAIC:BX:00575',2,NULL,NULL,NULL,'blunt glass probe, piezo-electric driver; periodically applied 10-ms square pulses (9.1±1.2 µm indentation) at 1, 5, 20, 40 Hz; 4-s trains framed by two standard 10-ms test pulses (step1/step2) | STIMULUS: 9.1 µm | ERROR-AS-REPORTED: 0.4 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.0','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','transient transfection of mouse Piezo2 (WT, I802F, E2727del)','HEK293t',NULL,NULL,NULL,NULL,-100.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00011','The time course of inactivation (τ) during an isolated single step pulse ‘step1’ was similar to the values from our own recordings with wild-type mouse Piezo2 in HEK293t cells (DRG: 3.1±0.3 ms, N = 7; HEK293t: 2.0±0.4 ms, N = 10; P=0.059, Student’s t-test)','Results (Figure 7A paragraph)','high','Gene subject verified: mouse Piezo2 WT in HEK293t (this row) — the companion 3.1 ms value is the native DRG row. Single step pulse (step1) decay tau, 10-ms poke at 9.1±1.2 µm, −100 mV. SEM per ''All data are mean ± s.e.m.'' Curly quotes around step1 as printed.','mPIEZO2_HEK293t_whole-cell_poke_10ms-pulse_9.1um_-100mV_tau-inact_Fig7A','10','LITERATURE','2026-11-08',10,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(576,'MAIC:BX:00576',2,NULL,NULL,NULL,'blunt glass pipette; repetitive 10-ms square pulses (17.3±2.5 µm indentation) at 1, 5, 20, 40 Hz; voltage clamp | STIMULUS: 17.3 µm | ERROR-AS-REPORTED: 0.3 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'3.1','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native (isolated, cultured RA DRG neurons; Piezo2-mediated RA current)','rapidly-adapting (RA) DRG neurons',NULL,NULL,NULL,NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00012','The time course of inactivation (τ) during an isolated single step pulse ‘step1’ was similar to the values from our own recordings with wild-type mouse Piezo2 in HEK293t cells (DRG: 3.1±0.3 ms, N = 7; HEK293t: 2.0±0.4 ms, N = 10; P=0.059, Student’s t-test)','Results (Figure 7A paragraph)','high','Native RA current (Piezo2-mediated per Ranade et al. 2014b, own recordings) in DRG neurons, −80 mV, 10-ms pulses at 17.3±2.5 µm; within RA classification <10 ms for every cell. Patched as native-cell measurement (expression_system native), not heterologous.','mPIEZO2-native_DRG-RA_whole-cell_poke_10ms-pulse_17.3um_-80mV_tau-inact_Fig7A','7','LITERATURE','2026-11-08',10,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(577,'MAIC:BX:00577',2,NULL,NULL,NULL,'glass probe (tip 2-3 µm) driven by piezoelectric actuator at 48° to coverslip; 50-ms displacements, 0.3-µm steps every 5 s; probe speed 2 µm/ms | ERROR-AS-REPORTED: 1.7 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'8.1','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'PERFORATED_PATCH','primary culture (dissociated Merkel cells, no heterologous expression)','dissociated Merkel cells from Atoh1/nGFP mouse pups (P2-P5); endogenous Piezo2-dependent MA currents',NULL,7.4,'140 NaCl, 5 KCl, 10 HEPES, 10 D-glucose, 2 MgCl2, 2 CaCl2 (pH 7.4 NaOH)','70 KOH, 70 KCl, 10 NaCl, 1 MgCl2, 0.5 CaCl2, 5 EGTA, 2 MgATP, 10 HEPES (pH 7.2) + amphotericin B 100-180 µg/ml (perforated patch)',-70.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00013','τinactivation (ms); 8.1 ± 1.7','Extended Data Table 1 (mean ± SEM; mechanically activated, N = 6, 6 trials); in-text parallel value 8±2 ms in Results (Fig. 1g)','high','Own-data: whole-cell (perforated-patch) MA currents of native Merkel cells; the paper establishes Piezo2 as the underlying channel (qPCR enrichment; biophysical match; companion Woo 2014). Table 1 header declares ''(mean ± SEM)''. In-text coarser print of the same measurement is ''fast inactivation time constants (8±2 ms; Fig. 1g)''. Gene subject = mouse Merkel-cell Piezo2-dependent current (not heterologous PIEZO2). The ''(Piezo2: τ inactivation =7±1 ms; E rev =9±2 mV; RR block ~80%)'' in the same paragraph cites Coste 2010 and is NOT rowed.','mouse-Merkel-cell_endogenous-Piezo2-MA perforated-patch_poke_-70mV_tau-inact_EDTable1','6','LITERATURE','2026-11-08',27,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(578,'MAIC:BX:00578',2,NULL,NULL,NULL,'glass probe (tip 2-3 µm) driven by piezoelectric actuator at 48° to coverslip; 50-ms displacements, 0.3-µm steps every 5 s; probe speed 2 µm/ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1.0,NULL,NULL,NULL,'1.0','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'PERFORATED_PATCH','primary culture (dissociated Merkel cells, no heterologous expression)','dissociated Merkel cells from Atoh1/nGFP mouse pups (P2-P5); endogenous Piezo2-dependent MA currents',NULL,7.4,'140 NaCl, 5 KCl, 10 HEPES, 10 D-glucose, 2 MgCl2, 2 CaCl2 (pH 7.4 NaOH)','70 KOH, 70 KCl, 10 NaCl, 1 MgCl2, 0.5 CaCl2, 5 EGTA, 2 MgATP, 10 HEPES (pH 7.2) + amphotericin B 100-180 µg/ml (perforated patch)',-70.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00014','Rise time t10-90% (ms); 1.0 ± 0.1','Extended Data Table 1 (mechanically activated, N = 6, 6 trials)','high','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). 10-90% rise time of whole-cell MA current, NOT an exponential tau_act — routed to schema_gap macroscopic_rise_time to avoid posing as tau_act_ms. Schema registers macroscopic rise time in s; as-printed unit here is ms (1.0 ms = 0.001 s; ×1000-to-ms hazard declared). Table 1 header declares ''(mean ± SEM)''.','mouse-Merkel-cell_endogenous-Piezo2-MA perforated-patch_poke_-70mV_rise-t10-90_EDTable1','6','LITERATURE','2026-11-08',27,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(579,'MAIC:BX:00579',2,NULL,NULL,NULL,'glass probe (tip 2-3 µm) driven by piezoelectric actuator at 48° to coverslip; 50-ms displacements, 0.3-µm steps every 5 s; probe speed 2 µm/ms | ERROR-AS-REPORTED: 3','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'8','mV','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'PERFORATED_PATCH','primary culture (dissociated Merkel cells, no heterologous expression)','dissociated Merkel cells from Atoh1/nGFP mouse pups (P2-P5); endogenous Piezo2-dependent MA currents',NULL,7.4,'140 NaCl, 5 KCl, 10 HEPES, 10 D-glucose, 2 MgCl2, 2 CaCl2 (pH 7.4 NaOH)','70 KOH, 70 KCl, 10 NaCl, 1 MgCl2, 0.5 CaCl2, 5 EGTA, 2 MgATP, 10 HEPES (pH 7.2) + amphotericin B 100-180 µg/ml (perforated patch)',-70.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00015','Mechanotransduction currents showed a linear current-voltage relation (reversal potential, 8±3 mV, Fig. 1h), indicating non-rectifying, non-selective ','Results paragraph 2 (Fig. 1h; N=5)','medium','Reversal potential estimated by linear regression of I-V at multiple holding potentials (-75 to +50 mV, 25 mV steps). Error type not stated for this in-text value (Table 1 uses mean±SEM convention; ±3 as printed). Non-rectifying, non-selective cation current of native Merkel cells.','mouse-Merkel-cell_endogenous-Piezo2-MA perforated-patch_poke_IV-ramp_-75to+50mV_Erev_Fig1h','5','LITERATURE','2026-11-08',27,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(580,'MAIC:BX:00580',2,NULL,NULL,NULL,'glass probe (tip 2-3 µm) driven by piezoelectric actuator at 48° to coverslip; 50-ms displacements, 0.3-µm steps every 5 s; probe speed 2 µm/ms','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'LINEAR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'LINEAR',NULL,'INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'PERFORATED_PATCH','primary culture (dissociated Merkel cells, no heterologous expression)','dissociated Merkel cells from Atoh1/nGFP mouse pups (P2-P5); endogenous Piezo2-dependent MA currents',NULL,7.4,'140 NaCl, 5 KCl, 10 HEPES, 10 D-glucose, 2 MgCl2, 2 CaCl2 (pH 7.4 NaOH)','70 KOH, 70 KCl, 10 NaCl, 1 MgCl2, 0.5 CaCl2, 5 EGTA, 2 MgATP, 10 HEPES (pH 7.2) + amphotericin B 100-180 µg/ml (perforated patch)',-70.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00016','Mechanotransduction currents showed a linear current-voltage relation (reversal potential, 8±3 mV, Fig. 1h), indicating non-rectifying, non-selective ','Results paragraph 2 (Fig. 1h; N=5)','high','iv_relation holds the enum NAME in value (no numeric). Paper wording ''linear current-voltage relation ... indicating non-rectifying, non-selective cation channels''.','mouse-Merkel-cell_endogenous-Piezo2-MA perforated-patch_poke_IV-ramp_-75to+50mV_I-V-linear_Fig1h','5','LITERATURE','2026-11-08',27,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(581,'MAIC:BX:00581',2,NULL,NULL,NULL,'same probe/protocol as N2A recordings; currents categorised rapid/intermediate/slow by inactivation within the 200-ms stimulus | TEMPERATURE-AS-REPORTED: 22-24 | ERROR-AS-REPORTED: 5.12 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.16,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14.16','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','primary culture (no transfection)','isolated mouse DRG neurons (endogenous RA/IA/SA MA currents; RA class PIEZO2-mediated per ccPA-inhibition experiment)',NULL,7.4,'137 NaCl, 5 KCl, 1 MgCl2, 2 CaCl2, 10 HEPES, 10 glucose (pH 7.4)','133 CsCl, 1 MgCl2, 1 CaCl2, 5 EGTA, 4 Na2ATP, 10 HEPES (pH 7.3, CsOH)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00017','The inactivation time constants (tau) of these currents were 14.16 ± 5.12 ms (mean ± SD) s','Methods, DRG neurons section (classification criteria; ccPA experiments Fig. 4e-l)','medium','Own-data: mean inactivation tau of the RA class of endogenous DRG MA currents; the paper states this tau is ''very similar to PIEZO2 transiently transfected in N2A-P1KO cells'' and the ccPA experiment identifies the RA population as PIEZO2-mediated. Error explicitly ''(mean ± SD)''. n for this summary is not printed in text (Fig. 4 DRG cohorts are n=100/100 cells) -> n blank, confidence medium. IA (30.67±10.70 ms) and SA (111.85±52.47 ms) class taus are non-PIEZO2-dominated currents and archived, not rowed.','mouse-DRG_endogenous-RA-MA-currents(PIEZO2)_whole-cell_poke_-60mV_Methods',NULL,'LITERATURE','2026-11-08',28,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(582,'MAIC:BX:00582',2,NULL,NULL,NULL,'fire-polished closed-tip poking pipette (2-5.5 µm diameters) on piezo actuator at 35°/45°/70°; 25 ramp-and-hold stimuli, 0.2-µm increments; velocity series 2 -> 0.062 µm/ms (8 µm displacement, halved each step); threshold = probe displacement at -10 pA current crossing | ERROR-AS-REPORTED: 0.37 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.86,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.86','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','heterologous transfection (Neuro2A PIEZO1-knockout, N2A-P1KO)','N2A-P1KO cells transfected with PIEZO2-HA-IRES-GFP (plasmid from Taberner 2019; species not restated in this paper)',NULL,7.4,'4 KCl, 140 NaCl, 1 MgCl2, 2 CaCl2, 4 glucose, 10 HEPES (pH 7.4)','125 potassium gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA (pH 7.3)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00018','For PIEZO2-mediated currents, we also observed a trend toward faster inactivation at higher stimulation angles (35°: τinact = 2.86 ± 0.37 ms, 45°: τinact = 2.21 ± 0.16 ms, 70°: τinact = 2.26 ± 0.28 ms), but no ','Results (Fig. 2i)','high','Systematic angle series at constant velocity 1.5 µm/ms and probe tip 3 µm; mean ± SEM per Statistics section. n shown only on graph, not printed in text.','PIEZO2_N2A-P1KO_whole-cell_poke_-60mV_angle35deg_probe3um_vel1.5um-ms',NULL,'LITERATURE','2026-11-08',29,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(583,'MAIC:BX:00583',2,NULL,NULL,NULL,'fire-polished closed-tip poking pipette (2-5.5 µm diameters) on piezo actuator at 35°/45°/70°; 25 ramp-and-hold stimuli, 0.2-µm increments; velocity series 2 -> 0.062 µm/ms (8 µm displacement, halved each step); threshold = probe displacement at -10 pA current crossing | ERROR-AS-REPORTED: 0.16 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.21,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.21','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','heterologous transfection (Neuro2A PIEZO1-knockout, N2A-P1KO)','N2A-P1KO cells transfected with PIEZO2-HA-IRES-GFP (plasmid from Taberner 2019; species not restated in this paper)',NULL,7.4,'4 KCl, 140 NaCl, 1 MgCl2, 2 CaCl2, 4 glucose, 10 HEPES (pH 7.4)','125 potassium gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA (pH 7.3)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00019','For PIEZO2-mediated currents, we also observed a trend toward faster inactivation at higher stimulation angles (35°: τinact = 2.86 ± 0.37 ms, 45°: τinact = 2.21 ± 0.16 ms, 70°: τinact = 2.26 ± 0.28 ms), but no ','Results (Fig. 2i and 3i)','high','Same condition/dataset printed twice (Fig. 2i at 45°; Fig. 3i at 3 µm tip) — rowed once. Mean ± SEM; n only on graph.','PIEZO2_N2A-P1KO_whole-cell_poke_-60mV_angle45deg_probe3um_vel1.5um-ms',NULL,'LITERATURE','2026-11-08',29,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(584,'MAIC:BX:00584',2,NULL,NULL,NULL,'fire-polished closed-tip poking pipette (2-5.5 µm diameters) on piezo actuator at 35°/45°/70°; 25 ramp-and-hold stimuli, 0.2-µm increments; velocity series 2 -> 0.062 µm/ms (8 µm displacement, halved each step); threshold = probe displacement at -10 pA current crossing | ERROR-AS-REPORTED: 0.28 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.26,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.26','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','heterologous transfection (Neuro2A PIEZO1-knockout, N2A-P1KO)','N2A-P1KO cells transfected with PIEZO2-HA-IRES-GFP (plasmid from Taberner 2019; species not restated in this paper)',NULL,7.4,'4 KCl, 140 NaCl, 1 MgCl2, 2 CaCl2, 4 glucose, 10 HEPES (pH 7.4)','125 potassium gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA (pH 7.3)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00020','For PIEZO2-mediated currents, we also observed a trend toward faster inactivation at higher stimulation angles (35°: τinact = 2.86 ± 0.37 ms, 45°: τinact = 2.21 ± 0.16 ms, 70°: τinact = 2.26 ± 0.28 ms), but no ','Results (Fig. 2i)','high','Constant velocity 1.5 µm/ms, probe tip 3 µm; mean ± SEM; n only on graph.','PIEZO2_N2A-P1KO_whole-cell_poke_-60mV_angle70deg_probe3um_vel1.5um-ms',NULL,'LITERATURE','2026-11-08',29,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(585,'MAIC:BX:00585',2,NULL,NULL,NULL,'fire-polished closed-tip poking pipette (2-5.5 µm diameters) on piezo actuator at 35°/45°/70°; 25 ramp-and-hold stimuli, 0.2-µm increments; velocity series 2 -> 0.062 µm/ms (8 µm displacement, halved each step); threshold = probe displacement at -10 pA current crossing | ERROR-AS-REPORTED: 0.7 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4.71,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.71','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','heterologous transfection (Neuro2A PIEZO1-knockout, N2A-P1KO)','N2A-P1KO cells transfected with PIEZO2-HA-IRES-GFP (plasmid from Taberner 2019; species not restated in this paper)',NULL,7.4,'4 KCl, 140 NaCl, 1 MgCl2, 2 CaCl2, 4 glucose, 10 HEPES (pH 7.4)','125 potassium gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA (pH 7.3)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00021','Likewise, PIEZO2 currents evoked with a 2 µm probe exhibited inactivation time constants of 4.71 ± 0.70 ms, whereas PIEZO2 currents evoked with 3 µm and 5.5 µm probes had inactivation time constants of 2.21 ± 0.16 ms and 2.61 ± 0.40 ms, respectively (Figure 3i','Results (Fig. 3i)','high','Probe-size series at 45°: 2-µm probe slows apparent tau ~2x vs 3/5.5 µm. Mean ± SEM; n only on graph. The Fig-3i tip-size series does not print its angle/velocity in that section — 45° at 1.5 µm/ms is INFERRED from the 2.21±0.16 ms value appearing in both Fig 2i (45°, 3 µm, 1.5 µm/ms) and Fig 3i, plus Fig 4''s stated default protocol (45°, 3 µm). Discussion cautions that poke ''tau_inact'' contains stimulus-adaptation/cell-relaxation contributions, not purely channel inactivation.','PIEZO2_N2A-P1KO_whole-cell_poke_-60mV_angle45deg_probe2um',NULL,'LITERATURE','2026-11-08',29,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(586,'MAIC:BX:00586',2,NULL,NULL,NULL,'fire-polished closed-tip poking pipette (2-5.5 µm diameters) on piezo actuator at 35°/45°/70°; 25 ramp-and-hold stimuli, 0.2-µm increments; velocity series 2 -> 0.062 µm/ms (8 µm displacement, halved each step); threshold = probe displacement at -10 pA current crossing | ERROR-AS-REPORTED: 0.4 (sem)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.61,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.61','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','heterologous transfection (Neuro2A PIEZO1-knockout, N2A-P1KO)','N2A-P1KO cells transfected with PIEZO2-HA-IRES-GFP (plasmid from Taberner 2019; species not restated in this paper)',NULL,7.4,'4 KCl, 140 NaCl, 1 MgCl2, 2 CaCl2, 4 glucose, 10 HEPES (pH 7.4)','125 potassium gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA (pH 7.3)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00022','Likewise, PIEZO2 currents evoked with a 2 µm probe exhibited inactivation time constants of 4.71 ± 0.70 ms, whereas PIEZO2 currents evoked with 3 µm and 5.5 µm probes had inactivation time constants of 2.21 ± 0.16 ms and 2.61 ± 0.40 ms, respectively (Figure 3i','Results (Fig. 3i)','high','Probe-size series at 45°; mean ± SEM; n only on graph. Series angle/velocity not printed in the Fig-3 section — inferred as 45°, 1.5 µm/ms per the first tip-series row (value-bridging argument).','PIEZO2_N2A-P1KO_whole-cell_poke_-60mV_angle45deg_probe5.5um',NULL,'LITERATURE','2026-11-08',29,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(587,'MAIC:BX:00587',2,NULL,NULL,NULL,'fire-polished closed-tip poking pipette (2-5.5 µm diameters) on piezo actuator at 35°/45°/70°; 25 ramp-and-hold stimuli, 0.2-µm increments; velocity series 2 -> 0.062 µm/ms (8 µm displacement, halved each step); threshold = probe displacement at -10 pA current crossing',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2.66,NULL,NULL,NULL,'2.66','ms','INDENTATION',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','heterologous transfection (Neuro2A PIEZO1-knockout, N2A-P1KO)','N2A-P1KO cells transfected with PIEZO2-HA-IRES-GFP (plasmid from Taberner 2019; species not restated in this paper)',NULL,7.4,'4 KCl, 140 NaCl, 1 MgCl2, 2 CaCl2, 4 glucose, 10 HEPES (pH 7.4)','125 potassium gluconate, 7 KCl, 1 CaCl2, 1 MgCl2, 10 HEPES, 4 EGTA (pH 7.3)',-60.0,NULL,NULL,NULL,NULL,NULL,'PIEZO2-EX-00023','The activation kinetics of PIEZO2, but not of PIEZO1, was also dependent on the stimulation tip size, such that the time-to-peak decreased from 2.66 ± 0.19 ms for currents evoked with a 2 µm tip to 2.19 ± 0.10 ms and 1.99 ± 0.11 ms for currents evoked with 3 µm and 5.5 µm tips, r','Results (Fig. 3i)','high','SCHEMA GAP: no DB home for this parameter class (see data/extraction_schema.md schema-gap register). Time-to-peak (current onset to peak) of whole-cell poking currents, not an exponential tau_act — schema_gap macroscopic_rise_time; registered canonical unit is s while as-printed here is ms (×1000-to-ms hazard declared). Mean ± SEM per Statistics section; n only on graph. Tip-size series angle/velocity not printed in the Fig-3 section — inferred 45°, 1.5 µm/ms (see first tip-series row).','PIEZO2_N2A-P1KO_whole-cell_poke_-60mV_angle45deg_probe2um_ttp',NULL,'LITERATURE','2026-11-08',29,'2026-11-08 00:00:00.000000',NULL);
