re data.','hTMC1_HEK293T-Piezo1KO_shUROD_cell-attached_single-channel_-80mV_-50mmHg_Fig5D-E',NULL,'LITERATURE','2026-11-08',147,'2026-11-08 00:00:00.000000',NULL);
