INSERT INTO "biophysics_experiment" VALUES(694,'MAIC:BX:00694',8,NULL,NULL,NULL,'mechanical bundle stimulation at holding potentials from -89 to +111 mV in 20-mV increments (I-V for reversal/permeability)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.71,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.71',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear OHCs P5 on a Tmc1 dn/dn background (TMC2-only channels): Tmie R82C/+ vs Tmie R82C/R82C; TMIE-28-153-HA truncation analyzed separately','mouse cochlear outer hair cell',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00116','(J) Reversal potential (R v ) plots for OHCs calculated from (H,I) (29.37±1.48 mV vs 23.71 ± 2.03 mV, Mean ± SEM, *, p<0.05) (K) Relative Ca 2+ permeability plots calculated using the Goldman-Hodgkin-Katz equation (6.71 ± 0.70 vs 4.69 ± 0.63, Mean ± SEM, *, p<0.05). See also Figs. S4 and S5 .','Fig 7 legend (K; Goldman-Hodgkin-Katz analysis)','medium','as-reported GHK-derived ratio; schema_gap. Tmc1 dn/dn background -> TMC2-only channel. Archived: single-channel CURRENTS (4.32 ± 0.12 pA n = 72 control vs 3.40 ± 0.13 pA n = 50 R82C/R82C) — currents not conductance; single-channel open-time constants (2.08 ms / 1.94 ms) are open-time taus, not MET adaptation; the TMIE-28-153-HA Po-displacement rightward shift is stated without numbers (delta_p50 flag -> no row). Pro-pore paper (TMIE regulates the pore).','mTmc2_OHC_apex_Tmc1-dn_Tmie-R82C-het_GHK_P-Ca-P-Cs_Fig7K',NULL,'LITERATURE','2026-11-08',159,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(695,'MAIC:BX:00695',8,NULL,NULL,NULL,'mechanical bundle stimulation at holding potentials from -89 to +111 mV in 20-mV increments (I-V for reversal/permeability)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4.69,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.69',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear OHCs P5 on a Tmc1 dn/dn background (TMC2-only channels): Tmie R82C/+ vs Tmie R82C/R82C; TMIE-28-153-HA truncation analyzed separately','mouse cochlear outer hair cell',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00117','(J) Reversal potential (R v ) plots for OHCs calculated from (H,I) (29.37±1.48 mV vs 23.71 ± 2.03 mV, Mean ± SEM, *, p<0.05) (K) Relative Ca 2+ permeability plots calculated using the Goldman-Hodgkin-Katz equation (6.71 ± 0.70 vs 4.69 ± 0.63, Mean ± SEM, *, p<0.05). See also Figs. S4 and S5 .','Fig 7 legend (K; Goldman-Hodgkin-Katz analysis)','medium','as-reported GHK-derived ratio; schema_gap. Tmc1 dn/dn background -> TMC2-only channel. Archived: single-channel CURRENTS (4.32 ± 0.12 pA n = 72 control vs 3.40 ± 0.13 pA n = 50 R82C/R82C) — currents not conductance; single-channel open-time constants (2.08 ms / 1.94 ms) are open-time taus, not MET adaptation; the TMIE-28-153-HA Po-displacement rightward shift is stated without numbers (delta_p50 flag -> no row). Pro-pore paper (TMIE regulates the pore).','mTmc2_OHC_apex_Tmc1-dn_Tmie-R82C-homo_GHK_P-Ca-P-Cs_Fig7K',NULL,'LITERATURE','2026-11-08',159,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(696,'MAIC:BX:00696',8,NULL,NULL,NULL,'fluid-jet bundle stimulation; Ca2+ reversal potentials in 100 mM Ca2+ external + Cs+-based internal (GHK analysis)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.1',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear hair cells (wild type): OHCs along the tonotopic axis and IHCs','mouse cochlear outer hair cell (apex / middle / base)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00118','Thus, for OHCs, the mean P Ca /P Cs (± SEM) = 6.1 ± 0.7 ( n = 7) at the apex, 5.2 ± 0.1 ( n = 4) at the middle, and 4.6 ± 0.5 ( n = 12) at the base. The three means were significantly different from each other ( t test; P < 0.02). A concern is that the smaller permeability at the base may be caused by Ca 2+ loading, but the inferred permeability for basal OHCs was unaffected when 3 mM BAPTA was used instead of 1 mM EGTA as the Ca 2+ buffer in the intracellular solution (P Ca /P Cs = 4.2 ± 0.6; n = 9).','Results (OHC P_Ca/P_Cs by cochlear position; Fig 2, C and D; apex)','medium','as-reported ratio (± SEM stated); schema_gap. Small but significant apex-to-base decrease (P < 0.02). . Archived: conductance flag -> the only conductance statement is the intro-cited ''large (>100-pS) unitary conductance'' (disclosure path per the round README) — no original single-channel measurement in this paper; IHC P_Ca/P_Cs ''invariant with position'' (Fig 2 D, no text numerics); Ca2+-loading check with BAPTA rowed below. Mild-skeptic paper (authors raise TMCs-as-chaperones). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1+mTmc2_OHC_apex_1mM-EGTA_WT_Ca-reversal_GHK_P-Ca-P-Cs_Fig2CD','7','LITERATURE','2026-11-08',160,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(697,'MAIC:BX:00697',8,NULL,NULL,NULL,'fluid-jet bundle stimulation; Ca2+ reversal potentials in 100 mM Ca2+ external + Cs+-based internal (GHK analysis)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'5.2',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear hair cells (wild type): OHCs along the tonotopic axis and IHCs','mouse cochlear outer hair cell (apex / middle / base)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00119','Thus, for OHCs, the mean P Ca /P Cs (± SEM) = 6.1 ± 0.7 ( n = 7) at the apex, 5.2 ± 0.1 ( n = 4) at the middle, and 4.6 ± 0.5 ( n = 12) at the base. The three means were significantly different from each other ( t test; P < 0.02). A concern is that the smaller permeability at the base may be caused by Ca 2+ loading, but the inferred permeability for basal OHCs was unaffected when 3 mM BAPTA was used instead of 1 mM EGTA as the Ca 2+ buffer in the intracellular solution (P Ca /P Cs = 4.2 ± 0.6; n = 9).','Results (OHC P_Ca/P_Cs by cochlear position; Fig 2, C and D; middle)','medium','as-reported ratio (± SEM stated); schema_gap. Small but significant apex-to-base decrease (P < 0.02). . Archived: conductance flag -> the only conductance statement is the intro-cited ''large (>100-pS) unitary conductance'' (disclosure path per the round README) — no original single-channel measurement in this paper; IHC P_Ca/P_Cs ''invariant with position'' (Fig 2 D, no text numerics); Ca2+-loading check with BAPTA rowed below. Mild-skeptic paper (authors raise TMCs-as-chaperones). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1+mTmc2_OHC_middle_1mM-EGTA_WT_Ca-reversal_GHK_P-Ca-P-Cs_Fig2CD','4','LITERATURE','2026-11-08',160,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(698,'MAIC:BX:00698',8,NULL,NULL,NULL,'fluid-jet bundle stimulation; Ca2+ reversal potentials in 100 mM Ca2+ external + Cs+-based internal (GHK analysis)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4.6,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.6',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear hair cells (wild type): OHCs along the tonotopic axis and IHCs','mouse cochlear outer hair cell (apex / middle / base)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00120','Thus, for OHCs, the mean P Ca /P Cs (± SEM) = 6.1 ± 0.7 ( n = 7) at the apex, 5.2 ± 0.1 ( n = 4) at the middle, and 4.6 ± 0.5 ( n = 12) at the base. The three means were significantly different from each other ( t test; P < 0.02). A concern is that the smaller permeability at the base may be caused by Ca 2+ loading, but the inferred permeability for basal OHCs was unaffected when 3 mM BAPTA was used instead of 1 mM EGTA as the Ca 2+ buffer in the intracellular solution (P Ca /P Cs = 4.2 ± 0.6; n = 9).','Results (OHC P_Ca/P_Cs by cochlear position; Fig 2, C and D; base)','medium','as-reported ratio (± SEM stated); schema_gap. Small but significant apex-to-base decrease (P < 0.02). standard intracellular solution (1 mM EGTA Ca2+ buffer). Archived: conductance flag -> the only conductance statement is the intro-cited ''large (>100-pS) unitary conductance'' (disclosure path per the round README) — no original single-channel measurement in this paper; IHC P_Ca/P_Cs ''invariant with position'' (Fig 2 D, no text numerics); Ca2+-loading check with BAPTA rowed below. Mild-skeptic paper (authors raise TMCs-as-chaperones). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1+mTmc2_OHC_base_1mM-EGTA_WT_Ca-reversal_GHK_P-Ca-P-Cs_Fig2CD','12','LITERATURE','2026-11-08',160,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(699,'MAIC:BX:00699',8,NULL,NULL,NULL,'fluid-jet bundle stimulation; Ca2+ reversal potentials in 100 mM Ca2+ external + Cs+-based internal (GHK analysis)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.2',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear hair cells (wild type): OHCs along the tonotopic axis and IHCs','mouse cochlear outer hair cell (apex / middle / base)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00121','Thus, for OHCs, the mean P Ca /P Cs (± SEM) = 6.1 ± 0.7 ( n = 7) at the apex, 5.2 ± 0.1 ( n = 4) at the middle, and 4.6 ± 0.5 ( n = 12) at the base. The three means were significantly different from each other ( t test; P < 0.02). A concern is that the smaller permeability at the base may be caused by Ca 2+ loading, but the inferred permeability for basal OHCs was unaffected when 3 mM BAPTA was used instead of 1 mM EGTA as the Ca 2+ buffer in the intracellular solution (P Ca /P Cs = 4.2 ± 0.6; n = 9).','Results (OHC P_Ca/P_Cs by cochlear position; Fig 2, C and D; base (3 mM BAPTA intracellular buffer control))','medium','as-reported ratio (± SEM stated); schema_gap. Small but significant apex-to-base decrease (P < 0.02). Ca2+-loading control: basal permeability unaffected by intracellular 3 mM BAPTA vs 1 mM EGTA — same cochlear position, DIFFERENT intracellular Ca2+ buffer (the two base rows are distinguished by the buffer condition, review fix). Archived: conductance flag -> the only conductance statement is the intro-cited ''large (>100-pS) unitary conductance'' (disclosure path per the round README) — no original single-channel measurement in this paper; IHC P_Ca/P_Cs ''invariant with position'' (Fig 2 D, no text numerics); Ca2+-loading check with BAPTA rowed below. Mild-skeptic paper (authors raise TMCs-as-chaperones). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1+mTmc2_OHC_base_3mM-BAPTA_WT_Ca-reversal_GHK_P-Ca-P-Cs_Fig2CD','9','LITERATURE','2026-11-08',160,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(700,'MAIC:BX:00700',8,NULL,NULL,113,'single-channel events after BAPTA; conductance states weighted to the mean equivalent conductance G = Σ(n_i I_i)/V_H | ERROR-AS-REPORTED: 5','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,95.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'95','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear OHCs: Tmc1 p.D569N/D569N;Tmc2-/- (TMC1-only mutant channel) vs Tmc1 +/+;Tmc2-/- controls; also Tmc2+/+ backgrounds','mouse cochlear outer hair cell (apex / base)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00122','G has a value of 95 ± 5 pS at the apex and 107 ± 6 pS at the base. While these values are different, the gradient is smaller than reported in wild type, where the base conductance is at least twice that at the apex.','Results (single MET channel currents; apex)','medium','DERIVATION DECLARED: weighted mean equivalent conductance over conductance states (G = Σ(n_i I_i)/V_H, formula in the source); the tonotopic gradient is smaller than wild type (''the base conductance is at least twice that at the apex'' in controls — control values cited to ref 13, not rowed). pS native scale. Archived: the headline claim is that conductance is NOT reduced by p.D569N (''no reduction in the MET channel conductance''; the 1/3 reduction in the abstract refers to channel EXPRESSION/number, not conductance); principal unitary CURRENT -7.9 ± 0.3 pA (100 events, 4 OHCs) and conductance states -4.0/-11.0/-14.0 pA are currents; P_Ca/P_Cs values are Fig 4C only (the same comparison quantified and rowed from Goldring 2019, 4.20/2.11/1.24); IHC conductance no reduction. Pro-pore paper.','mTmc1_OHC_apex_D569N-homo_Tmc2-KO_weighted-G_-84mV',NULL,'LITERATURE','2026-11-08',161,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(701,'MAIC:BX:00701',8,NULL,NULL,113,'single-channel events after BAPTA; conductance states weighted to the mean equivalent conductance G = Σ(n_i I_i)/V_H | ERROR-AS-REPORTED: 6','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,107.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'107','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear OHCs: Tmc1 p.D569N/D569N;Tmc2-/- (TMC1-only mutant channel) vs Tmc1 +/+;Tmc2-/- controls; also Tmc2+/+ backgrounds','mouse cochlear outer hair cell (apex / base)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00123','G has a value of 95 ± 5 pS at the apex and 107 ± 6 pS at the base. While these values are different, the gradient is smaller than reported in wild type, where the base conductance is at least twice that at the apex.','Results (single MET channel currents; base)','medium','DERIVATION DECLARED: weighted mean equivalent conductance over conductance states (G = Σ(n_i I_i)/V_H, formula in the source); the tonotopic gradient is smaller than wild type (''the base conductance is at least twice that at the apex'' in controls — control values cited to ref 13, not rowed). pS native scale. Archived: the headline claim is that conductance is NOT reduced by p.D569N (''no reduction in the MET channel conductance''; the 1/3 reduction in the abstract refers to channel EXPRESSION/number, not conductance); principal unitary CURRENT -7.9 ± 0.3 pA (100 events, 4 OHCs) and conductance states -4.0/-11.0/-14.0 pA are currents; P_Ca/P_Cs values are Fig 4C only (the same comparison quantified and rowed from Goldring 2019, 4.20/2.11/1.24); IHC conductance no reduction. Pro-pore paper.','mTmc1_OHC_base_D569N-homo_Tmc2-KO_weighted-G_-84mV',NULL,'LITERATURE','2026-11-08',161,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(702,'MAIC:BX:00702',8,NULL,NULL,NULL,'single-channel events after BAPTA tip-link removal; fluid-jet I-X fits for X_O | ERROR-AS-REPORTED: 3','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,81.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'81','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear apical OHCs on Tmc2-/- backgrounds: Tmc1 +/+;Tmc2-/- controls, Tmc1 p.D528N/D528N, Tmc1 p.E520Q, Tmc1 +/+;Tmie-/-;Tmc2-/- and Tmc1 +/+;Lhfpl5-/-;Tmc2-/-; single channels after BAPTA','mouse cochlear outer hair cell (apex)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00124','Neutralizing a negative aspartate, Tmc1 p.D528N, in TM6 near the external face of the membrane, reduced the channel conductance in apical OHCs from 81 ± 3 pS ( n = 5 cells; Tmc1 +/+ ;Tmc2 -/- ) to 53 ± 3 pS ( n = 5 cells; Tmc1 p.D528N/D528N ;Tmc2 -/- ) ( Fig. 1 A – D ). The smaller conductance was accompanied by a much decreased selectivity for Ca 2+ ions: P Ca / P Cs , (ratio of permeability to Ca 2+ ions relative to Cs + ions) = 4.3 ± 0.4 ( n = 8) in Tmc1 +/+ ;Tmc2 -/- and 0.6 ± 0.04 ( n = 7) in Tmc1 p.D528N/D528N ;Tmc2 -/- ( 4 ).','Results (D528N conductance; Fig 1, A-D)','medium','control (TMC1-only channel). Tmc2-/- background -> TMC1-only channel token. pS native scale. Archived: the critique-reported ''148 ± 90 pS in Tmc1+/- and 102 ± 70 pS'' are ANOTHER GROUP''s values (cited) — not rowed; ~40 pS subconductance state; 10-90% working ranges 125 ± 18 nm (Lhfpl5-/-) vs 70 ± 8 nm (control) are operating ranges, NOT x50; unitary CURRENTS 6.8 ± 0.5 pA (control) and macroscopic 28 ± 6 pA (Lhfpl5-/-). Pro-pore for TMC1 with TMIE also pore-implicated. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1_OHC_apex_Tmc2-KO_control_BAPTA-single-channel_-84mV','5','LITERATURE','2026-11-08',162,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(703,'MAIC:BX:00703',8,NULL,NULL,104,'single-channel events after BAPTA tip-link removal; fluid-jet I-X fits for X_O | ERROR-AS-REPORTED: 3','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,53.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'53','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear apical OHCs on Tmc2-/- backgrounds: Tmc1 +/+;Tmc2-/- controls, Tmc1 p.D528N/D528N, Tmc1 p.E520Q, Tmc1 +/+;Tmie-/-;Tmc2-/- and Tmc1 +/+;Lhfpl5-/-;Tmc2-/-; single channels after BAPTA','mouse cochlear outer hair cell (apex)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00125','Neutralizing a negative aspartate, Tmc1 p.D528N, in TM6 near the external face of the membrane, reduced the channel conductance in apical OHCs from 81 ± 3 pS ( n = 5 cells; Tmc1 +/+ ;Tmc2 -/- ) to 53 ± 3 pS ( n = 5 cells; Tmc1 p.D528N/D528N ;Tmc2 -/- ) ( Fig. 1 A – D ). The smaller conductance was accompanied by a much decreased selectivity for Ca 2+ ions: P Ca / P Cs , (ratio of permeability to Ca 2+ ions relative to Cs + ions) = 4.3 ± 0.4 ( n = 8) in Tmc1 +/+ ;Tmc2 -/- and 0.6 ± 0.04 ( n = 7) in Tmc1 p.D528N/D528N ;Tmc2 -/- ( 4 ).','Results (D528N conductance; Fig 1, A-D)','medium','reduced from 81 ± 3 pS by the TM6 pore-region mutation. Tmc2-/- background -> TMC1-only channel token. pS native scale. Archived: the critique-reported ''148 ± 90 pS in Tmc1+/- and 102 ± 70 pS'' are ANOTHER GROUP''s values (cited) — not rowed; ~40 pS subconductance state; 10-90% working ranges 125 ± 18 nm (Lhfpl5-/-) vs 70 ± 8 nm (control) are operating ranges, NOT x50; unitary CURRENTS 6.8 ± 0.5 pA (control) and macroscopic 28 ± 6 pA (Lhfpl5-/-). Pro-pore for TMC1 with TMIE also pore-implicated. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1_OHC_apex_Tmc2-KO_D528N-homo_BAPTA-single-channel_-84mV','5','LITERATURE','2026-11-08',162,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(704,'MAIC:BX:00704',8,NULL,NULL,114,'single-channel events after BAPTA tip-link removal; fluid-jet I-X fits for X_O | ERROR-AS-REPORTED: 4','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,52.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'52','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear apical OHCs on Tmc2-/- backgrounds: Tmc1 +/+;Tmc2-/- controls, Tmc1 p.D528N/D528N, Tmc1 p.E520Q, Tmc1 +/+;Tmie-/-;Tmc2-/- and Tmc1 +/+;Lhfpl5-/-;Tmc2-/-; single channels after BAPTA','mouse cochlear outer hair cell (apex)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00126','E520Q reduced the channel conductance to 52 ± 4 pS (average of 75 traces in 4 cells)','Results (E520Q conductance; Fig 1)','medium','genotype not restated in this span; the pore-mutant series is on the Tmc2-/- background. Tmc2-/- background -> TMC1-only channel token. pS native scale. Archived: the critique-reported ''148 ± 90 pS in Tmc1+/- and 102 ± 70 pS'' are ANOTHER GROUP''s values (cited) — not rowed; ~40 pS subconductance state; 10-90% working ranges 125 ± 18 nm (Lhfpl5-/-) vs 70 ± 8 nm (control) are operating ranges, NOT x50; unitary CURRENTS 6.8 ± 0.5 pA (control) and macroscopic 28 ± 6 pA (Lhfpl5-/-). Pro-pore for TMC1 with TMIE also pore-implicated.','mTmc1_OHC_apex_Tmc2-KO_E520Q-homo_BAPTA-single-channel_-84mV','4','LITERATURE','2026-11-08',162,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(705,'MAIC:BX:00705',8,NULL,NULL,NULL,'single-channel events after BAPTA tip-link removal; fluid-jet I-X fits for X_O | ERROR-AS-REPORTED: 5','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,63.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'63','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear apical OHCs on Tmc2-/- backgrounds: Tmc1 +/+;Tmc2-/- controls, Tmc1 p.D528N/D528N, Tmc1 p.E520Q, Tmc1 +/+;Tmie-/-;Tmc2-/- and Tmc1 +/+;Lhfpl5-/-;Tmc2-/-; single channels after BAPTA','mouse cochlear outer hair cell (apex)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00127','was obtained from 60 traces in four apical OHCs of Tmc1 +/+ ;Tmie -/- ;Tmc2 -/- , equivalent to a conductance of 63 ± 5 pS; this value is smaller than the control value of 85 ± 3 pS ( t test','Results (TMIE-null conductance; Fig 3)','medium','TMIE-null residual channel, smaller than the 85 ± 3 pS same-location control. Tmc2-/- background -> TMC1-only channel token. pS native scale. Archived: the critique-reported ''148 ± 90 pS in Tmc1+/- and 102 ± 70 pS'' are ANOTHER GROUP''s values (cited) — not rowed; ~40 pS subconductance state; 10-90% working ranges 125 ± 18 nm (Lhfpl5-/-) vs 70 ± 8 nm (control) are operating ranges, NOT x50; unitary CURRENTS 6.8 ± 0.5 pA (control) and macroscopic 28 ± 6 pA (Lhfpl5-/-). Pro-pore for TMC1 with TMIE also pore-implicated. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1_OHC_apex_Tmc2-KO_Tmie-KO_BAPTA-single-channel_-84mV','4','LITERATURE','2026-11-08',162,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(706,'MAIC:BX:00706',8,NULL,NULL,NULL,'single-channel events after BAPTA tip-link removal; fluid-jet I-X fits for X_O | ERROR-AS-REPORTED: 11','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,75.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'75','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear apical OHCs on Tmc2-/- backgrounds: Tmc1 +/+;Tmc2-/- controls, Tmc1 p.D528N/D528N, Tmc1 p.E520Q, Tmc1 +/+;Tmie-/-;Tmc2-/- and Tmc1 +/+;Lhfpl5-/-;Tmc2-/-; single channels after BAPTA','mouse cochlear outer hair cell (apex)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00128','The mean single-channel current was -6.3 ± 0.8 pA ( n = 51 channel events in 2 OHCs) at -84-mV holding potential, equivalent to a conductance 75 ± 11 pS. Control recordings in Tmc1 +/+ ;Lhfpl5 +/+ ;Tmc2 -/- mice made at the same cochlear location ( d = 0.2) gave a unitary current of 6.8 ± 0.5 pA (120 traces in 5 OHCs).','Results (Lhfpl5-null conductance; Fig 5, E-G)','medium','from -6.3 ± 0.8 pA (51 events, 2 OHCs); conductance comparable to wild type despite 30-fold smaller macroscopic currents. Tmc2-/- background -> TMC1-only channel token. pS native scale. Archived: the critique-reported ''148 ± 90 pS in Tmc1+/- and 102 ± 70 pS'' are ANOTHER GROUP''s values (cited) — not rowed; ~40 pS subconductance state; 10-90% working ranges 125 ± 18 nm (Lhfpl5-/-) vs 70 ± 8 nm (control) are operating ranges, NOT x50; unitary CURRENTS 6.8 ± 0.5 pA (control) and macroscopic 28 ± 6 pA (Lhfpl5-/-). Pro-pore for TMC1 with TMIE also pore-implicated.','mTmc1_OHC_apex_Tmc2-KO_Lhfpl5-KO_BAPTA-single-channel_-84mV','2','LITERATURE','2026-11-08',162,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(707,'MAIC:BX:00707',8,NULL,NULL,NULL,'single-channel events after BAPTA tip-link removal; fluid-jet I-X fits for X_O',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.3',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','native mouse cochlear apical OHCs on Tmc2-/- backgrounds: Tmc1 +/+;Tmc2-/- controls, Tmc1 p.D528N/D528N, Tmc1 p.E520Q, Tmc1 +/+;Tmie-/-;Tmc2-/- and Tmc1 +/+;Lhfpl5-/-;Tmc2-/-; single channels after BAPTA','mouse cochlear outer hair cell (apex)',NULL,NULL,NULL,NULL,-84.0,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00129','Neutralizing a negative aspartate, Tmc1 p.D528N, in TM6 near the external face of the membrane, reduced the channel conductance in apical OHCs from 81 ± 3 pS ( n = 5 cells; Tmc1 +/+ ;Tmc2 -/- ) to 53 ± 3 pS ( n = 5 cells; Tmc1 p.D528N/D528N ;Tmc2 -/- ) ( Fig. 1 A – D ). The smaller conductance was accompanied by a much decreased selectivity for Ca 2+ ions: P Ca / P Cs , (ratio of permeability to Ca 2+ ions relative to Cs + ions) = 4.3 ± 0.4 ( n = 8) in Tmc1 +/+ ;Tmc2 -/- and 0.6 ± 0.04 ( n = 7) in Tmc1 p.D528N/D528N ;Tmc2 -/- ( 4 ).','Results (D528N Ca2+ selectivity; Fig 1)','medium','as-reported ratio; schema_gap. D528N collapses Ca2+ selectivity (4.3 -> 0.6), consistent with the pilot''s Beurg 2021 JN values (4.25/0.57). Archived: the critique-reported ''148 ± 90 pS in Tmc1+/- and 102 ± 70 pS'' are ANOTHER GROUP''s values (cited) — not rowed; ~40 pS subconductance state; 10-90% working ranges 125 ± 18 nm (Lhfpl5-/-) vs 70 ± 8 nm (control) are operating ranges, NOT x50; unitary CURRENTS 6.8 ± 0.5 pA (control) and macroscopic 28 ± 6 pA (Lhfpl5-/-). Pro-pore for TMC1 with TMIE also pore-implicated. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','mTmc1_OHC_apex_Tmc2-KO_control_Ca-reversal_GHK_P-Ca-P-Cs','8','LITERATURE','2026-11-08',162,'2026-11-08 00:00:00.000000',NULL);
