INSERT INTO "biophysics_experiment" VALUES(717,'MAIC:BX:00717',8,NULL,NULL,NULL,'mechanical stimulation of membrane patches; single-channel currents (n = 22-31 patches from 22-29 cells); I-V with Na-, Cs- or Ca-based pipette solutions','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-7.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-7.1','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','PIEZO1-knockout HEK293T (PK-HEK293T) cells expressing Fyn-tagged mouse TMC1 or TMC2 (-mCherry), co-expressed with mTMIE; heterologous with TMIE co-expression (NOT an only-TMC system)','HEK293T (Piezo1 knockout)',NULL,NULL,'150 NaCl / 144 CsCl / 100 CaCl2 pipette-solution variants (10 HEPES, pH 7.3) for the permeability series',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TMC-EX-00139','Measured reversal potentials were -7.1 mV (Fyn-mTMC2-mCherry) for Cs in the pipette, and +6.6 mV (Fyn-mTMC1-mCherry) or +9.8 mV (Fyn-mTMC2-mCherry) for Ca in the pipette. These values were used to calculate relative Na/Cs/Ca permeability after adjusting for junction potentials, as detailed in the Materials and Methods section','Fig 6 C legend (measured reversal potentials)','medium','absolute single-channel E_rev, junction-potential adjusted (''used to calculate relative Na/Cs/Ca permeability''); Na-pipette value in the same legend is the normalization reference. Gene split by condition_key. Archived: the ''multiples of 18/24/12 pS'' common-divisor statement (covered by the rowed means); DHS (0.2 mM) and NMDG effects qualitative. Pro-pore.','mTmc2_PK-HEK293T_Fyn-tag_single-channel-I-V_144CsCl_Fig6C',NULL,'LITERATURE','2026-11-08',164,'2026-11-08 00:00:00.000000',NULL);
