INSERT INTO "biophysics_experiment" VALUES(915,'MAIC:BX:00915',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.0,'fold',NULL,NULL,NULL,NULL,'3.0','fold','POSITIVE_PRESSURE',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'in vivo (mouse, KO vs WT)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00033','Trpv4 knockout elevates the in-vivo pressure threshold ~3-fold','Results (KO threshold shift)','low','paper states ~3-fold elevation (RR 120->350 mmHg); fold-change is NOT a pressure unit -> schema_gap (delta_p50_* DB column is pressure-only). Absolute thresholds captured as p50 rows (EX-00029..32). SR shift (92->210 mmHg) has no single reported shift number -> not emitted as a delta row (endpoints in p50 rows). In-vivo behavioral, not single-channel','in-vivo, rapid-response afferent, Trpv4-/- vs +/+',NULL,'LITERATURE','2026-11-08',39,'2026-11-08 00:00:00.000000',NULL);
