INSERT INTO "biophysics_experiment" VALUES(917,'MAIC:BX:00917',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','CHO (TRPV4)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00035','the current encoded by TRPV4 was outwardly rectified, selective for cation (Cs:Na:NMDG:Ca:Cl = 1:1.1:0.01:9:0.01)','Results (current characterization)','low','iv_relation NAME (cited from ref 8). NOTE: ''conductance of these nerves was 15 and 14 m/s'' = NERVE CONDUCTION VELOCITY, not single-channel pS -> not a conductance row','CHO whole-cell (TRPV4); cited',NULL,'LITERATURE','2026-11-08',39,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(918,'MAIC:BX:00918',3,NULL,NULL,NULL,'190 mOsm hypotonic solution (HTS) / GSK101 | STIMULUS: 190.0 mOsm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,61300.0,NULL,NULL,NULL,'61.3','s','HYPOTONIC',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','mouse Muller glia (primary)','retinal Muller glia',21.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00039','the swelling-evoked current reached its maximum at 202.5 +/- 32.2 s in Aqp4-/- compared with 61.3 +/- 22.4 s in WT cells (p < 0.01).','Results (current kinetics)','low','MACROSCOPIC WHOLE-CELL RISE TIME (time-to-peak) in SECONDS, NOT an exponential tau_act in ms -> schema_gap, NO DB home. Do NOT load into tau_act_ms (1000x unit hazard). Whole-cell pA currents, not single-channel; indirect (swelling) activation.','whole-cell, mouse Muller glia (WT), 190 mOsm HTS, RT',NULL,'LITERATURE','2026-11-08',40,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(919,'MAIC:BX:00919',3,NULL,NULL,NULL,'190 mOsm hypotonic solution (HTS) | STIMULUS: 190.0 mOsm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,202500.0,NULL,NULL,NULL,'202.5','s','HYPOTONIC',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','mouse Muller glia (Aqp4-/-, primary)','retinal Muller glia (Aqp4-KO)',21.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00040','the swelling-evoked current reached its maximum at 202.5 +/- 32.2 s in Aqp4-/- compared with 61.3 +/- 22.4 s in WT cells (p < 0.01).','Results (current kinetics)','low','MACROSCOPIC WHOLE-CELL RISE TIME (time-to-peak) in SECONDS, NOT an exponential tau_act in ms -> schema_gap, NO DB home. Do NOT load into tau_act_ms (1000x unit hazard). Aqp4-/- genotype; whole-cell, indirect (swelling) activation.','whole-cell, mouse Muller glia (Aqp4-/-), 190 mOsm HTS, RT',NULL,'LITERATURE','2026-11-08',40,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(920,'MAIC:BX:00920',3,NULL,NULL,NULL,'GSK101 (chemical agonist); symmetric 150 mM KCl | MODULATOR: GSK1016790A (agonist) | ERROR-AS-REPORTED: 22.0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,252.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'252.0','pS','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','Xenopus tropicalis TRPV4 (recombinant)',NULL,NULL,NULL,'150 mM KCl (symmetric)','150 mM KCl (symmetric)',-30.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00041','Wild type Xenopus TRPV4 has a unitary conductance of 252 +/- 22 pS at -30 mV membrane in symmetric 150 mM KCl, while TRPV4cryst has a conductance of 264 +/- 19 pS.','Results (single-channel / Fig)','medium','unitary conductance WT (Xenopus tropicalis TRPV4); access_basis=abstract (full text not in PMC); single ion-binding site explains nonselectivity (qualitative). Structure_function: VSLD-pore packing interface (qualitative)','inside-out, Xenopus TRPV4 WT, -30 mV, symmetric 150 mM KCl, GSK101',NULL,'LITERATURE','2026-11-08',41,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(921,'MAIC:BX:00921',3,NULL,NULL,NULL,'MODULATOR: GSK1016790A (agonist) | ERROR-AS-REPORTED: 19.0','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,264.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'264.0','pS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'INSIDE_OUT','Xenopus tropicalis TRPV4cryst (crystallization construct)',NULL,NULL,NULL,'150 mM KCl (symmetric)','150 mM KCl (symmetric)',-30.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00042','Wild type Xenopus TRPV4 has a unitary conductance of 252 +/- 22 pS at -30 mV membrane in symmetric 150 mM KCl, while TRPV4cryst has a conductance of 264 +/- 19 pS.','Results (single-channel / Fig)','medium','unitary conductance of the crystallization construct TRPV4cryst (quantified variant effect vs WT 252 pS); construct label (NOT HGVS) -> variant_hgvs_short left blank','inside-out, Xenopus TRPV4cryst, -30 mV, symmetric 150 mM KCl',NULL,'LITERATURE','2026-11-08',41,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(922,'MAIC:BX:00922',3,NULL,NULL,NULL,'voltage ramp -100 to +100 mV | ERROR-AS-REPORTED: 2.2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-15.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-15.1','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','primary rat hippocampal astrocytes (slice + culture)','hippocampal CA1 astrocyte',28.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00043','Exposure to 4alpha-PDD shifted the reversal potential from -15.1+/-2.2 mV to -5.9+/-1.7 mV (deltaErev = 9.1+/-1.7 mV, n = 13).','Results (E_rev shift)','medium','control E_rev (pre-4α-PDD); macroscopic whole-cell (not single-channel) -> covers ion_selectivity Y-flag. DeltaErev=9.1+/-1.7 mV noted [supplemental_verified]','whole-cell, adult rat hippocampal CA1 astrocytes, pre-4α-PDD/control, 28+/-2 C','13','LITERATURE','2026-11-08',42,'2026-11-08 00:00:00.000000',NULL);
