INSERT INTO "biophysics_experiment" VALUES(924,'MAIC:BX:00924',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6.0',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'primary mouse RGCs','retinal ganglion cell',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00045','transduces osmotic pressure, shear force stimuli, mechanical stretch, and moderate warmth (~27-37 C) into cation influx with a preference for Ca2+ (PCa/PNa ~6).','Introduction/Results (cited)','low','CITED background value (Liedtke/Guler/O''Neil), NOT an original measurement (downgraded); readout is Ca2+ imaging + multielectrode array, no patch-clamp of TRPV4; schema_gap [supplemental_verified]','mouse retinal ganglion cells (Ca2+ imaging + MEA); cited value',NULL,'LITERATURE','2026-11-08',43,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(925,'MAIC:BX:00925',3,NULL,NULL,NULL,'1-s voltage step from -80 mV hold to +60 mV test (activation) | ERROR-AS-REPORTED: 14.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,20.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'20.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00050','The composite activation time constants were similar, being 20 ± 14 ms (weighted avg. ± std, n = 10 oocytes) for untreated wild-type, 21 ± 8 ms (n = 10) for wild-type channels pretreated with 4αPDD, 23 ± 14 ms (n = 10) for M713I and 23 ± 19 ms (n = 10) for L619P.','Results (Activation and deactivation kinetics)','medium','voltage-step activation tau (composite of two exponentials), oocyte TEVC ensemble current; reflects voltage-dependent gating, not mechano-activation. Recording temperature not stated.','TEVC, Xenopus oocyte, rat TRPV4 WT, -80 to +60 mV voltage step, untreated','10','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(926,'MAIC:BX:00926',3,NULL,NULL,NULL,'1-s voltage step from -80 mV hold to +60 mV test (activation); 3 uM 4α-PDD | MODULATOR: 4α-PDD (agonist) 3 uM | ERROR-AS-REPORTED: 8.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,21.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'21.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00051','The composite activation time constants were similar, being 20 ± 14 ms (weighted avg. ± std, n = 10 oocytes) for untreated wild-type, 21 ± 8 ms (n = 10) for wild-type channels pretreated with 4αPDD, 23 ± 14 ms (n = 10) for M713I and 23 ± 19 ms (n = 10) for L619P.','Results (Activation and deactivation kinetics)','medium','voltage-step activation tau, 4α-PDD-pretreated WT. Recording temperature not stated.','TEVC, Xenopus oocyte, rat TRPV4 WT, -80 to +60 mV voltage step, +3 uM 4α-PDD','10','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(927,'MAIC:BX:00927',3,NULL,NULL,130,'1-s voltage step from -80 mV hold to +60 mV test (activation) | ERROR-AS-REPORTED: 14.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'23.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00052','The composite activation time constants were similar, being 20 ± 14 ms (weighted avg. ± std, n = 10 oocytes) for untreated wild-type, 21 ± 8 ms (n = 10) for wild-type channels pretreated with 4αPDD, 23 ± 14 ms (n = 10) for M713I and 23 ± 19 ms (n = 10) for L619P.','Results (Activation and deactivation kinetics)','medium','M713I is a yeast-screen gain-of-function allele at the S6 bundle crossing, not a disease variant. Recording temperature not stated.','TEVC, Xenopus oocyte, rat TRPV4 M713I (GOF), -80 to +60 mV voltage step','10','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(928,'MAIC:BX:00928',3,NULL,NULL,131,'1-s voltage step from -80 mV hold to +60 mV test (activation) | ERROR-AS-REPORTED: 19.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,23.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'23.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,-80.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00053','The composite activation time constants were similar, being 20 ± 14 ms (weighted avg. ± std, n = 10 oocytes) for untreated wild-type, 21 ± 8 ms (n = 10) for wild-type channels pretreated with 4αPDD, 23 ± 14 ms (n = 10) for M713I and 23 ± 19 ms (n = 10) for L619P.','Results (Activation and deactivation kinetics)','medium','L619P is a yeast-screen gain-of-function S5-kink allele, not a disease variant. Recording temperature not stated.','TEVC, Xenopus oocyte, rat TRPV4 L619P (GOF), -80 to +60 mV voltage step','10','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(929,'MAIC:BX:00929',3,NULL,NULL,NULL,'voltage return from +60 mV to -80 mV (deactivation) | ERROR-AS-REPORTED: 60.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,230.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'230.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,60.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00054','Conglomerate deactivation rates from +60 to -80 mV were however distinct, being 230 ± 60 ms (n = 16) for wild-type, 730 ± 260 ms (n = 12) for 4αPDD-treated wild-type, 850 ± 210 ms (n = 8) for M713I, 802 ± 316 ms (n = 21) for L619P-expressing oocytes. The majority of the increase in the wild-type rate was due to the appearance of a fast decay (65 ± 17 ms) of about half the current [...]','Results (Activation and deactivation kinetics)','medium','voltage-step deactivation tau (conglomerate); WT also shows a fast component of 65 +/- 17 ms (~half the current). oocyte TEVC ensemble; temperature not stated. [F-004:truncation-marked] editorial omission marker ''[...]'' in quote (single span, self-disclosed; classified 2026-08-31)','TEVC, Xenopus oocyte, rat TRPV4 WT, +60 to -80 mV voltage return (deactivation), untreated','16','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(930,'MAIC:BX:00930',3,NULL,NULL,NULL,'voltage return from +60 mV to -80 mV (deactivation); 3 uM 4α-PDD | MODULATOR: 4α-PDD (agonist) 3 uM | ERROR-AS-REPORTED: 260.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,730.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'730.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,60.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00055','Conglomerate deactivation rates from +60 to -80 mV were however distinct, being 230 ± 60 ms (n = 16) for wild-type, 730 ± 260 ms (n = 12) for 4αPDD-treated wild-type, 850 ± 210 ms (n = 8) for M713I, 802 ± 316 ms (n = 21) for L619P-expressing oocytes. The majority of the increase in the wild-type rate was due to the appearance of a fast decay (65 ± 17 ms) of about half the current [...]','Results (Activation and deactivation kinetics)','medium','4α-PDD-treated WT deactivation tau (conglomerate). Temperature not stated. [F-004:truncation-marked] editorial omission marker ''[...]'' in quote (single span, self-disclosed; classified 2026-08-31)','TEVC, Xenopus oocyte, rat TRPV4 WT, +60 to -80 mV voltage return (deactivation), +3 uM 4α-PDD','12','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(931,'MAIC:BX:00931',3,NULL,NULL,130,'voltage return from +60 mV to -80 mV (deactivation) | ERROR-AS-REPORTED: 210.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,850.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'850.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,60.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00056','Conglomerate deactivation rates from +60 to -80 mV were however distinct, being 230 ± 60 ms (n = 16) for wild-type, 730 ± 260 ms (n = 12) for 4αPDD-treated wild-type, 850 ± 210 ms (n = 8) for M713I, 802 ± 316 ms (n = 21) for L619P-expressing oocytes. The majority of the increase in the wild-type rate was due to the appearance of a fast decay (65 ± 17 ms) of about half the current [...]','Results (Activation and deactivation kinetics)','medium','M713I GOF deactivation tau (conglomerate); markedly slower than WT, consistent with destabilized closed intracellular gate. Temperature not stated. [F-004:truncation-marked] editorial omission marker ''[...]'' in quote (single span, self-disclosed; classified 2026-08-31)','TEVC, Xenopus oocyte, rat TRPV4 M713I (GOF), +60 to -80 mV voltage return (deactivation)','8','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(932,'MAIC:BX:00932',3,NULL,NULL,131,'voltage return from +60 mV to -80 mV (deactivation) | ERROR-AS-REPORTED: 316.0 (sd)','KINETICS_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,802.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'802.0','ms',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte (rTRPV4)',NULL,NULL,7.2,'66 mM KCl, 100 mM sorbitol, 1.8 mM BaCl2, 5 mM K+-HEPES',NULL,60.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00057','Conglomerate deactivation rates from +60 to -80 mV were however distinct, being 230 ± 60 ms (n = 16) for wild-type, 730 ± 260 ms (n = 12) for 4αPDD-treated wild-type, 850 ± 210 ms (n = 8) for M713I, 802 ± 316 ms (n = 21) for L619P-expressing oocytes. The majority of the increase in the wild-type rate was due to the appearance of a fast decay (65 ± 17 ms) of about half the current [...]','Results (Activation and deactivation kinetics)','medium','L619P GOF deactivation tau (conglomerate); markedly slower than WT. Temperature not stated. [F-004:truncation-marked] editorial omission marker ''[...]'' in quote (single span, self-disclosed; classified 2026-08-31)','TEVC, Xenopus oocyte, rat TRPV4 L619P (GOF), +60 to -80 mV voltage return (deactivation)','21','LITERATURE','2026-11-08',45,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(933,'MAIC:BX:00933',3,NULL,NULL,NULL,'250-ms depolarization from -30 mV to +40 mV every 20 s (Fig.2 time-series); 100 nM GSK101 (full agonist) | MODULATOR: GSK1016790A (agonist) 100 nM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,83.2,'fold',NULL,NULL,NULL,NULL,'83.2','fold',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte',NULL,NULL,NULL,NULL,NULL,-30.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00058','Increases in current (50- to 100-fold) are observed routinely (83.2 ± 31.2-fold, n = 6) (Fig. 2).','Results (L596P and W733R Channels Have Higher Basal Po)','high','GSK101-induced fold-increase of macroscopic current (basal->maximal); inversely proportional to basal Po; WT reference value for L596P/W733R GOF comparison. NOT a pressure/threshold shift — parameter_kind=threshold_fold_shift used as the schema-gap container for this basal-Po GOF metric. Temperature not explicitly stated for TEVC; left blank.','TEVC, Xenopus oocyte, rat TRPV4 WT, -30 mV hold, +40 mV test pulse (250-ms every 20 s),100 nM GSK101','6','LITERATURE','2026-11-08',46,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(934,'MAIC:BX:00934',3,NULL,NULL,132,'250-ms depolarization from -30 mV to +40 mV every 20 s (Fig.2 time-series); 100 nM GSK101; 1 ng cRNA injection (mutant is toxic at higher amounts) | MODULATOR: GSK1016790A (agonist) 100 nM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7.2,'fold',NULL,NULL,NULL,NULL,'7.2','fold',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte',NULL,NULL,NULL,NULL,NULL,-30.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00059','GSK caused an increase of less than 10-fold in the L596P channel current (7.2 ± 2.0-fold, n = 7)','Results (L596P and W733R Channels Have Higher Basal Po)','high','GSK101-induced fold-increase of macroscopic current for the L596P human skeletal-dysplasia allele; reduced fold vs WT (83.2) reflects raised basal Po (GOF). NOT a pressure/threshold shift — schema-gap basal-Po GOF metric.','TEVC, Xenopus oocyte, rat TRPV4 L596P, -30 mV hold, +40 mV test pulse (250-ms every 20 s),100 nM GSK101','7','LITERATURE','2026-11-08',46,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(935,'MAIC:BX:00935',3,NULL,NULL,133,'250-ms depolarization from -30 mV to +40 mV every 20 s (Fig.2 time-series); 100 nM GSK101; 0.1 ng cRNA injection (mutant is strongly toxic) | MODULATOR: GSK1016790A (agonist) 100 nM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1.1,'fold',NULL,NULL,NULL,NULL,'1.1','fold',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte',NULL,NULL,NULL,NULL,NULL,-30.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00060','an approximately doubled increase in the W733R channel (1.1 ± 0.2-fold, n = 4) because of the increased basal activities (raised floor)','Results (L596P and W733R Channels Have Higher Basal Po)','high','GSK101-induced fold-increase for W733R (TRP box invariant-W mutated); near-saturated basal Po (fold ~1) indicates near-complete loss of closed-state stabilization. NOT a pressure/threshold shift — schema-gap basal-Po GOF metric. Temperature not explicitly stated; left blank.','TEVC, Xenopus oocyte, rat TRPV4 W733R, -30 mV hold, +40 mV test pulse (250-ms every 20 s),100 nM GSK101','4','LITERATURE','2026-11-08',46,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(936,'MAIC:BX:00936',3,NULL,NULL,NULL,'Hypotonic stimulation (HTS) by mannitol dilution; baseline 300 mOsm; % HTS = percent reduction',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,34.15,'% HTS','34.15','% HTS','HYPOTONIC',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mouse Müller glia',25.0,7.4,'Ringer''s (mm): 133 NaCl, 2.5 KCl, 1.5 NaH2PO4, 1.5 MgCl2, 2 CaCl2, 10 glucose, 10 HEPES hemisodium, 1 pyruvic acid, 1 lactic acid, 0.5 l-glutamine, 0.5 glutathione, 0.3 Na-ascorbate; pH 7.4, 300 mOsm; mannitol-adjusted',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00061','Müller cell swelling was associated with increases in [Ca2+]i with an EC50 of 34.15 ± 3.31% HTS (Fig. 6 C, D).','Results (Differential TRPV4 channel activation mediates neuronal and glial responses to swelling)','medium','EC50 of hypotonicity (% HTS) for Ca2+ response in native mouse Müller glia — an indirect / swelling-cell threshold, not a direct pressure-clamp threshold; confidence=medium per brief rule 3 (indirect / swollen-cell thresholds → low/medium). Error is 95% confidence band of sigmoidal fit (error_type=ci95). n not explicitly stated for this EC50 (Fig. 6D legend: n=13-20); left blank.','Acutely dissociated mouse Müller glia, fura-5F ratiometric Ca2+ imaging, HTS (mannitol-adjusted, 300 mOsm baseline), 25°C',NULL,'LITERATURE','2026-11-08',47,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(937,'MAIC:BX:00937',3,NULL,NULL,NULL,'25 nM GSK101 (TRPV4 agonist) perfusion; peak time measured from stimulus onset | MODULATOR: GSK1016790A (agonist) 25 nM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,236900.0,NULL,NULL,NULL,'236.9','s','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mouse Müller glia',25.0,7.4,'Ringer''s as above (300 mOsm, pH 7.4)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00062','time-to-peak [Ca2+]i elevations (236.9 ± 17.7 s vs 93.0 ± 4.4 s; p < 0.0001, two-way ANOVA).','Results (The kinetics of TRPV4 activation differ in neurons and glia)','medium','Macroscopic Ca2+-signal rise time (time-to-peak) in native Müller glia — not a single-channel tau_act; represents cell-level TRPV4 activation kinetics via Ca2+ imaging (PLA2/CYP450-dependent, slow onset). schema_gap parameter. Unit is s (NOT ms — avoid 1000x trap). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','Acutely dissociated mouse Müller glia, fura-5F Ca2+ imaging, 25 nM GSK101, 25°C','21','LITERATURE','2026-11-08',47,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(938,'MAIC:BX:00938',3,NULL,NULL,NULL,'25 nM GSK101 perfusion; peak time from stimulus onset | MODULATOR: GSK1016790A (agonist) 25 nM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,93000.0,NULL,NULL,NULL,'93.0','s','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mouse RGC',25.0,7.4,'Ringer''s as above (300 mOsm, pH 7.4)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00063','time-to-peak [Ca2+]i elevations (236.9 ± 17.7 s vs 93.0 ± 4.4 s; p < 0.0001, two-way ANOVA).','Results (The kinetics of TRPV4 activation differ in neurons and glia)','medium','Macroscopic Ca2+ rise time in native RGCs (PLA2-independent, fast onset). schema_gap parameter. Unit s. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','Acutely dissociated mouse retinal ganglion cells (RGCs, Thy1:CFP+), fura-5F Ca2+ imaging, 25 nM GSK101, 25°C','24','LITERATURE','2026-11-08',47,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(939,'MAIC:BX:00939',3,NULL,NULL,NULL,'25 nM GSK101; inactivation tau from post-peak Ca2+ decay | MODULATOR: GSK1016790A (agonist) 25 nM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,346200.0,NULL,NULL,NULL,'346.2','s','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mouse Müller glia',25.0,7.4,'Ringer''s as above',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00064','The time constant of inactivation following the peak was larger in Müller glia than RGCs (τ = 346.2 ± 31.6 s vs 123.0 ± 12.3 s; p < 0.0001; Fig. 4F).','Results (The kinetics of TRPV4 activation differ in neurons and glia)','medium','Ca2+-signal decay tau in native Müller glia (cell-level inactivation, sustained). Although stored in tau_inact_ms schema column, value is in s — DB ingest must convert (×1000) or note unit mismatch. Not a single-channel voltage-step tau. [auto-recategorized: second-scale tau -> macroscopic_rise_time (schema_gap) to avoid ms/s 1000x hazard]. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','Acutely dissociated mouse Müller glia, fura-5F Ca2+ imaging, 25 nM GSK101, 25°C','20','LITERATURE','2026-11-08',47,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(940,'MAIC:BX:00940',3,NULL,NULL,NULL,'25 nM GSK101; inactivation tau from post-peak Ca2+ decay | MODULATOR: GSK1016790A (agonist) 25 nM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,123000.0,NULL,NULL,NULL,'123.0','s','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mouse RGC',25.0,7.4,'Ringer''s as above',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00065','The time constant of inactivation following the peak was larger in Müller glia than RGCs (τ = 346.2 ± 31.6 s vs 123.0 ± 12.3 s; p < 0.0001; Fig. 4F).','Results (The kinetics of TRPV4 activation differ in neurons and glia)','medium','Ca2+-signal decay tau in native RGCs (fast inactivation). Unit s — DB ingest conversion note as above. [auto-recategorized: second-scale tau -> macroscopic_rise_time (schema_gap) to avoid ms/s 1000x hazard]. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','Acutely dissociated mouse RGCs, fura-5F Ca2+ imaging, 25 nM GSK101, 25°C','20','LITERATURE','2026-11-08',47,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(941,'MAIC:BX:00941',3,NULL,NULL,NULL,'25 nM GSK101 perfusion; voltage ramp for I-V; CsCl/TEA bath to block K+ currents | MODULATOR: GSK1016790A (agonist) 25 nM | ERROR-AS-REPORTED: 5.5 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-4.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-4.5','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'mouse Müller glia',25.0,7.2,'Ames'' medium + 5 mM CsCl + 10 mM TEA','(mM) 125 Cs gluconate, 10 TEACl, 10 HEPES, 3 EGTA, 1 ATP, 0.5 GTP, 3 MgCl2, 1 CaCl2, pH 7.2',-70.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00066','showing a current–voltage relation typical of nonselective cation channels with a reversal at -4.5 ± 5.5 mV (Fig. 2 E, F).','Results (TRPV4 agonists induce sustained elevations in Müller cell [Ca2+]i)','high','Reversal potential of GSK101-induced ITRPV4 in native Müller glia; near 0 mV consistent with nonselective cation channel. IV relation lacks the outward rectification typical of homomeric TRPV4 (linearized, possible auxiliary subunits).','Mouse Müller glia, whole-cell patch clamp, -70 mV hold, voltage ramp, 25 nM GSK101, 25°C','10','LITERATURE','2026-11-08',47,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(942,'MAIC:BX:00942',3,NULL,NULL,NULL,'200-ms steps from -20 mV to test potentials +50 to -130 mV (15 mV increments); tonic current read at -85 mV; 50 μM MβCD 45 min to deplete endogenous cholesterol | STIMULUS: -85 mV | MODULATOR: m-beta-cyclodextrin (MβCD) 50 μM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10.0,'fold',NULL,NULL,NULL,NULL,'10','fold',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TEVC','Xenopus oocyte',NULL,23.0,7.4,'(mM) 50 NaCl, 2 KCl, 1 MgCl2, 1 CaCl2, 10 HEPES, 100 mannitol, Tris pH 7.4, 220 mOsm',NULL,-20.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00068','those of the TRPV4-expressing oocytes were enhanced approximately 10-fold (from 156 ± 42 to 1,466 ± 475 nA, N = 9, P = 0.014) by cholesterol depletion','Results (MβCD potentiates TRPV4 current in heterologously expressing oocytes)','high','Modulator-induced fold-shift of tonic TRPV4 current by cholesterol depletion (a structure-function / lipid-regulation metric, NOT a pressure-threshold shift). parameter_kind=threshold_fold_shift used as the schema-gap container for this modulator effect on channel activity. No error on the ~10-fold ratio (error_type=none); underlying nA values have SEM (156 ± 42; 1466 ± 475). Uninjected controls unaffected by MβCD.','TEVC, Xenopus oocyte, rat TRPV4 WT, 50 μM MβCD (45 min), 23°C, -20 mV hold, test pulses +50 to -130 mV','9','LITERATURE','2026-11-08',48,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(943,'MAIC:BX:00943',3,NULL,NULL,NULL,'60 min MβCD (10 mM) incubation to deplete membrane cholesterol; TRPV4-ir puncta counted per cell area vs control | MODULATOR: m-beta-cyclodextrin (MβCD) 10 mM',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4.49,'fold',NULL,NULL,NULL,NULL,'4.49','fold',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'primary human TM cell',37.0,NULL,'Trabecular meshwork cell medium (TMCM; ScienCell 6591)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00069','One-hour incubation with MβCD produced a 4.49 ± 1.07-fold increase in the number of TRPV4-ir (immunoreactivity [ir]) puncta (N = 3; P < 0.05) (Fig. 7 A, B, D).','Results (Membrane cholesterol regulates TRPV4 expression)','high','Modulator-induced fold-shift of TRPV4 membrane puncta density (trafficking/expression metric), NOT a pressure-threshold shift — schema-gap threshold_fold_shift container. Reflects cholesterol-dependent trafficking/retrieval of TRPV4. Abrogated by MβCD:cholesterol (1:10) supplementation (0.73 ± 0.28-fold, not extracted separately). n=3 (independent experiments). [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','Primary human trabecular meshwork (TM) cells, immunofluorescence (TRPV4 antibody), 10 mM MβCD 60 min','3','LITERATURE','2026-11-08',48,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(944,'MAIC:BX:00944',3,NULL,NULL,NULL,'Positive and negative pressure steps (10-63 mmHg, 200-3000 ms) applied via recording pipette to the intracellular side after whole-cell breakthrough | STIMULUS: 10-63 mmHg','P50',18.0,'mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'18','mmHg','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'primate retinal bipolar cell (BC)',24.0,7.2,'oxygenated Ames medium, pH 7.3','118 mM Cs gluconate, 10 CsCl, 10 mM EGTA, 0.5 mM CaCl2, 1 mM MgCl2, 4 mM ATP, 0.3 mM GTP, 10 mM HEPES, pH 7.2 with CsOH; ECl = -61 mV',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00072','The mean pressure to evoke the half-maximal response was ~18 mmHg (range: 10–23 mmHg).','Results (The pressure and temperature sensitivity of bipolar cells), Fig. 6f','medium','Whole-cell macroscopic current p50 from native TRPV4-containing cation conductance in primate retinal BC, NOT single-channel p50. n=4 cells for the pressure-response curve fit (Fig. 6f). τ=34 mmHg reported in the same sentence is the exponential CDF time constant of the pressure-response curve (in pressure units, not time) and is NOT tau_act. Recording temperature for the p50 measurement not explicitly stated; BC experiments were performed at baseline bath temperature then heated (24->30 C) for the thermal sensitivity test; pressure-response curve is the unheated condition. Reversal near -10 mV is consistent with a non-selective cation channel (close to EC for these internal/external solutions).','WHOLE_CELL voltage-clamp, primate (macaque/baboon) retinal slice bipolar cell, native TRPV4, Cs+-based internal (K+ channels blocked), positive/negative pressure steps 10-63 mmHg via patch pipette, pressure-response curve fit with exponential CDF','4','LITERATURE','2026-11-08',50,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(945,'MAIC:BX:00945',3,NULL,NULL,NULL,'Pressure steps at multiple holding potentials (-80, 0, +50 mV); positive pressure onset activates cation conductance, offset reduces it; negative pressure gives opposite polarity same reversal | STIMULUS: 42 mmHg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-10.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-10','mV','PRESSURE_CLAMP',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'primate retinal bipolar cell (BC)',24.0,7.2,'oxygenated Ames medium, pH 7.3','Cs+-based internal (K+ replaced by Cs+ to block K+ channels), 10 mM EGTA, 10 mM HEPES, pH 7.2; ECl = -61 mV',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00073','Positive pressure applied to the intracellular side activated a cation conductance which reversed at ~ -10 mV, and releasing the pressure reduced the cation conductance.','Results (The pressure and temperature sensitivity of bipolar cells), Fig. 6b/c','medium','Reversal potential of native cation current attributed to TRPV4 in primate retinal BC; whole-cell macroscopic recording (not single-channel). Not a P_Ca/P_Na ratio (ion_selectivity=N).','WHOLE_CELL voltage-clamp, primate retinal slice bipolar cell, native TRPV4, Cs+ internal, pressure steps applied via pipette; reversal measured from I-V at Vh = -80, 0, +50 mV',NULL,'LITERATURE','2026-11-08',50,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(946,'MAIC:BX:00946',3,NULL,NULL,NULL,'voltage ramp -100 to +100 mV over 1 s at 0.2 Hz | MODULATOR: GSK1016790A (agonist) 3 nM | ERROR-AS-REPORTED: 7.1 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'9.9','mV',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','HrMVEC (human retinal microvascular endothelial cells, endogenous)','retinal microvascular endothelial cell',23.0,7.4,'150 NaCl, 3 KCl, 1 MgCl2, 2 CaCl2, 10 HEPES, 5.5 d-glucose, pH 7.4 (NaOH)','125 potassium gluconate, 10 KCl, 1 MgCl2, 4 Mg-ATP, 0.6 Na-GTP, 5 BAPTA (caesium salt), 10 HEPES, pH 7.3 (KOH)',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00074','When the membrane potential was ramped between ±100 mV, the GSK101‐dependent conductance exhibited modest outward rectification, reversal potential of 9.9 ± 7.1 mV (number of the animals used (n) = 10) and inhibition by HC‐06','Results (TRPV4 is functionally expressed in human MVECs)','medium','n=10 labelled in paper as ''number of the animals used'' but is most likely cells (patch-clamp); whole-cell macroscopic ramp reversal potential, not single-channel.','WHOLE_CELL, HrMVEC, hTRPV4 endogenous, GSK101 (3 nM), voltage ramp -100 to +100 mV, room temp','10','LITERATURE','2026-11-08',51,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(947,'MAIC:BX:00947',3,NULL,NULL,NULL,'voltage ramp -100 to +100 mV over 1 s at 0.2 Hz | MODULATOR: GSK1016790A (agonist) 3 nM','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL','HrMVEC (human retinal microvascular endothelial cells, endogenous)','retinal microvascular endothelial cell',23.0,7.4,'150 NaCl, 3 KCl, 1 MgCl2, 2 CaCl2, 10 HEPES, 5.5 d-glucose, pH 7.4 (NaOH)','125 potassium gluconate, 10 KCl, 1 MgCl2, 4 Mg-ATP, 0.6 Na-GTP, 5 BAPTA, 10 HEPES, pH 7.3 (KOH)',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00075','the GSK101‐dependent conductance exhibited modest outward rectification, reversal potential of 9.9 ± 7.1 mV','Results (TRPV4 is functionally expressed in human MVECs)','high','Paper explicitly describes ''modest outward rectification'' for GSK101-dependent whole-cell current; canonical TRPV4 I-V signature.','WHOLE_CELL, HrMVEC, endogenous hTRPV4, GSK101 (3 nM), voltage ramp -100 to +100 mV, room temp','10','LITERATURE','2026-11-08',51,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(948,'MAIC:BX:00948',3,NULL,NULL,NULL,'voltage steps at multiple patch potentials, single-channel I-V slope | STIMULUS: 0 to 60 mV | ERROR-AS-REPORTED: 7 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,118.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'118','pS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HCAEC (human coronary artery endothelial cells, lentiviral hTRPV4-GFP)','coronary artery endothelial cell',23.0,7.3,'135 KCl, 0.8 CaCl2, 1 MgCl2, 5 glucose, 5 EGTA, 5 HEPES, pH 7.3 (CsOH/KOH, final Cs+ 4 mM)','140 NaCl, 1 MgCl2, 10 HEPES, pH 7.4 (CsOH)',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00077','The calculated slope conductances in the membrane potential ranges of 0 to 60 and -40 to 0 mV averaged 118±7 (n=5) and 64±3 (n=5) pS, respectively','Results (Effect of AA on TRPV4 Single-Channel Currents in HCAECs)','high','Genuine unitary single-channel slope conductance of hTRPV4 in cell-attached patches on hTRPV4-overexpressing HCAECs. Two slope ranges reported because the I-V is outwardly rectifying. Bath high-K+ zeroes cell membrane potential so patch potential = -pipette voltage.','CELL_ATTACHED, hTRPV4-overexpressing HCAEC, normal extracellular pipette (140 Na+, 5 Cs+), high-K+ bath (140 K+) to null membrane potential, room temp','5','LITERATURE','2026-11-08',53,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(949,'MAIC:BX:00949',3,NULL,NULL,NULL,'voltage steps at multiple patch potentials, single-channel I-V slope (negative branch) | STIMULUS: -40 to 0 mV | ERROR-AS-REPORTED: 3 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,64.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'64','pS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HCAEC (human coronary artery endothelial cells, lentiviral hTRPV4-GFP)','coronary artery endothelial cell',23.0,7.3,'135 KCl, 0.8 CaCl2, 1 MgCl2, 5 glucose, 5 EGTA, 5 HEPES, pH 7.3 (CsOH/KOH, final Cs+ 4 mM)','140 NaCl, 1 MgCl2, 10 HEPES, pH 7.4 (CsOH)',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00078','The calculated slope conductances in the membrane potential ranges of 0 to 60 and -40 to 0 mV averaged 118±7 (n=5) and 64±3 (n=5) pS, respectively','Results (Effect of AA on TRPV4 Single-Channel Currents in HCAECs)','high','Negative-branch unitary slope conductance of the same outwardly rectifying hTRPV4 single-channel I-V.','CELL_ATTACHED, hTRPV4-overexpressing HCAEC, normal extracellular pipette (140 Na+, 5 Cs+), high-K+ bath (140 K+) to null membrane potential, room temp','5','LITERATURE','2026-11-08',53,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(950,'MAIC:BX:00950',3,NULL,NULL,NULL,'patch potential varied; E_rev of unitary current','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0','mV',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HCAEC (human coronary artery endothelial cells, lentiviral hTRPV4-GFP)','coronary artery endothelial cell',23.0,7.3,'135 KCl, 0.8 CaCl2, 1 MgCl2, 5 glucose, 5 EGTA, 5 HEPES, pH 7.3 (CsOH/KOH, final Cs+ 4 mM)','140 NaCl, 1 MgCl2, 10 HEPES, pH 7.4 (CsOH)',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00079','single-channel current openings were detected at different patch potentials with a reverse potential of 0 mV','Results (Effect of AA on TRPV4 Single-Channel Currents in HCAECs)','medium','E_rev ≈ 0 mV reflects the asymmetric Na+(pipette)/K+(bath) ionic conditions and non-selective cation permeation of TRPV4; n inferred from same patch set as slope conductance (n=5).','CELL_ATTACHED, hTRPV4-overexpressing HCAEC, normal extracellular pipette (140 Na+, 5 Cs+), high-K+ bath (140 K+) to null membrane potential, room temp','5','LITERATURE','2026-11-08',53,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(951,'MAIC:BX:00951',3,NULL,NULL,NULL,'voltage steps at multiple patch potentials','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED','HCAEC (human coronary artery endothelial cells, lentiviral hTRPV4-GFP)','coronary artery endothelial cell',23.0,7.3,'135 KCl, 0.8 CaCl2, 1 MgCl2, 5 glucose, 5 EGTA, 5 HEPES, pH 7.3 (CsOH/KOH)','140 NaCl, 1 MgCl2, 10 HEPES, pH 7.4 (CsOH)',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00080','The calculated slope conductances in the membrane potential ranges of 0 to 60 and -40 to 0 mV averaged 118±7 (n=5) and 64±3 (n=5) pS, respectively','Results (Effect of AA on TRPV4 Single-Channel Currents in HCAECs)','high','Outward rectification inferred from the differing slope conductances in positive (118 pS) vs negative (64 pS) voltage ranges of the same single-channel I-V.','CELL_ATTACHED, hTRPV4-overexpressing HCAEC, Na+ pipette / high-K+ bath, room temp','5','LITERATURE','2026-11-08',53,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(952,'MAIC:BX:00952',3,NULL,NULL,NULL,'Voltage steps to construct single-channel I–V curve; junction-potential adjusted | MODULATOR: 4α-PDD 1 μM | ERROR-AS-REPORTED: 7 (sem)','CONDUCTANCE_ONLY',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,57.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'57','pS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED',NULL,'PVN parvocellular neurone',NULL,7.4,'ACSF (mM): 127 NaCl, 1.8 KCl, 1.2 KH2PO4, 2.4 CaCl2, 1.3 MgSO4, 26 NaHCO3, 5 glucose; 95% O2/5% CO2; pH 7.4','(mM) 35 K-gluconate, 5 KCl, 100 NaMeSO3, 10 HEPES; pH 7.4 with NaOH; ~300 mOsm',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00082','a TRP-like channel was identified in 50% of recordings (8/16) with a conductance of 57 ± 7 pS and V_rev of -5 ± 3 mV (Figure 3A and B; n = 6; adjusted for junction potential)','Results (Identification of TRPV4 channels by single-channel recordings)','medium','Genuine unitary single-channel slope conductance from cell-attached patches on endogenous TRPV4-like channel in PVN parvocellular neurones; channel identity supported by 4α-PDD-induced 48 ± 9% increase in P0 but not confirmed in TRPV4 KO, hence medium confidence. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','Cell-attached single-channel recording; mouse hypothalamic slice; parvocellular PVN neurone; voltage-step IV; TRP-like channel identified by 4α-PDD (1 μM)-induced increase of P0','6','LITERATURE','2026-11-08',55,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(953,'MAIC:BX:00953',3,NULL,NULL,NULL,'Voltage steps to construct single-channel I–V curve; junction-potential adjusted | MODULATOR: 4α-PDD 1 μM | ERROR-AS-REPORTED: 3 (sem)','FULL_CARD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-5.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-5','mV',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'CELL_ATTACHED',NULL,'PVN parvocellular neurone',NULL,7.4,'ACSF (mM): 127 NaCl, 1.8 KCl, 1.2 KH2PO4, 2.4 CaCl2, 1.3 MgSO4, 26 NaHCO3, 5 glucose; 95% O2/5% CO2; pH 7.4','(mM) 35 K-gluconate, 5 KCl, 100 NaMeSO3, 10 HEPES; pH 7.4 with NaOH; ~300 mOsm',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00083','a TRP-like channel was identified in 50% of recordings (8/16) with a conductance of 57 ± 7 pS and V_rev of -5 ± 3 mV (Figure 3A and B; n = 6; adjusted for junction potential)','Results (Identification of TRPV4 channels by single-channel recordings)','medium','Single-channel reversal potential (zero-current intercept) of endogenous TRPV4-like channel; value near 0 mV is consistent with non-selective cation channel and supports TRPV4 identity; not confirmed in TRPV4 KO. [F-004:verbatim-semi] '';'' junction(s) confirmed in archived corpus (classified 2026-08-31)','Cell-attached single-channel recording; mouse hypothalamic slice; parvocellular PVN neurone; voltage-step IV; TRP-like channel identified by 4α-PDD (1 μM)-induced increase of P0','6','LITERATURE','2026-11-08',55,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(954,'MAIC:BX:00954',3,NULL,NULL,NULL,'Voltage ramp from -80 mV to +80 mV; holding between ramps at -80/-60/-40 mV | MODULATOR: GSK1016790A (agonist) 100 nM | ERROR-AS-REPORTED: 0.4 (sem)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-1.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1.0','mV',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'PDGFRα+ interstitial cell (detrusor)',30.0,7.4,'CaPSS (mM): NaCl 135, KCl 5, MgCl2 1.2, CaCl2 2, Glucose 10, HEPES 10; pH 7.4 with Tris-base','(mM) CsCl 135, CaCl2 0.012, MgATP 3, Na2GTP 0.1, creatine phosphate disodium 2.5, EGTA 0.1, glucose 10, HEPES 10; pH 7.2 with Tris-base',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00090','GSK activated non-selective cation currents with a reversal potential of -1.0 ± 0.4 mV','Results (Effects of TRPV4 agonist and antagonists on PDGFRα+ cells)','medium','Macroscopic (whole-cell) TRPV4 current reversal potential, near 0 mV as expected for non-selective cation channel. Not unitary conductance. Current blocked by HC-067047 and RN-1734 and absent in Trpv4-/- cells, supporting TRPV4 identity.','PDGFRα+ interstitial cells from mouse detrusor muscle; whole-cell voltage clamp; Cs-rich pipette to block K+ currents; ramp -80 to +80 mV; 100 nM GSK1016790A','12','LITERATURE','2026-11-08',58,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(955,'MAIC:BX:00955',3,NULL,NULL,NULL,'Voltage ramp from -80 mV to +80 mV; holding -40 mV; UCL1684 1 μM pre-applied to block SK channels and unmask pure TRPV4 inward current | MODULATOR: GSK1016790A 100 nM | ERROR-AS-REPORTED: 0.6 (sem)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-1.9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-1.9','mV',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'PDGFRα+ interstitial cell (detrusor)',30.0,7.4,'CaPSS (mM): NaCl 135, KCl 5, MgCl2 1.2, CaCl2 2, Glucose 10, HEPES 10; pH 7.4 with Tris-base','(mM) KCl 135, CaCl2 0.012, MgATP 3, Na2GTP 0.1, creatine phosphate disodium 2.5, EGTA 0.1, glucose 10, HEPES 10; pH 7.2 with Tris-base',-40.0,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00091','GSK in the presence of UCL1684 (1 μM) activated inward current (122 ± 72 pA, n = 6), but no outward current, at a holding potential of -40 mV. The inward current reversed at -1.9 ± 0.6 mV','Results (Effects of TRPV4 agonist and antagonists on PDGFRα+ cells)','medium','Macroscopic reversal potential of TRPV4-only inward current unmasked by blocking SK channels with UCL1684; value close to the Cs-pipette macroscopic reversal, consistent with non-selective cation current. Current subsequently fully blocked by HC-067047. n=6 in the quote is the amplitude n of the UCL1684-isolated GSK inward current; the reversal-potential n is 5 per Fig. 3g,h.','PDGFRα+ interstitial cells from mouse detrusor muscle; whole-cell voltage clamp; K-rich pipette; 1 μM UCL1684 (SK blocker) pre-treatment to isolate TRPV4 current; ramp -80 to +80 mV; 100 nM GSK1016790A','5','LITERATURE','2026-11-08',58,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(956,'MAIC:BX:00956',3,NULL,NULL,NULL,'moderately high temperature (MHT) bath perfusion 37~39°C; ramp-like pulses from -100 to +80 mV (0.36 V/s), no fixed holding potential | ERROR-AS-REPORTED: 1.1 (sem)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-4.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-4.1','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'HMC-1 (human mast cell line)',38.0,7.2,'HEPES-buffered normal Tyrode: 3.6 KCl, 145 NaCl, 1 MgCl2, 5 glucose, 10 HEPES (mM), pH 7.2 with NaOH','145 Cs-glutamate, 8 NaCl, 1 MgCl2, 10 HEPES, 1 EGTA, 2 MgATP (mM), pH 7.2 with CsOH',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00092','The I/V curves of MHT-induced current were weakly outward rectifying, and crossed the control I/V curve at -4.1±1.1 mV','Results (Heat-evoked currents in HMC-1 cells, Fig. 1A)','medium','I/V curve crossing point of MHT-induced current vs control, interpreted as the reversal potential of the thermo-activated endogenous TRPV4 current. Whole-cell macroscopic ramp I/V (not single-channel). Membrane conductance reported by the paper is macroscopic (excluded per brief).','WHOLE_CELL, HMC-1 human mast cell line, endogenous TRPV4, moderately high temperature (MHT) 37~39°C, ramp -100 to +80 mV, large-response group','21','LITERATURE','2026-11-08',59,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(957,'MAIC:BX:00957',3,NULL,NULL,NULL,'MHT bath perfusion 37~39°C; ramp-like pulses from -100 to +80 mV | ERROR-AS-REPORTED: 3.4 (sem)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,-19.7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-19.7','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'HMC-1 (human mast cell line)',38.0,7.2,'HEPES-buffered normal Tyrode: 3.6 KCl, 145 NaCl, 1 MgCl2, 5 glucose, 10 HEPES (mM), pH 7.2 with NaOH','145 Cs-glutamate, 8 NaCl, 1 MgCl2, 10 HEPES, 1 EGTA, 2 MgATP (mM), pH 7.2 with CsOH',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00093','The other HMC-1 cells tested for MHT showed only a slight increase of membrane conductance, which crossed the control I/V curve at -19.7±3.4 mV','Results (Heat-evoked currents in HMC-1 cells, Fig. 1B)','medium','I/V curve crossing point in the small-response subgroup (weak activation), interpreted as reversal potential of the weakly-activated endogenous TRPV4-containing current. Whole-cell macroscopic.','WHOLE_CELL, HMC-1 human mast cell line, endogenous TRPV4, MHT 37~39°C, ramp -100 to +80 mV, small-response group','19','LITERATURE','2026-11-08',59,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(958,'MAIC:BX:00958',3,NULL,NULL,NULL,'1 µM 4α-PDD (TRPV4-selective agonist) at room temperature; ramp-like pulses from -100 to +80 mV | MODULATOR: 4α-PDD (agonist) 1 µM | ERROR-AS-REPORTED: 0.7 (sem)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3.5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'3.5','mV','OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'HMC-1 (human mast cell line)',24.0,7.2,'HEPES-buffered normal Tyrode: 3.6 KCl, 145 NaCl, 1 MgCl2, 5 glucose, 10 HEPES (mM), pH 7.2 with NaOH','145 Cs-glutamate, 8 NaCl, 1 MgCl2, 10 HEPES, 1 EGTA, 2 MgATP (mM), pH 7.2 with CsOH',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00094','the I/V curve of the 4αPDD-activated current crossed the control I/V curve at 3.5±0.7 mV','Results (4α-PDD activation, Fig. 2D)','medium','I/V curve crossing point of 4α-PDD-activated current vs control, interpreted as reversal potential of the 4α-PDD-activated endogenous TRPV4 current. Whole-cell macroscopic. Authors note this E_rev (3.5 mV) is more positive than the MHT-induced E_rev (-4.1 mV), suggesting the two activators recruit additional current components.','WHOLE_CELL, HMC-1 human mast cell line, endogenous TRPV4, 1 µM 4α-PDD agonist, room temperature, ramp -100 to +80 mV','12','LITERATURE','2026-11-08',59,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(959,'MAIC:BX:00959',3,NULL,NULL,NULL,'MHT bath perfusion 37~39°C; ramp-like pulses from -100 to +80 mV',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'OUTWARD_RECTIFYING',NULL,'OTHER',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'HMC-1 (human mast cell line)',38.0,7.2,'HEPES-buffered normal Tyrode: 3.6 KCl, 145 NaCl, 1 MgCl2, 5 glucose, 10 HEPES (mM), pH 7.2 with NaOH','145 Cs-glutamate, 8 NaCl, 1 MgCl2, 10 HEPES, 1 EGTA, 2 MgATP (mM), pH 7.2 with CsOH',NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00095','The I/V curves of MHT-induced current were weakly outward rectifying','Results (Heat-evoked currents in HMC-1 cells, Fig. 1A)','high','Verbatim I/V-shape descriptor. Paper says ''weakly outward rectifying''; mapped to schema enum OUTWARD_RECTIFYING (no WEAKLY_ variant in the enum). The same descriptor is repeatedly used for HT-induced, VHT-induced and 4α-PDD-induced currents.','WHOLE_CELL, HMC-1 human mast cell line, endogenous TRPV4, MHT 37~39°C, ramp -100 to +80 mV, large-response group','21','LITERATURE','2026-11-08',59,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "biophysics_experiment" VALUES(960,'MAIC:BX:00960',3,NULL,NULL,NULL,'hypoosmolar challenge or 4α-PDD agonist (abstract does not disambiguate which stimulus was used for the E_rev measurement); current is HC-067047-sensitive | MODULATOR: 4α-PDD (agonist) | ERROR-AS-REPORTED: 6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,31.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'31','mV','HYPOTONIC',NULL,NULL,NULL,NULL,NULL,NULL,'WHOLE_CELL',NULL,'human cultured white adipocytes',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'TRPV4-EX-00096','The current had a reverse potential of +31 ± 6 mV and exhibited preferential permeability to Ca2+','Abstract','medium','Abstract-only access (no PMCID; is_oa=false, oa_url empty). Error type (SEM vs SD), n, bath/pipette solutions, and holding potential are not specified in the abstract. Whole-cell patch-clamp reversal potential of the HC-067047-sensitive endogenous TRPV4 current. The positive E_rev (+31 mV) is consistent with TRPV4''s reported Ca2+ preference; the abstract states ''preferential permeability to Ca2+'' only qualitatively (no P_Ca/P_Na ratio given), so ion_selectivity=N.','WHOLE_CELL, human cultured white adipocytes, endogenous TRPV4, hypoosmolarity or 4α-PDD agonist, HC-067047-sensitive current',NULL,'LITERATURE','2026-11-08',60,'2026-11-08 00:00:00.000000',NULL);
