INSERT INTO "unmapped_measurement" VALUES(26,'MAIC:UM:00026',3,'x50',252.0,'nm','KEEP: demoted-contested (combined TRPV4+PIEZO1 current, not channel-isolated)','TRPV4-EX-00036','The threshold for chondrocytes, 252 +/- 68 (n = 24) was significantly higher than that calculated for dedifferentiated cells 59 +/- 13 (n = 15).','Fig 5 (deflection thresholds)','low','deflection threshold (nm); unit recorded as nm (IndentationUnit). Direct mechano-gating contested; deflection current = combined TRPV4+PIEZO1 (blocked by GSK205). Stretch P50 (87.1 mmHg) is PIEZO1-mediated -> NOT emitted as TRPV4. RT [demoted: combined TRPV4+PIEZO1 deflection current, not TRPV4-isolated]','whole-cell, primary mouse chondrocytes, pillar deflection, RT','24','LITERATURE','2026-11-08',18,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "unmapped_measurement" VALUES(27,'MAIC:UM:00027',3,'x50',59.0,'nm','KEEP: demoted-contested (combined TRPV4+PIEZO1 current, not channel-isolated)','TRPV4-EX-00037','The threshold for chondrocytes, 252 +/- 68 (n = 24) was significantly higher than that calculated for dedifferentiated cells 59 +/- 13 (n = 15).','Fig 5 (deflection thresholds)','low','deflection threshold (nm), dedifferentiated cells; direct gating contested [demoted: combined TRPV4+PIEZO1 deflection current, not TRPV4-isolated]','whole-cell, dedifferentiated cells, pillar deflection, RT','15','LITERATURE','2026-11-08',18,'2026-11-08 00:00:00.000000',NULL);
INSERT INTO "unmapped_measurement" VALUES(28,'MAIC:UM:00028',3,'tau_act',1.7,'ms','KEEP: demoted-contested (direct gating contested)','TRPV4-EX-00038','chondrocyte currents: latency = 3.6 +/- 0.3 ms, activation time constant (tau1) = 1.7 +/- 0.3 ms (mono-exponential fit).','Fig 8C (activation kinetics)','low','tau_act=tau1 1.7+/-0.3 ms (mono-exponential); latency 3.6+/-0.3 ms noted separately. Direct gating contested (deflection current). tau2 (decay) reported only as a significance test with NO numeric value -> tau_inact Y-flag yields no numeric row (figure-only) [demoted: combined TRPV4+PIEZO1 deflection current, not TRPV4-isolated]','whole-cell, chondrocyte deflection-gated current, RT',NULL,'LITERATURE','2026-11-08',18,'2026-11-08 00:00:00.000000',NULL);
